(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,40958,(A,n,N)=>{n.exports=JSON.parse('[{"모듈":"홈","코드":"HOM","개요":"AGENTBASE 접속 시 시작 지점이다. 오케스트레이터가 연결되어 있으면 자연어로 작업을 요청받고, 연결되어 있지 않으면 작업 현황을 위젯으로 요약하며, 구성원은 위젯 구성을 바꾼다.","상태":[],"공통":["홈 위젯은 오케스트레이터 연결 여부로 갈린다. 연결되어 있으면 입력 위젯(오케스트레이터로 시작하기, 추천 아이디어, 최근 요청), 없으면 작업 전환 위젯(승인 대기, 문제 발생, 실행중 작업, 자원 대기 작업, GPU 사용, 상용 API 비용, 워크플로우 호출 순위, 접속 중)이다.","위젯 배치는 GPUBASE 계정의 구분(관리자, AI 개발자)마다, 그리고 오케스트레이터 연결 여부마다 따로 저장한다. 관리자로 지정된 AI 개발자는 관리자 배치를 쓴다.","두 구분의 위젯 목록과 처음 배치는 같고, 승인 대기 위젯의 내용만 다르다.","위젯 숫자는 상단바 갱신 주기마다 다시 모은다.","오케스트레이터가 실행하는 일은 입력한 구성원의 권한으로 판정하고, 오케스트레이션 실행 중에는 모든 화면이 보기 전용이다."],"기능":[{"묶음":"작업 시작","fn":"FN-HOM-001","이름":"오케스트레이터로 시작하기","동작":"구성원이 데이터, 모델, RAG, 도구, 워크플로우 가운데 만들 작업 유형을 고르면 → 오케스트레이터가 만들 구성을 제안하고 → 구성원이 확인하면 생성한다.","규칙":["오케스트레이터가 연결되어 있을 때만 있다.","생성 뒤 자원을 점유하는 일(배포, 학습)은 입력자의 권한으로 판정하고 권한이 없으면 요청 단계에서 멈춘다."],"엣지":[],"미정":[]},{"묶음":"작업 요청","fn":"FN-HOM-002","이름":"작업 요청 입력","동작":"구성원이 홈 입력 칸에 요청을 넣으면 → 오케스트레이터 대화가 시작되고 → 처리 결과를 대화에서 확인한다.","규칙":["오케스트레이터가 연결되어 있을 때만 있다. 연결되어 있지 않으면 입력 칸을 두지 않는다.","오케스트레이션이 끝나면 요청자 본인에게만 작업 종료 알림이 간다."],"엣지":[],"미정":[]},{"묶음":"홈 위젯","fn":"FN-HOM-003","이름":"홈 구성 전환","동작":"시스템이 오케스트레이터 연결 상태를 확인해 → 연결되어 있으면 입력 위젯 배치를, 아니면 작업 전환 위젯 배치를 홈에 보인다.","규칙":["위젯 갤러리는 지금 연결 상태의 위젯만 보인다."],"엣지":["오케스트레이터 연결이 끊기면 작업 전환 위젯 배치로 바뀌고, 입력 위젯 배치는 다시 연결될 때 쓴다."],"미정":[]},{"묶음":"홈 위젯","fn":"FN-HOM-004","이름":"위젯 편집","동작":"구성원이 위젯을 추가·제외하고 크기와 차례를 바꾸면 → 그 구분·그 구성의 배치로 저장된다. [처음 배치로]는 그 구분·그 구성의 처음 배치로 되돌린다.","규칙":["같은 위젯은 한 번만 놓는다.","배치는 이 브라우저에 남는다."],"엣지":["다른 브라우저에서는 처음 배치로 보인다.","구분이 바뀐 직후에는 바뀐 구분의 배치를 연다. 앞 구분에서 고친 배치는 다시 그 구분이 되면 돌아온다."],"미정":["홈 배치를 브라우저가 아니라 계정에 저장할지(대시보드 템플릿은 계정마다 저장)"]},{"묶음":"홈 위젯","fn":"FN-HOM-005, FN-HOM-006","이름":"추천 아이디어 요청과 최근 요청 실행","동작":"구성원이 추천 요청 문장이나 최근 요청을 고르면 → 그 문장을 오케스트레이터에 그대로 보내 바로 요청한다.","규칙":["오케스트레이터가 연결되어 있을 때만 있다.","최근 요청은 이력을 보는 자리가 아니라 다시 보내는 자리다."],"엣지":[],"미정":["최근 요청의 보관 개수와 범위(구성원마다인지)"]},{"묶음":"홈 위젯","fn":"FN-HOM-007","이름":"승인 대기 조회","동작":"승인 대기 위젯은 관리자에게 검토할 요청 수와 목록을, AI 개발자에게 승인을 기다리는 내 요청을 보인다. 위젯을 누르면 알림 패널이 열리고 보던 홈은 그대로다.","규칙":["자원 한도 변경 요청은 관리자의 검토할 요청에 넣지 않는다."],"엣지":[],"미정":[]},{"묶음":"홈 위젯","fn":"FN-HOM-008","이름":"문제 발생 조회","동작":"문제 발생 위젯은 실패한 작업 수와 최근 실패 작업을 보인다. 누르면 시스템 자원 관리 작업 목록이 실패로 걸러져 열린다.","규칙":["시스템 자원 관리 작업 목록과 같은 셈이다."],"엣지":[],"미정":[]},{"묶음":"홈 위젯","fn":"FN-HOM-009","이름":"GPU 사용 조회","동작":"GPU 사용 위젯은 할당된 GPU 의 사용률과 노드 풀별 점유를 보인다.","규칙":["시스템 자원 관리 GPU 카드와 같은 값이다."],"엣지":[],"미정":["(N-18) 실패한 채 GPU 를 잡은 작업을 점유로 셀지(권장: 실패는 늘 반환, 셈에서 걷음)"]},{"묶음":"홈 위젯","fn":"FN-HOM-010","이름":"워크플로우 호출 순위 조회","동작":"워크플로우 호출 순위 위젯은 서비스 API 로 오픈한 워크플로우를 최근 30일 서비스 API 호출 수 차례로 보인다.","규칙":["호출 수는 서비스 API 로 들어온 호출만 센다. 테스트 호출은 넣지 않는다."],"엣지":[],"미정":[]},{"묶음":"홈 위젯","fn":"FN-HOM-011","이름":"실행중 작업 조회","동작":"실행중 작업 위젯은 실행중 작업 수와 GPU 를 쓰는 작업을 보인다. 누르면 시스템 자원 관리 작업 목록이 실행중으로 걸러져 열린다.","규칙":["상태가 실행중인 작업만 센다(학습, 전체 실행과 표본 실행, 검색 DB 생성과 업데이트).","배포중인 모델 배포, RAG, 도구, 데이터 파이프라인, 워크플로우와 서비스 API 오픈은 넣지 않는다."],"엣지":[],"미정":[]},{"묶음":"홈 위젯","fn":"FN-HOM-012","이름":"자원 대기 작업 조회","동작":"자원 대기 작업 위젯은 자원을 기다리는 작업과 작업마다 필요한 자원을 보인다. 학습과 모델 배포는 GPU, RAG·도구·데이터 파이프라인은 CPU 와 RAM 을 기다린다.","규칙":["시스템 자원 관리 자원 대기 작업과 같은 대상이다. 승인 대기와 실행 일정을 기다리는 데이터 파이프라인은 넣지 않는다."],"엣지":[],"미정":[]},{"묶음":"홈 위젯","fn":"FN-HOM-013","이름":"상용 API 비용 조회","동작":"상용 API 비용 위젯은 이번 달 1일부터 마지막 수집 시각까지의 상용 API 모델 비용 합계와 모델별 비용을 보인다.","규칙":["비용은 공급사의 입력·출력 토큰 요금을 원으로 바꾼 값이다.","대시보드 상용 API 비용과 같은 값이다."],"엣지":[],"미정":["공급사 요금을 모으는 주기"]},{"묶음":"홈 위젯","fn":"FN-HOM-014","이름":"접속 현황 조회","동작":"접속 중 위젯은 지금 접속한 구성원 수와 관리자 접속 여부를 보인다.","규칙":["상단바 접속자와 같은 값이다."],"엣지":[],"미정":[]}]},{"모듈":"대시보드","코드":"DSH","개요":"구성원이 고른 템플릿(대시보드)에 서비스 성과, 자원, 비용, 개발 작업 위젯을 배치해 운영 상태를 요약한다. 템플릿 하나가 대시보드 하나이자 저장된 보기다.","상태":[],"공통":["대시보드는 템플릿 단위다. 템플릿을 고르면 그 배치와 위젯 설정이 열린다.","기본 제공 템플릿은 관리자 여섯(운영 관리, 경영 요약, 서비스 성과, 자원 관리, AI 개발자 기본, 데이터 작업), AI 개발자 둘(AI 개발자 기본, 데이터 작업)이다.","구성원은 새 템플릿을 저장하거나 기본 제공 템플릿을 고쳐 덮어쓴다. 템플릿은 계정마다 저장한다.","관리자인 계정은 관리자 기본 템플릿, AI 개발자는 AI 개발자 기본 템플릿으로 시작한다. 관리자로 지정된 AI 개발자는 관리자 템플릿을 쓴다.","AI 개발자도 관리자와 같은 위젯을 모두 고를 수 있다.","편집은 편집 화면에서 한다. 편집 중 초안은 자동으로 남고 [저장]하면 지운다. 저장하지 않고 나갔다가 다시 편집하면 초안을 이어 쓴다.","같은 위젯도 설정을 달리해 여러 개 놓을 수 있다. 위젯마다 작게·보통·크게 꼴이 있고 크기를 바꾸면 들어가는 가장 큰 꼴로 바뀐다.","기본 제공 템플릿을 지우면 숨김이고, 마지막 남은 템플릿은 지울 수 없다.","수는 머리 기간 필터(처음 값 최근 30일)의 합이고, 위젯 설정에서 기간을 고정한 위젯은 그 기간이다.","GPUBASE 그룹 관리자의 관리자 대시보드는 시스템 관리자와 같은 전체 범위다.","화면 ID 는 대시보드 하나이고 위젯 편집 판과 위젯 추가 창만 따로다. 기능 ID 는 위젯마다 따로 둔다."],"기능":[{"묶음":"서비스 현황","fn":"FN-DSH-001","이름":"서비스 지표 조회","동작":"요약 지표, 서비스 이용, 서비스 만족도, 서비스 사용자 위젯이 선택한 기간의 요청 수, 성공 응답, 에러, 응답 시간, 만족도, 서비스 사용자 수를 집계해 보인다.","규칙":["만족도는 평가한 답변 가운데 좋아요 비율이다.","응답 시간은 성공 요청 기준이다.","서비스 이용은 요청 → 성공 응답 → 좋아요 전환율이다.","서비스 사용자는 서비스 사용자별 요청 순위다.","요약 지표 위젯은 지표를 최대 여섯까지 고른다."],"엣지":[],"미정":["(C-09) 권한·한도로 막힌 요청을 에러율에 넣을지"]},{"묶음":"서비스 현황","fn":"FN-DSH-002","이름":"워크플로우 운영 현황 조회","동작":"워크플로우 운영 현황 위젯은 서비스 API 로 오픈한 워크플로우마다 선택한 기간의 요청 수와 응답 시간을 비교하고 상용 API 호출 여부로 구분한다. 워크플로우 이용 순위 위젯은 호출 수 차례로 보인다.","규칙":["서비스 모니터링은 서비스 지표와 호출 자원 표까지 보이고, 원인은 워크플로우 모니터링으로 이동해 본다."],"엣지":[],"미정":[]},{"묶음":"자원 현황","fn":"FN-DSH-003","이름":"자원 사용 현황","동작":"GPU, CPU, RAM, 스토리지 위젯은 사용률과 점유(스토리지는 사용) 상위 작업을 보인다. 자원 가용성 위젯은 노드 풀별 GPU 와 CPU·RAM·스토리지의 잔여와 대기 요청을 보인다.","규칙":["시스템 자원 관리 자원 카드와 같은 값이다.","상위 작업은 위젯 설정에서 3개나 5개(처음 값 5)를 고른다."],"엣지":[],"미정":["(N-18) 실패한 채 자원을 잡은 작업을 점유와 「호출 없는 점유」로 셀지"]},{"묶음":"자원 현황","fn":"FN-DSH-004","이름":"상용 API 비용 조회","동작":"상용 API 비용 위젯은 이번 달 1일부터 마지막 수집 시각까지 상용 API 모델 배포의 비용 합계, 모델별 비용, 비중을 보인다.","규칙":["비용은 공급사의 입력·출력 토큰 요금을 원으로 바꾼 값이다.","홈 상용 API 비용 위젯과 같은 값이다."],"엣지":[],"미정":["공급사 요금을 모으는 주기"]},{"묶음":"자원 현황","fn":"FN-DSH-005, FN-DSH-006, FN-DSH-007","이름":"모델 배포·RAG·도구 자원 대비 호출 조회","동작":"운영 현황 위젯은 모델 배포(점유 GPU), RAG(점유 CPU), 도구(점유 CPU)마다 점유한 자원 비중 대비 호출 비중을 비교해 정상, 경고, 위험으로 나눈다. 위젯 설정에서 대상(모델 배포, RAG, 도구)을 바꾼다.","규칙":["호출 비중 ÷ 자원 비중이 경고 기준 미만이면 경고, 위험 기준 이상이면 위험이다.","경고 기준은 0.3, 0.5, 0.7배 미만(처음 값 0.5), 위험 기준은 1.5, 2, 3배 이상(처음 값 1.5)에서 위젯마다 고른다.","주소만 등록한 외부 엔드포인트와 상용 API 는 모델 배포 대상에서 뺀다.","서비스 사용자의 개인 RAG 는 한 줄로 합쳐 보인다."],"엣지":[],"미정":[]},{"묶음":"위젯(기능정의서에 행 없음)","fn":"없음","이름":"템플릿 선택·저장·편집","동작":"구성원이 머리에서 템플릿을 바꾸면 그 대시보드가 열린다. 편집 화면에서 위젯을 추가·제외하고 크기와 자리를 바꾼 뒤 [저장]하거나 새 템플릿으로 저장한다.","규칙":["편집 화면 주소로 새로 고침해도 편집 화면이 유지된다."],"엣지":["관리자에서 AI 개발자로 바뀌면 관리자 기본 템플릿 넷은 빠지고 내가 저장한 템플릿은 남는다."],"미정":[]},{"묶음":"위젯(기능정의서에 행 없음)","fn":"없음","이름":"크레딧 사용량, 승인 대기, 실행 및 배포 중인 작업, 실행·배포 예정 작업, 조치 대상 작업, 라벨링 진행, 모델 평가 순위 위젯","동작":"크레딧 사용량은 모델·도구별 일별 크레딧, 승인 대기는 승인 대기 요청 목록, 실행 및 배포 중인 작업은 작업별 상태·진행률·경과 시간, 실행·배포 예정 작업은 예정 일시, 조치 대상 작업은 실패·대기·검수 대기·커밋 대기 작업, 라벨링 진행은 라벨링 작업별 진행률, 모델 평가 순위는 리더보드 등록 모델 배포의 종합 점수 순위를 보인다.","규칙":["작업 위젯은 위젯 설정에서 작업 유형과 기본 상태 필터를 고른다.","실행 작업은 경과 시간만 보이고 남은 시간은 계산하지 않는다."],"엣지":["대시보드에서 연 리더보드의 [리더보드 등록]·[등록 해제]는 고른 모델 배포가 없어 비활성이다."],"미정":[]}]},{"모듈":"데이터 파이프라인","코드":"DPL","개요":"원본 데이터를 처리 단계를 담은 노드의 그래프로 가공해 데이터셋 버전을 만든다. 배포로 실행 자원 한 벌을 점유하고 그 안에서 표본 실행과 전체 실행을 하며, 검수를 마친 실행 결과를 발행하면 데이터 관리에 데이터셋 버전 폴더가 생긴다.","상태":["생성됨·중지·실패 → [배포] → 설치중 → 배포중","생성됨·중지·실패 → [배포](자원 부족 또는 배포 예약) → 대기 → 자원 확보·예약 시각 → 설치중 → 배포중","생성됨·중지·실패 → [배포 요청](권한 없음) → 대기(승인 대기) → 관리자 승인 → 설치중 → 배포중","설치중 → 설치 실패 → 실패(자원 반환)","배포중 → [전체 실행]·실행 일정·표본 실행 → 실행중 → 배포중","실행중(전체 실행) → 라벨링 단계 도달 → 실행중(라벨링 대기) → 모든 항목 작업 완료 → 실행중 → 배포중","실행중(전체 실행) → [실행 중지] → 배포중(중간 산출물 보관 또는 삭제)","실행중(전체 실행) → 실행 실패 → 배포중(실행 결과 없음, 배포 회차 유지)","배포중 → [배포 중지] → 중지(자원 반환, 배포 회차 종료)","대기 → [배포 중지] → 중지(자원 대기·배포 예약 취소)","배포중(실행 일정 활성) → 다음 실행 일시를 기다림 → 대기 → 일정 시각 → 실행중 → 배포중","실행 결과(검수 대기 0건) → [발행] → 발행 중(결과 확인 → 파일 이동 → 버전 등록) → 데이터셋 버전 vN","발행 중 → [발행 취소] 또는 발행 실패 → 버전·버전 폴더 미생성, 실행 결과와 검수 판정 유지"],"공통":["권한이 필요한 조작은 [배포] 하나다. 컴퓨팅 자원 사용 권한이 없으면 배포 창이 곧 요청 창([배포 요청])이고, 메모와 자원·시점을 적어 보내며, 승인되면 요청한 값으로 바로 배포한다.","[배포 중지]는 요청을 거치지 않는다(배포 중지 요청은 없다). 자원 대기·배포 예약의 취소도 권한 없이 한다.","전체 실행, 표본 실행, 실행 중지, 예약 취소, 발행, 발행 취소, 설정 편집은 권한 없이 한다. 다른 구성원의 조작은 편집 점유가 막는다.","실행 자원 한 벌(노드 풀, GPU, CPU, RAM)은 [배포] 창에서만 정하고 [배포 중지]까지 점유한다. 모든 노드의 표본 실행과 전체 실행이 이 한 벌을 나눠 쓰고, 노드별 실행 자원은 없다. GPU 0이면 CPU와 RAM만 쓴다.","배포 중에는 실행 자원을 바꿀 수 없다. [배포 중지] 뒤 다시 [배포]하면 새 배포 회차가 열린다. 처음 배포 창은 빈칸이고, 다시 배포 창은 지난 자원 값을 채운다.","정보 탭의 실행 자원은 설치중, 배포중, 실행중일 때만 점유 값을 적고 그 밖에는 「실행 자원 -」 한 칸이다.","배포 회차는 [배포]로 배포중에 들어간 순간(요청이면 승인 뒤) 열리고 [배포 중지]나 실패로 끝난다. 0회차는 생성이다. 자원 대기, 대기 끝의 중지, 설치중 실패는 회차 번호가 없는 줄이다.","전체 실행, 표본 실행, 발행, 검수 판정, 라벨 저장은 회차를 새로 열지 않고 그 시각 배포 회차의 작업 내역 한 줄로 남는다. 전체 실행 줄은 실행 조건(수동 실행, 실행 일정)과 결과를 적는다.","실행 결과는 하나만 두고 데이터 파이프라인 안에 둔다. 다음 전체 실행이나 설정 변경 때 대체·삭제한다. 데이터 관리에는 발행한 데이터셋 버전 폴더만 생긴다.","데이터 파이프라인은 원본 데이터에 쓰지 않는다. 소스는 회차를 고정하지 않고 실행할 때의 최신 회차를 읽는다.","설정 탭 편집은 [편집]으로 편집 모드에 들어가는 순간 편집자가 되고 [편집 완료]로 끝난다. 정보 탭 수정과 설정 탭 편집은 같은 점유 하나다. 새로 만든 데이터 파이프라인은 생성자가 점유한 편집 모드로 열린다.","조작 없이 3분이 지나면 뷰어로 바뀌고(2분 30초에 「30초 뒤 뷰어로 전환합니다.」) [편집 완료]와 같이 처리한다. 설정은 자동 저장이라 남는다.","점유 중 다른 구성원에게는 수정, 삭제, 전체 실행, 실행 중지, 발행, 표본 실행, [배포 중지], 예약 취소를 비활성 + 「{이름}님이 편집 중입니다.」로 막는다. 조회, 필터, 버전 비교는 뷰어도 한다.","설정 편집은 배포 상태와 상관없이 한다. 배포 중에 바꾼 설정은 자동 저장되고 다음 전체 실행부터 반영한다.","[편집 완료] 때 설정이 처음과 달라졌으면 발행하지 않은 실행 결과와 그 검수 판정을 지우고 「설정이 변경되어 발행하지 않은 실행 결과를 삭제했습니다.」를 알린다. 이미 발행한 버전은 지우지 않는다.","실행 결과, 보관한 중간 산출물, 발행한 버전 폴더는 스토리지 사용량에 든다. 전체 실행 중 스토리지가 가득 차면 실행은 실패(사유 「스토리지 부족」)다.","데이터셋 새 버전이 생기면 그 데이터셋을 쓰는 작업마다 생성자와 관리자 전원에게 「데이터셋 새 버전」 알림을 한 건 보낸다. 전체 실행·발행이 끝나거나 실패하면 실행자와 관리자에게 작업 종료 알림을 보낸다.","작업 이력은 지우지 않는다. 관리 설정의 이력 표시 기간은 화면에 보이는 범위일 뿐이다.","막힌 조작은 숨기지 않고 비활성으로 두며, 먼저 걸린 이유 하나를 보인다."],"기능":[{"묶음":"데이터 파이프라인 목록","fn":"FN-DPL-001","이름":"데이터 파이프라인 목록 조회","동작":"사용자가 목록을 열면 데이터 파이프라인마다 상태, 이름, 설명, 실행 자원, 최근 업데이트 일시, 생성자를 보여 준다. 상태와 생성자로 거르고 이름이나 생성자로 검색한다. 상태 칩은 상세 머리와 같은 값이다.","규칙":["상태는 생성됨, 대기, 설치중, 배포중, 실행중, 중지, 실패다.","배포 중이고 실행 일정을 활성화한 수집 노드가 있으며 실행 중이 아니면 상태는 「대기」(다음 실행 대기)다.","목록 검색 대상은 이름과 생성자이고 설명은 검색하지 않는다.","목록 더보기 메뉴에는 배포 항목([배포], [배포 중지])을 두지 않는다. 배포와 중지는 상세에서만 한다.","목록 더보기의 [삭제]는 상세의 [삭제]와 같은 조건, 같은 문구로 막는다."],"엣지":["승인 대기 중인 배포 요청이 있으면 상태 칩은 대기이고, 자원을 점유한 상태에서 다른 요청이 대기 중이면 칩은 지금 상태 그대로다."],"미정":[]},{"묶음":"데이터 파이프라인 목록","fn":"FN-DPL-002","이름":"데이터 파이프라인 생성","동작":"사용자가 이름, 설명, 원본 데이터 폴더를 입력하고 [생성]하면 데이터 파이프라인과 같은 이름의 빈 출력 데이터셋을 만든다. 고른 폴더마다 데이터 형식에 맞는 소스 노드를 배치하고, 폴더를 고르지 않으면 빈 소스 노드 하나로 시작한다. 만든 직후 생성자가 점유한 편집 모드의 설정 탭이 열리고 상태는 생성됨이다.","규칙":["이름은 필수이고 같은 이름은 만들 수 없다.","원본 데이터 칸은 처음에 비어 있다.","생성 창에서는 실행 자원을 받지 않는다. 자원은 [배포] 창에서 받는다.","생성은 권한이 필요 없다."],"엣지":["고른 폴더가 비어 있어도 만들 수 있다. 전체 실행은 「원본 폴더에 파일이 없습니다. 소스 노드의 폴더에 데이터를 업로드한 뒤 실행합니다.」로 막힌다."],"미정":[]},{"묶음":"설정","fn":"FN-DPL-003","이름":"설정 그래프 조회","동작":"설정 탭을 열면 노드마다 이름, 포함한 처리 단계, 실행 상태를 그래프로 보여 준다. 노드를 고르면 처리 단계를 차례대로 단계 이름과 처리 내용으로 보여 준다. 조회는 뷰어도 한다.","규칙":["노드 유형 차례는 소스, 분석, 라벨링, 전처리, AI, 필터, 흐름, 출력이다.","마지막 전체 실행을 마친 노드는 편집 모드가 아닐 때 「완료」를 표시한다.","단계가 없는 노드는 「단계가 없습니다.」를 표시한다.","설정 점검(단계 미선택, 모델 미선택, 필수 칸 미입력)은 전체 실행 전에 고칠 목록으로 함께 보인다."],"엣지":[],"미정":[]},{"묶음":"설정","fn":"FN-DPL-004","이름":"설정 편집","동작":"사용자가 [편집]으로 편집 모드에 들어가 단계를 추가하면, 선택한 노드와 유형이 같으면 그 노드의 마지막 단계로, 다르거나 선택한 노드가 없으면 새 노드로 만들어 선택한 노드 뒤에 연결한다. 단계 순서 변경, 단계 삭제, 노드 삭제와 [되돌리기], [다시 실행]을 하고, 바꾼 내용은 바로 자동 저장되어 다음 전체 실행부터 반영한다. [편집 완료]로 편집을 끝낸다.","규칙":["유형이 다른 노드로 옮긴 단계는 거부한다.","적용할 수 없는 단계는 비활성으로 두고 이유를 보인다(「{대상}은 {조건}에 사용할 수 있습니다. 앞 단계 출력은 {유형} 데이터입니다.」 꼴).","전체 실행 중(라벨링 대기 포함)에는 [편집]을 막는다(「실행 중에는 편집할 수 없습니다. 실행이 끝나거나 중지하면 편집할 수 있습니다.」).","발행 중에는 [편집]을 막는다(「발행하는 동안에는 편집할 수 없습니다. 발행이 끝난 뒤 편집합니다.」).","실행이 예약되어 있으면 [편집]을 막는다(「실행이 예약되어 있어 편집할 수 없습니다. [예약 취소]한 뒤 편집합니다.」).","설정 탭이 아니면 [편집]을 막는다(「설정 탭에서만 편집할 수 있습니다.」).","다른 구성원이 편집 중이면 [편집]을 막는다(「{이름}님이 편집 중입니다.」).","편집 중에는 [되돌리기], [다시 실행], [편집 완료]만 남고 [전체 실행], [발행]은 없다.","조작 없이 3분이 지나면 편집을 끝내고(2분 30초에 미리 알림) [편집 완료]와 같이 처리한다."],"엣지":["[편집 완료] 때 설정이 처음과 다르면 발행하지 않은 실행 결과와 검수 판정을 지운다. 편집만 열고 바꾸지 않았으면 지우지 않는다.","3분 무조작으로 끝난 경우도 설정이 바뀌었으면 같은 규칙으로 미발행 결과와 판정을 지운다.","표본 실행 중에는 [편집 완료]와 탭 이동을 막는다(「표본 실행 중입니다. 끝나거나 [중지]한 뒤 편집을 완료합니다.」).","수집 노드 실행 일정을 바꿨으면 [편집 완료] 때 작업 이력에 「설정 변경」 한 줄을 남긴다."],"미정":["전체 실행 예약을 걷으면 예약 중 편집 차단도 함께 걷힌다(C-18)."]},{"묶음":"설정","fn":"FN-DPL-005","이름":"노드 설정","동작":"사용자가 처리 단계를 골라 입력 열, 결과 열, 처리 방식, 실행 값을 입력하면 [적용] 없이 바로 설정에 반영한다. 열은 앞 단계 출력의 열에서 고른다. 실행을 막는 값이 있으면 칸들 아래 한 줄로 이유를 보이고 전체 실행을 막는다.","규칙":["열 정보를 실행 뒤에야 아는 소스 뒤에서는 막지 않고 「열 이름」 입력 칸을 둔다.","AI 단계는 AGENTBASE 모델 배포나 등록한 Custom 모델에서 고른다. GPUBASE 워크로드 주소를 직접 등록하지 않는다.","고른 모델 배포가 운영 중이 아니면 전체 실행을 막는다.","단계별 칸은 노드 유형, 전처리 단계, AI 단계, 라벨링 유형 묶음이 정한다.","막힘 문장, 비활성 선택지 말풍선, 전체 실행 막힘은 같은 판정의 같은 문장이다."],"엣지":["앞 단계를 바꿔 고른 열이 사라지면 그 칸은 미입력으로 돌아가고 전체 실행이 막힌다."],"미정":[]},{"묶음":"설정","fn":"FN-DPL-006, FN-DPL-007","이름":"표본 실행, 표본 실행 중지","동작":"배포중인 데이터 파이프라인에서 노드 미리보기의 [이 노드까지 표본 실행]으로 표본 방식과 표본 크기를 고르면, 소스부터 선택한 노드(또는 단계)까지 원본 일부를 배포한 실행 자원으로 처리해 미리보기에 보여 준다. 진행 중에는 [중지]로 멈춘다. 결과는 미리보기에만 남고 데이터셋 버전을 만들지 않으며 원본 데이터에 적재하지 않는다.","규칙":["배포중일 때만 한다. 편집 모드가 아니어도 된다.","표본 방식은 앞쪽, 무작위다.","표본 크기는 표 소스(테이블 파일, 데이터베이스 조회) 100·500·1,000행, 파일 소스 20·50·100개다.","전처리 단계는 방식마다 변환 결과를 계산해 보인다.","미배포·대기·설치중이면 막고 배포 상태별 이유를 보인다.","전체 실행 중에는 막는다(「전체 실행 중에는 표본 실행할 수 없습니다.」).","다른 노드의 표본 실행이 진행 중이면 막는다(한 번에 하나).","다른 구성원이 편집 중이면 막는다.","단계가 없는 노드는 막는다(「이 노드에는 단계가 없습니다.」).","실행 자원 칸은 보기 전용이다(「변경하려면 배포를 중지한 뒤 다시 배포합니다.」).","작업 이력에는 회차 번호 없이 지금 배포 회차의 작업 내역 한 줄로 남는다."],"엣지":["표본 실행 중에는 [배포 중지], 삭제, [편집 완료], 탭 이동을 막는다.","표본 실행 중지는 확인 없이 멈추고 그때까지의 표본 결과는 버린다."],"미정":[]},{"묶음":"설정","fn":"FN-DPL-072","이름":"출력 열 확인","동작":"데이터베이스 조회나 외부 서버 파일 단계에서 [열 확인]을 누르면 표본을 조회해 출력 열을 확정하고, 뒤 단계의 열 선택을 확정한 열로 제한한다. 조회 대상을 바꾸면 확정을 풀고 다시 확인해야 한다.","규칙":["확인 전 표시는 「열 확인 전」, 확인 뒤는 「열 n개 확인」이다.","확인 전 뒤 단계의 열 칸은 열 이름 입력이다.","조회 대상이 비어 있으면 막는다(「{조회 대상}을 입력해야 열을 확인할 수 있습니다.」).","이미지, 오디오, 비디오, 문서 형식의 외부 서버 파일은 파일 목록이라 열 확인이 없다."],"엣지":[],"미정":[]},{"묶음":"설정","fn":"FN-DPL-073","이름":"적재 데이터 조회","동작":"소스 노드의 수집 단계나 파일 단계를 고르면 표본 실행 없이 그 단계가 원본 데이터에 적재한(읽는) 데이터를 행 수나 파일 수와 함께 미리보기에 보여 준다. 적재한 데이터가 없으면 수집한 데이터가 없다고 안내한다.","규칙":["웹 크롤링(JSONL)과 데이터베이스 조회(parquet)는 행, 외부 서버 파일은 받은 파일 목록을 보인다.","표본 실행 결과가 있으면 표본 실행 결과를 먼저 보인다.","표본 실행은 적재하지 않는다."],"엣지":[],"미정":[]},{"묶음":"데이터셋 생성","fn":"FN-DPL-008","이름":"전체 실행","동작":"배포중인 데이터 파이프라인에서 [전체 실행]을 누르면 실행 창에서 실행 시점과 시작 위치(처음부터, 이어서)를 받아 원본 전체를 출력 노드까지 배포한 실행 자원으로 처리한다. 상태는 실행중이 되고, 끝나면 배포중으로 돌아가며 실행 결과 하나가 파이프라인 안에 생긴다. 라벨링 단계에 닿으면 라벨링 대기로 멈췄다가 모든 항목의 작업이 끝나면 이어서 실행한다.","규칙":["권한이 필요 없다.","막는 차례: 다른 구성원 편집 중 → 배포중 아님(미배포·설치중·대기별 문구) → 발행 중 → 원본 폴더 빔 → 설정 미완성(단계 미선택, 모델 미선택, 필수 칸, 모델 배포 운영 중 아님, 열·비율 오류).","미배포 문구는 「[배포]로 자원을 점유한 뒤 전체 실행을 할 수 있습니다.」다.","발행하지 않은 지난 실행 결과는 새 실행 결과로 대체한다. 새 전체 실행은 지난 검수 판정을 지운다.","이어서 실행은 중간 산출물을 보관하고 중지한 실행에만 있고, 멈춘 노드부터 처리한다.","실패한 실행은 이어서 실행할 수 없고 처음부터 다시 실행한다.","실행을 예약하면 [전체 실행] 자리가 [예약 취소]이고, 예약을 취소하기 전까지 설정 편집과 삭제를 막는다. 예약 취소는 권한 없이 확인 창을 거친다.","실행이 끝나면 작업 이력에 실행 줄(실행 조건, 결과, 실행 시간)과 소스 노드가 읽은 파일·회차 줄을 남긴다."],"엣지":["실행 중 실패하면 상태는 배포중으로 돌아가고 배포 회차와 자원은 유지한다. 발행은 「마지막 전체 실행이 실패해 발행할 실행 결과가 없습니다.」로 막힌다.","실행 결과가 0행이면 발행을 막는다.","실행 결과를 만든 뒤 원본 데이터가 바뀌면 그 결과는 발행할 수 없다.","필터 조치가 「실행 실패」이거나 데이터 계약 검증을 통과하지 못하면 실행을 실패로 끝낸다."],"미정":["전체 실행 창의 예약(지정 시각, 피크외 시간)을 유지할지, 실행 일정과 즉시 실행만 둘지 정하지 않았다(C-18).","스토리지 사용률 95% 이상에서 전체 실행 시작을 막을지 정하지 않았다(P-37)."]},{"묶음":"데이터셋 생성","fn":"FN-DPL-009","이름":"실행 중지","동작":"진행 중인 전체 실행에서 [실행 중지]를 누르면 확인 창에서 중간 산출물 보관 여부를 고르고 실행을 멈춘다. 상태는 배포중으로 돌아가고 자원은 계속 점유한다. 보관하면 다음 전체 실행에서 멈춘 노드부터 이어서 실행할 수 있다.","규칙":["권한이 필요 없다. 자원 반환은 [배포 중지]가 맡는다.","처음 값은 보관이다.","라벨링 대기 중에도 [실행 중지]로 멈추고, 입력한 라벨은 보관해 다음 이어서 실행에서 쓴다.","보관한 중간 산출물은 다음 전체 실행(처음부터·이어서)이나 설정 변경 때 지우고, 보관하는 동안 스토리지 사용량에 든다.","다른 구성원이 편집 중이면 막는다."],"엣지":["멈춘 순간 돌던 노드는 대기로 돌린다. 작업 이력의 실행 줄 결과는 「중지」다."],"미정":[]},{"묶음":"데이터셋 생성","fn":"FN-DPL-010","이름":"데이터셋 버전 발행","동작":"검수 대기가 0건인 실행 결과에서 [발행]을 누르고 저장 폴더와 버전 설명을 입력하면, 결과 확인 → 파일 이동 → 버전 등록 세 단계로 반려한 행을 뺀 데이터셋 버전 vN을 만든다. 버전 폴더는 버전 등록 때 데이터 관리에 처음 생긴다. 발행은 화면을 닫아도 계속된다.","규칙":["권한과 배포 상태는 조건이 아니다.","기본 저장 폴더는 /데이터셋/{파이프라인 이름}이다.","막는 차례: 다른 구성원 편집 중 → 전체 실행 중 → 마지막 실행 실패 → 결과 없음 → 이미 발행 → 결과 0행 → 원본 변경 → 검수 대기 n건.","검수 대기는 미판정과 보류다. 반려가 있어도 검수 대기가 0이면 발행한다.","저장 폴더에 같은 vN 폴더가 있으면 막는다.","발행 중에는 [전체 실행], [편집], 삭제를 막는다.","발행 중 진행은 「데이터셋 버전 vN을 발행하고 있습니다. {단계} 중입니다(n/3).」로 보인다.","발행은 회차를 만들지 않고 그 회차 작업 내역에 「데이터셋 버전 발행」 한 줄을 남긴다.","발행한 실행 결과의 판정은 바꿀 수 없다."],"엣지":["[발행 취소]는 확인 창을 거치고, 어느 단계에서든 버전과 버전 폴더를 만들지 않으며 실행 결과와 판정은 남긴다.","발행이 도중에 실패하면 실행자와 관리자에게 실패 알림을 보내고, 다시 [발행]하면 같은 결과로 처음부터 발행한다.","발행한 버전을 쓰는 작업의 생성자와 관리자에게 「데이터셋 새 버전」 알림을 보낸다."],"미정":["발행이 파일 이동이면 스토리지를 검사하지 않고, 복사면 잔여 스토리지 초과 시 막는다. 어느 쪽인지 정하지 않았다(C-21).","검수자가 승인한 격리 행을 버전에 넣을지 정하지 않았다(N-04)."]},{"묶음":"데이터셋 생성","fn":"FN-DPL-023","이름":"실행 일정 설정","동작":"수집 노드 패널의 「실행 일정」을 활성화하고 주기와 시각을 정하면, 데이터 파이프라인이 배포 중인 동안 그 일정에 따라 전체 실행을 시작한다. 처음 값은 비활성화이고 이때는 수동 실행만 한다. 바꾼 일정은 [편집 완료] 때 작업 이력에 남고 다음 실행부터 반영한다.","규칙":["외부 소스 단계(웹 크롤링, 데이터베이스 조회, 외부 서버 파일)의 노드에만 있다.","주기는 매시간, 매일, 매주, 매달, 매년이다.","시각은 매시간이면 매시 00·10·20·30·40·50분, 그 밖은 00:00~23:00이다.","데이터 파이프라인 전체에 거는 일정 버튼은 없다.","정보 탭은 활성화한 수집 노드마다 「{주기 시각} ({노드 이름})」을 잇고, 없으면 「비활성화」다.","작업 이력에는 「설정 변경 | {수집 노드 이름} | 실행 일정 | 변경 전 → 변경 후」로 남는다."],"엣지":["배포 중이 아니면 일정이 와도 실행하지 않고 작업 이력에도 남지 않는다."],"미정":[]},{"묶음":"데이터셋 생성","fn":"FN-DPL-074","이름":"일정 실행","동작":"배포 중이고 실행 일정을 활성화한 수집 노드가 있으면 다음 실행 일시에 전체 실행을 처음부터 시작한다. 다음 실행을 기다리는 동안 상태는 대기이고, 사유 창에 노드 이름, 실행 일정, 다음 실행 일시를 보인다. 실행 줄의 실행 조건은 「실행 일정」이다.","규칙":["다음 실행 일시는 수집 노드마다 계산한 가장 이른 시각이다.","매주, 매달, 매년은 배포 일시의 요일과 날짜를 따른다.","지난 시각은 몰아서 실행하지 않는다.","그 시각에 앞 전체 실행이 진행 중이면 이번 일정을 건너뛴다.","실행 일정을 기다리는 대기는 자원 대기 작업 수에 세지 않는다."],"엣지":[],"미정":["실행 일정을 기다리는 동안의 상태 칩을 「대기」로 둘지 「배포중」으로 둘지 정하지 않았다(C-22).","발행 중이거나 다른 구성원이 편집 중일 때 일정을 건너뛰고 「건너뜀」 줄을 남길지 정하지 않았다(P-30).","발행하지 않은 결과에 검수 판정이 있을 때 일정 실행이 그 결과를 덮어쓸지, 건너뛰고 알릴지 정하지 않았다(P-29)."]},{"묶음":"설정","fn":"FN-DPL-024","이름":"라벨링 단계 설정","동작":"라벨링 노드에 라벨링 유형 단계를 추가하고 타입, 입력 열, 라벨 정의, 라벨링 가이드, 작업자와 분담 방식, 검수자와 검수 방식을 정한다. 모델 초안을 쓰는 타입은 앞 AI 단계의 결과 열을 초안 열로 고른다. 설정은 자동 저장되고 다음 전체 실행부터 반영한다.","규칙":["분담 방식은 균등 분배, 공용 대기열이다.","작업자는 필수다. 고르지 않으면 실행을 막는다.","검수자는 라벨링 검수 권한이 있는 구성원에서 고르고 작업자와 겹칠 수 없다.","검수자를 고르지 않으면 검수 방식은 비활성(「검수자를 선택하지 않아 선택할 수 없습니다.」)이고 작업자가 저장한 항목을 바로 승인한다.","검수 방식은 전수 검수, 표본 검수(표본 비율 1~100%)다. 표본 비율이 비면 실행을 막는다(「표본 비율을 입력해야 실행할 수 있습니다.」).","라벨링 가이드는 파일 하나, 2MB 이하다.","라벨 열 이름이 겹치면 실행을 막는다.","앞 단계 출력에 필요한 열이 없는 타입은 고를 수 없다."],"엣지":["표본 비율 100%는 전수 검수와 같다."],"미정":[]},{"묶음":"라벨링, 검수","fn":"FN-DPL-011","이름":"라벨링 작업","동작":"전체 실행이 라벨링 단계에 닿으면 라벨링 대기로 멈추고 작업자와 검수자에게 알림을 보낸다. 작업자는 [라벨링]으로 작업 화면을 열어 항목마다 라벨을 입력하거나 모델 초안을 고치고 작업을 완료한다. 모든 항목의 작업이 끝나면 전체 실행을 이어서 진행한다.","규칙":["균등 분배는 배정된 항목만, 공용 대기열은 내 항목과 미작업 항목을 보인다.","작업자로 지정되지 않으면 [라벨링]은 비활성이고 이유를 보인다(「작업자로 지정되지 않아 라벨링할 수 없습니다.」 꼴).","작업 화면은 타입마다 다르다.","고친 내용은 1초 뒤와 항목을 옮길 때 자동 저장하고, 자동 저장은 항목 상태를 바꾸지 않는다.","단축키는 물리 키로 받아 한글 입력 상태에서도 같다.","라벨 저장 한 건이 작업 이력 한 줄이다(재작업 항목은 재작업 저장)."],"엣지":["다음 전체 실행에서 반려 건은 「재작업」, 라벨이 없는 건은 「미작업」으로 라벨링 대기가 되고, 승인한 라벨은 그대로 쓴다.","라벨이 모두 있으면 라벨링 단계에서 멈추지 않는다.","재작업 항목을 열면 검수 의견과 이전 반려 사유를 먼저 보이고, 다시 저장하면 검수 대기다."],"미정":["라벨링 대기 동안 실행 자원을 돌려주고 끝나면 다시 받을지, 배포 중지까지 계속 잡을지 정하지 않았다(C-20)."]},{"묶음":"라벨링, 검수","fn":"FN-DPL-012","이름":"검수 판정","동작":"검수자가 작업 완료 항목을 읽기 전용으로 열어 항목 전체나 작성 칸마다 의견을 입력하고 승인, 반려, 보류로 판정한다. 판정은 즉시 실행 결과에 반영되고 한 건마다 작업 이력에 한 줄이 남는다. 반려한 행은 발행할 때 버전에서 빼고, 다음 전체 실행에서 재작업 항목으로 라벨링 대기가 된다.","규칙":["판정자는 라벨링 단계에서 지정한 검수자다.","검수 대상은 수동 라벨 행, AI 노드가 만든 값의 행, 필터·AI 단계의 격리 행이다.","표본 검수 n%이면 작업 완료 항목 가운데 n%만 검수 대상이고 나머지는 자동 승인한다. 검수 대기는 표본 대상 가운데 미판정과 보류만 센다.","보류는 검수 대기로 남는다.","반려 건의 재작업은 같은 실행 안에서 일어나지 않는다.","발행한 실행 결과의 판정은 바꿀 수 없다."],"엣지":["검수자를 지정하지 않으면 작업 완료 항목을 바로 승인하고 검수 대기는 0이다.","새 전체 실행은 지난 판정을 비운다. 승인한 라벨 값은 남지만 그 건도 새 실행의 검수 대상이다."],"미정":["표본 검수의 n%를 어떤 항목으로 언제 뽑는지, 재작업 건이 다시 표본에 드는지 정하지 않았다(N-03)."]},{"묶음":"라벨링, 검수","fn":"FN-DPL-013","이름":"판정 이력","동작":"검수자가 라벨링·검수 탭의 [판정 이력]을 열면 판정한 건을 최근 판정부터 보여 준다. 한 건을 되돌리면 그 판정을 지우고 그 건을 검수 대기로 돌린다.","규칙":["되돌리기는 발행 전까지만 한다.","다른 구성원이 편집 중이면 되돌리기를 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링, 검수","fn":"FN-DPL-014","이름":"데이터 분포 조회","동작":"라벨링·검수 탭에서 실행 결과의 분포(타입별 라벨 분포, 작성 길이, 점수 등)와 검수 품질(승인, 반려, 보류 수)을 조회한다. 데이터는 바꾸지 않는다.","규칙":["조회는 뷰어도 한다.","실행 결과가 없으면 값은 「-」다."],"엣지":[],"미정":[]},{"묶음":"라벨링, 검수","fn":"FN-DPL-025","이름":"라벨링 가이드 조회","동작":"작업자와 검수자가 작업 중에 라벨링 단계에서 올린 가이드의 파일 이름, 업로드 일시, 본문이나 이미지를 조회한다.","규칙":["올린 가이드가 없으면 조회를 막고 이유를 보인다.","미리보기를 지원하지 않는 형식은 파일 이름만 보인다."],"엣지":[],"미정":[]},{"묶음":"데이터셋 버전","fn":"FN-DPL-015","이름":"데이터셋 버전 조회","동작":"데이터셋 버전 탭에서 발행한 버전 목록과 버전별 생성 계보(소스 폴더, 실행 회차, 설정 스냅샷)를 조회한다. 사용 현황은 그 버전을 쓰는 작업(파인 튜닝 학습·테스트 데이터셋, RAG, 모델 배포 벤치마크) 수다.","규칙":["열은 버전, 설명, 행 수, 검수 수정 행 수(라벨링 검수를 쓸 때만), 사용 현황, 발행 일시, 롤백이다.","설명이 없으면 「-」다.","사용은 데이터셋이 아니라 버전마다 센다."],"엣지":["업로드 「기존 데이터셋에 버전 추가」로 생긴 버전도 같은 데이터셋의 버전으로 보인다."],"미정":[]},{"묶음":"데이터셋 버전","fn":"FN-DPL-016","이름":"버전 비교","동작":"두 버전을 고르면 결과(행 수, 분할, 열)와 설정 스냅샷의 차이(노드·단계 추가, 삭제, 값 변경)를 함께 보여 준다. 조회는 뷰어도 한다.","규칙":["설정 스냅샷이 없는 버전이 끼면 결과만 비교하고 「{버전}에는 설정 스냅샷이 없습니다.」를 보인다."],"엣지":[],"미정":[]},{"묶음":"데이터셋 버전","fn":"FN-DPL-017","이름":"설정 롤백","동작":"버전 줄의 롤백을 누르고 확인하면 그 버전을 발행한 시점의 설정 스냅샷으로 지금 설정을 바꾼다. 데이터셋 버전과 작업 이력은 지우지 않고, 바뀐 설정은 다음 전체 실행부터 반영한다.","규칙":["롤백은 편집 동작이라 편집 점유 규칙을 따른다.","가장 최신 버전은 지금 설정이라 롤백이 비활성(「현재」)이다.","설정 스냅샷이 없는 버전은 롤백하지 않고 이유를 보인다.","전체 실행 중, 발행 중, 표본 실행 중에는 막는다."],"엣지":["롤백으로 설정이 바뀌면 발행하지 않은 실행 결과와 판정은 설정 변경 규칙에 따라 지운다."],"미정":[]},{"묶음":"작업 이력","fn":"FN-DPL-018","이름":"작업 이력 조회","동작":"작업 이력 탭에서 배포 회차별로 상태, 전체 실행 수, 발행 버전, 실행 자원, 실행 시간, 배포 일시, 실행자를 조회하고, 회차를 열어 그 회차의 작업 내역(배포 시작·중지, 전체·표본 실행, 설정 변경, 라벨 저장, 검수 판정, 발행, 다운로드)을 변경 전후, 반영 상태, 승인자와 함께 본다.","규칙":["회차 표기는 n회차이고 0회차는 생성이다.","전체 실행과 표본 실행은 회차를 열지 않는 작업 내역이고 실행 조건(수동 실행, 실행 일정)을 적는다.","설정 변경은 배포 중에도 저장하고 반영 상태는 다음 전체 실행 뒤 반영됨이다.","변경 사항 탭은 직전 배포 회차와 비교한다.","회차 상세에는 데이터 파이프라인 실행 결과 탭이 있다.","기록은 지우지 않고, 화면에는 관리 설정의 표시 범위만 보인다.","오케스트레이터를 거친 일은 줄에 「오케스트레이터」 경유를 표시한다."],"엣지":["전체 실행 중 배포가 중지되면 실행 줄 결과 「중지」와 배포 중지 줄이 함께 남는다."],"미정":[]},{"묶음":"정보","fn":"FN-DPL-019","이름":"정보 조회","동작":"정보 탭에서 이름, 설명, 생성자, 구성(노드 수, 소스 폴더), 실행 자원, 수집 노드의 실행 일정, 출력 데이터셋과 그것을 쓰는 작업을 조회한다.","규칙":["실행 자원은 배포 중(설치중, 배포중, 실행중)일 때만 값을, 그 밖에는 「실행 자원 -」이다.","실행 일정은 활성화한 수집 노드마다 「{주기 시각} ({노드 이름})」, 없으면 「비활성화」다."],"엣지":[],"미정":[]},{"묶음":"정보","fn":"FN-DPL-020","이름":"데이터 파이프라인 수정, 복제, 삭제","동작":"수정은 생성 창과 같은 칸에서 이름과 설명을 바꿔 즉시 저장한다. 복제는 설정을 복사해 새 데이터 파이프라인을 만들고(실행 결과, 버전, 작업 이력은 복사하지 않음), 삭제는 설정과 작업 이력을 지우되 발행한 데이터셋 버전은 데이터 관리에 남긴다.","규칙":["수정 창의 원본 데이터 칸은 지금 소스 노드가 읽는 폴더를 고른 채 비활성이다(「원본 데이터는 설정 탭의 소스 노드에서 변경합니다.」).","바꾼 값이 없으면 [수정]을 막는다(「변경한 항목이 없습니다.」).","정보 탭 수정은 설정 탭 편집과 같은 점유다.","배포가 걸려 있는 동안(대기, 설치중, 배포중, 실행중) 삭제를 막는다(「배포 중인 데이터 파이프라인은 삭제할 수 없습니다. [배포 중지] 뒤 삭제합니다.」).","발행 중, 표본 실행 중, 편집 모드, 실행 예약 중, 다른 구성원 편집 중에도 삭제를 막는다. 이유는 먼저 걸린 하나만 보인다.","실패 상태는 자원을 반환한 상태라 지울 수 있다."],"엣지":["라벨링 대기로 멈춘 전체 실행도 실행중이라 삭제를 막는다.","삭제 뒤 남은 버전 폴더는 쓰는 작업이 있으면 데이터 관리에서도 지울 수 없다."],"미정":["발행한 데이터셋을 파인 튜닝이 학습·테스트 데이터셋으로 쓸 때 삭제를 막을지(지금은 막음), 버전 폴더만 남기고 허용할지 정하지 않았다(N-02)."]},{"묶음":"배포","fn":"FN-DPL-021","이름":"데이터 파이프라인 배포","동작":"[배포] 창에서 실행 자원 한 벌(노드 풀, CPU·RAM, GPU)과 실행 시점을 받아 배포하면 설치중을 거쳐 배포중이 되고, 배포 중지까지 그 자원을 점유한다. 이때 배포 회차가 열리고 모든 노드의 표본 실행과 전체 실행을 그 자원으로 한다. 자원이 모자라거나 예약한 시점 전이면 대기로 기다렸다가 배포한다.","규칙":["컴퓨팅 자원 사용 권한이 필요하다. 없으면 [배포 요청]이고 승인되면 요청한 자원과 시점으로 바로 배포한다.","처음 배포의 노드 풀과 자원 칸은 비어 있고, 다시 배포는 지난 값을 채운다.","GPU 칸이 있고 0 EA면 CPU와 RAM만 쓴다.","배포 중에도 설정 편집을 한다(전체 실행 중, 발행 중 제외).","실행 자원 변경은 배포 중지 뒤 다시 배포한다.","대기 사유는 자원 부족, 예약, 피크외 시간, 승인 대기이고 대기 중 자원 점유는 0이다.","대기 사유 창은 실행 시점, 대기 사유, 실행 예정 일시, 대기 시간을 적고 대기 차례와 예상 대기 시간은 적지 않는다.","대기에는 만료가 없다. 사유가 풀리면 자동으로 배포하고 취소는 사람이 한다."],"엣지":["내 배포 요청이 승인 대기 중이면 다른 컴퓨팅 자원 요청을 막는다.","요청을 보낸 뒤 권한이 생기면 대기 요청은 자동 취소되고 바로 배포할 수 있다."],"미정":[]},{"묶음":"배포","fn":"FN-DPL-022","이름":"데이터 파이프라인 배포 중지","동작":"[배포 중지]를 누르고 확인하면 실행 자원을 반환하고 상태는 중지가 되며 그 배포 회차가 끝난다. 대기나 예약 중이면 대기나 예약을 취소하고 중지로 돌린다. 설정, 실행 결과, 데이터셋 버전은 남는다.","규칙":["권한이 필요 없다(배포 중지 요청은 없다).","전체 실행 중에는 막는다(「전체 실행 중에는 배포를 중지할 수 없습니다. 실행이 끝나거나 [실행 중지]한 뒤 중지합니다.」).","표본 실행 중, 발행 중에는 막는다.","다른 구성원이 편집 중이면 막는다.","자원 대기와 배포 예약의 [배포 중지]도 확인 창을 거친다(예약이면 「배포 예약을 취소하시겠습니까?」)."],"엣지":["확인 창을 연 사이 자원이 확보되어 설치중이 되면 그대로 설치를 취소하고 중지로 처리한다."],"미정":["전체 실행 중 [배포 중지]를 허용해 실행도 함께 멈출지(중간 산출물 보관), 지금처럼 막을지 정하지 않았다(C-19)."]},{"묶음":"노드 유형","fn":"FN-DPL-026","이름":"노드 유형 > 소스(Source)","동작":"데이터 관리의 원본 데이터 경로나 외부 소스(웹 크롤링, 데이터베이스 조회, 외부 서버 파일)를 읽어 행과 열의 표로 다음 노드에 넘긴다. 외부 소스의 수집 데이터는 실행마다 저장 위치(원본 데이터)에 적재한다.","규칙":["처리 단계는 테이블 파일, 이미지 폴더, 오디오 폴더, 비디오 폴더, 문서 폴더, 웹 크롤링, 데이터베이스 조회, 외부 서버 파일이다.","파이프라인마다 소스 노드가 하나 이상 있어야 한다.","읽기 권한이 없는 경로나 연결이면 실행을 막는다.","원본 데이터 폴더를 바꾸는 자리는 소스 노드뿐이다.","실행 일정 칸은 외부 소스 단계에만 있다."],"엣지":["소스가 읽는 폴더는 연결 작업이 있는 데이터라 데이터 관리에서 이름 변경, 이동, 삭제가 막힌다."],"미정":["수집 노드가 실행마다 원본 데이터에 새 파일을 추가하는지(파일마다 1회차), 같은 파일을 덮어써 회차를 올리는지 정하지 않았다(P-17)."]},{"묶음":"노드 유형","fn":"FN-DPL-027","이름":"노드 유형 > 분석(Analyze)","동작":"앞 단계 출력의 데이터로 데이터 유형에 맞는 그래프와 품질 리포트를 만든다. 받은 행은 바꾸지 않고 그대로 다음 노드에 넘긴다.","규칙":["그래프는 선 차트, 막대 차트, 원형 차트, 히스토그램, 산점도, 상관관계 히트맵, 박스 플롯, 워드 클라우드, 텍스트 네트워크, 이미지 어노테이션 뷰어, 스펙트로그램, 비디오 어노테이션 뷰어다.","데이터 유형에 맞지 않는 그래프는 고를 수 없다.","품질 리포트는 모든 데이터 유형에 쓴다.","그래프 칸의 범위는 구간 개수 2~50, 최소 단어 길이 1~10, 최소 등장 횟수 1 이상이다."],"엣지":[],"미정":[]},{"묶음":"노드 유형","fn":"FN-DPL-028","이름":"노드 유형 > 라벨링(Labeling)","동작":"앞 단계 출력의 이미지 열, 텍스트 열과 초안 열을 받아 사람이 라벨을 붙이게 하고, 승인한 라벨을 타입별 열로 더한 표를 넘긴다. 실행이 이 노드에 닿으면 라벨링 대기로 멈추고 모든 항목이 끝나면 이어서 실행한다.","규칙":["라벨링 유형은 이미지, 텍스트, 생성형 AI, 순위 점수, 멀티모달이다.","작업자가 없으면 실행을 막는다.","정의 항목은 라벨링 유형과 타입, 라벨 정의, 작업자, 검수자다."],"엣지":[],"미정":["라벨링 대기 중 실행 자원 반환 여부(C-20)."]},{"묶음":"노드 유형","fn":"FN-DPL-029","이름":"노드 유형 > 전처리(Preprocess)","동작":"앞 단계 출력의 데이터를 데이터 유형별 처리 단계로 정제·변환해 학습할 수 있는 형태의 표로 넘긴다.","규칙":["데이터 유형은 테이블, 텍스트, 이미지, 비디오, 오디오, 문서다.","처리 단계의 항목과 차례는 MODELBASE 전처리와 같다.","전처리에는 Built-in, Custom 구분이 없다. Custom 모델 호출은 AI 단계가 맡는다.","데이터 유형이나 앞 라벨링 결과에 적용할 수 없는 단계는 추가할 수 없고 이유를 보인다."],"엣지":[],"미정":[]},{"묶음":"노드 유형","fn":"FN-DPL-030","이름":"노드 유형 > AI","동작":"앞 단계 출력의 텍스트 열, 이미지 열을 고른 모델 배포나 Custom 모델로 처리해 행마다 결과 열을 만든다. 일부 결과 열은 라벨링 단계의 초안 열로 이어진다.","규칙":["AI 단계는 텍스트 입력(LLM), 이미지 입력(VLM), Custom 모델로 묶는다.","모델을 고르지 않으면 실행을 막는다.","공통 칸은 재호출 횟수, 행당 제한 시간, 실패 행 처리(격리, 빈 값, 실행 실패)다.","실패 행 처리가 격리이면 그 행은 실행 결과의 격리 행으로 두고 검수 대상이 된다.","실패 행 처리가 실행 실패이면 실패한 행이 하나라도 있을 때 실행을 실패로 끝낸다."],"엣지":["고른 모델 배포가 중지되면 전체 실행은 「{모델 배포} 운영 중 아님」으로 막힌다."],"미정":[]},{"묶음":"노드 유형","fn":"FN-DPL-031","이름":"노드 유형 > 필터(Filter)","동작":"앞 단계 출력의 행을 검사 단계로 걸러 조건을 충족하는 행만 넘기고, 맞지 않는 행은 정한 조치(제외, 격리, 실행 실패)로 처리한다. 격리한 행은 데이터 관리에 폴더를 만들지 않고 실행 결과의 격리 행으로 데이터 파이프라인 안에 둔다.","규칙":["조치는 제외, 격리, 실행 실패다.","격리 행은 결과 표에서 빠지고 라벨링·검수 탭의 검수 대상으로 보인다.","격리 행은 다음 전체 실행이나 설정 변경 때 실행 결과와 함께 지운다.","조치가 실행 실패이면 맞지 않는 행이 하나라도 있을 때 실행을 실패로 끝내고 격리하지 않는다.","참조 무결성 검사의 참조 키 열은 다른 표의 열이라 글자로 입력한다."],"엣지":[],"미정":["검수자가 승인한 격리 행을 버전에 넣을지 정하지 않았다(N-04)."]},{"묶음":"노드 유형","fn":"FN-DPL-032","이름":"노드 유형 > 흐름(Flow)","동작":"분기는 조건에 따라 행을 경로별 다음 노드로 나누고, 병합은 여러 경로의 행을 병합 방식과 조인 키로 결합한 표로 넘긴다.","규칙":["병합 방식은 Concat, Inner, Left, Outer, As-of다.","조인 방식에서 조인 키가 없으면 실행을 막는다.","As-of는 허용 오차를 입력한다."],"엣지":[],"미정":[]},{"묶음":"노드 유형","fn":"FN-DPL-033","이름":"노드 유형 > 출력(Export)","동작":"앞 단계 출력의 행을 분할하고 형식을 바꿔 데이터셋 버전의 분할별 파일로 만든다. 발행할 때 이 파일이 버전 폴더로 옮겨진다.","규칙":["처리 단계는 그룹 기반 분할, 인스트럭션 형식 변환, 테이블 출력, JSONL 출력, RAG 문서셋 출력, 데이터 계약 검증이다.","그룹 기반 분할은 분할 방식, 그룹 키, 시간 열, train·val·test 비율을 받는다.","분할 비율 합이 맞지 않으면 실행을 막는다.","데이터 계약 검증의 규격을 충족하지 않으면 실행을 실패로 끝낸다."],"엣지":[],"미정":[]},{"묶음":"전처리 단계","fn":"FN-DPL-034","이름":"테이블 전처리","동작":"테이블 데이터의 대상 열을 처리 방식으로 정제·변환한 테이블을 넘긴다.","규칙":["숫자가 아닌 열에 수치 처리 방식을 고르면 실행을 막는다.","집계와 시계열 리샘플링은 행 수가 줄어든다.","라벨링 결과 JSON CSV 변환은 라벨 하나당 한 행이다.","One-Hot 인코딩은 처음 보는 값의 처리(Ignore, Error, Infrequent)를 정한다."],"엣지":[],"미정":[]},{"묶음":"전처리 단계","fn":"FN-DPL-036","이름":"텍스트 전처리","동작":"텍스트 데이터나 텍스트 열이 있는 테이블의 대상 열을 정제한 텍스트 열로 넘긴다. 청킹과 증강은 행을 더한다.","규칙":["처리 단계는 텍스트 정제, 의미 필터링, 텍스트 인코딩 통일, 토큰화 및 임베딩 생성, 텍스트 증강, 구문 재배열, 규칙 기반 패러프레이즈 생성, 청킹, 길이 기준 필터링, 완전 일치 중복 제거, 개인정보 비식별화다.","받지 않는 데이터 유형이면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"전처리 단계","fn":"FN-DPL-037","이름":"이미지 전처리","동작":"이미지 데이터를 처리 방식으로 정리·변환한 이미지로 넘긴다. 증강은 행을 더한다.","규칙":["손상 이미지 제거와 노이즈 증강을 뺀 단계는 공통 칸 「손상 파일 건너뛰기」를 받는다.","이미지 특성 추출은 Embedding 모델 배포를 골라 embedding 열을 더한다.","받지 않는 데이터 유형이면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"전처리 단계","fn":"FN-DPL-039, FN-DPL-040, FN-DPL-041","이름":"비디오 전처리, 오디오 전처리, 문서 전처리","동작":"비디오는 프레임 이미지나 오디오 파일로, 오디오는 정리한 오디오 파일로, 문서는 페이지 이미지나 추출한 텍스트 열로 바꿔 넘긴다.","규칙":["각 유형의 처리 단계와 처리 방식은 MODELBASE 전처리와 같다.","받지 않는 데이터 유형이면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-044","이름":"AI > 이미지 입력(VLM) > 광학 문자 인식(OCR)","동작":"이미지 열을 고른 모델 배포로 읽어 인식한 텍스트 열을 더하고, 출력 범위에 따라 페이지와 위치 열을 더한다.","규칙":["칸은 모델 배포, 인식 언어, 출력 범위(텍스트, 페이지, 좌표 박스)다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-045","이름":"AI > 이미지 입력(VLM) > 이미지 캡셔닝(Caption Image)","동작":"이미지 열을 VLM 모델 배포로 처리해 캡션 열을 더한다. 캡션 열은 이미지 캡셔닝 라벨링의 초안 열이 된다.","규칙":["칸은 VLM 모델 배포와 생성 조건이다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-055","이름":"AI > 이미지 입력(VLM) > 이미지 질의응답 생성(Generate Visual QA)","동작":"이미지 열을 VLM 모델 배포로 처리해 질문과 답 열을 더한다. 시각 질의응답 라벨링의 초안 열이 된다.","규칙":["칸은 VLM 모델 배포, 출력 언어, 질문 기준, 이미지당 생성 수다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-046","이름":"AI > 텍스트 입력(LLM) > 속성 추출(Extract Attributes)","동작":"텍스트 열이나 이미지 열에서 지시문에 따라 추출 속성마다 열을 더한다.","규칙":["칸은 입력 유형에 맞는 모델 배포, 추출 속성, 지시문이다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-047","이름":"AI > 텍스트 입력(LLM) > 텍스트 분류(Classify Text)","동작":"텍스트 열을 허용 클래스와 판단 기준으로 분류해 분류 결과 열을 더한다.","규칙":["칸은 LLM 모델 배포, 허용 클래스, 판단 기준, 허용 밖 값 처리 방식이다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-048","이름":"AI > 텍스트 입력(LLM) > 텍스트 요약(Summarize Text)","동작":"텍스트 열을 요약 기준과 출력 길이로 요약해 요약 열을 더한다. 요약 라벨링의 초안 열이 된다.","규칙":["칸은 LLM 모델 배포, 요약 기준, 출력 길이다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-049","이름":"AI > 텍스트 입력(LLM) > 질문 답변 생성(QA Generation)","동작":"텍스트 열과 청크 ID 열로 청크마다 질문, 답, 근거 열을 만든다. 질의응답 라벨링의 초안 열이 된다.","규칙":["칸은 LLM 모델 배포, 질문 유형(사실 확인, 추론, 요약), 청크당 생성 수다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-050","이름":"AI > 텍스트 입력(LLM) > 지시문 데이터 생성(Instruction Generation)","동작":"원천 열로 지시문, 입력, 응답 열을 만든다. 지시문 응답 라벨링의 초안 열이 된다.","규칙":["칸은 LLM 모델 배포, 작업 유형(요약, 분류, 정보 추출, 답변 작성), 청크당 생성 수다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-051","이름":"AI > 텍스트 입력(LLM) > 문장 변형 증강(Augmentation)","동작":"텍스트 열과 원본 행 ID 열로 변형 방식과 증강 배수만큼 증강 행을 더하고 원본 행 연결 열을 단다.","규칙":["칸은 LLM 모델 배포, 변형 방식, 증강 배수다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-053","이름":"AI > 텍스트 입력(LLM) > 응답 후보 생성(Generate Responses)","동작":"프롬프트 열로 생성 수만큼 응답 후보 열을 만든다. 선호 비교, 응답 평가 라벨링의 초안 열이 된다.","규칙":["칸은 LLM 모델 배포, 생성 수, 다양성, 선택 항목인 두 번째 모델이다.","두 번째 모델을 고르면 두 모델 배포가 번갈아 응답한다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-054","이름":"AI > 텍스트 입력(LLM) > 번역(Translate)","동작":"원문 열을 대상 언어로 번역해 번역 열을 더한다. 번역 라벨링의 초안 열이 된다.","규칙":["칸은 LLM 모델 배포, 원문 언어(자동 감지, 한국어, 영어, 일본어, 중국어), 대상 언어, 지시문이다.","모델 배포나 입력 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"AI 단계","fn":"FN-DPL-052","이름":"AI > Custom 모델 > Custom 모델 호출(Custom Model Endpoint)","동작":"보낼 열을 등록한 Custom 모델에 보내고, 응답 필드를 받을 열 이름으로 더한다.","규칙":["칸은 등록한 Custom 모델, 보낼 열, 받을 열이다.","Custom 모델이나 보낼 열이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-056","이름":"이미지 > 이미지 분류","동작":"작업자가 이미지마다 클래스를 지정하면 항목마다 클래스를 기록한 라벨 열을 만든다.","규칙":["앞 단계 출력에 이미지 열이 없으면 고를 수 없다.","클래스가 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-057","이름":"이미지 > 객체 탐지","동작":"작업자가 객체마다 도형과 클래스, 속성을 표시하면 위치와 클래스를 기록한 라벨 열을 만든다.","규칙":["클래스마다 도형을 여럿 고를 수 있다.","이미지 열이 없으면 고를 수 없다.","클래스나 도형이 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-058","이름":"이미지 > 이미지 분할","동작":"작업자가 영역마다 폴리곤과 클래스를 표시하면 그것을 기록한 라벨 열을 만든다.","규칙":["정의 항목은 분할 방식과 클래스 목록이다.","이미지 열이 없으면 고를 수 없다.","클래스가 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-059","이름":"이미지 > 키포인트 탐지","동작":"작업자가 객체마다 박스와 점 좌표, 보임 상태를 표시하면 그것을 기록한 라벨 열을 만든다.","규칙":["클래스마다 점 이름과 연결선을 정한다.","보임 상태는 보임, 가려짐, 없음이다.","이미지 열이 없으면 고를 수 없다.","점 이름이 없거나 겹치면 실행을 막는다.","연결선의 점 번호가 범위를 벗어나면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-060","이름":"텍스트 > 텍스트 분류","동작":"작업자가 텍스트마다 클래스를 지정하면 항목마다 클래스를 기록한 라벨 열을 만든다.","규칙":["정의 항목은 클래스 목록과 선택 방식(하나, 여럿)이다.","텍스트 열이 없으면 고를 수 없다.","클래스가 없으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-061","이름":"텍스트 > 개체명 인식","동작":"작업자가 텍스트 구간에 개체 유형을 붙이면 구간마다 시작·끝 위치와 개체 유형을 기록한 라벨 열을 만든다.","규칙":["태그는 영문 대문자로 시작하고 영문 대문자, 숫자, 밑줄로 쓴다.","텍스트 열이나 개체 유형이 없거나 태그가 겹치면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-062","이름":"생성형 AI > 지시문 응답","동작":"원천 열과 지시문 데이터 생성 단계의 초안 열로 작성 칸을 채우고, 작업자가 고친 결과를 출력 형식의 라벨 열과 초안 수정 여부 열로 만든다.","규칙":["작성 칸마다 초안 열과 모델 초안 필수 여부를 정한다.","출력 형식은 JSONL Alpaca, JSONL ChatML이다.","텍스트 열이 없으면 고를 수 없다.","생성형 AI·멀티모달 공통: 초안 열 값으로 작성 칸을 채우고 고친 칸은 draft_edited 열에 기록한다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-063","이름":"생성형 AI > 선호 비교","동작":"프롬프트 열과 응답 후보 열을 보여 주고, 작업자가 선호 응답을 고르거나 순위를 매기면 선호 응답, 비선호 응답, 이유 열을 만든다.","규칙":["출력 형식은 TRL DPO JSONL이다.","응답 열이 2개 미만이면 고를 수 없다.","선호와 비선호는 같은 응답일 수 없고 같은 순위를 겹쳐 줄 수 없다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-064","이름":"생성형 AI > 응답 평가","동작":"프롬프트 열과 응답 열을 보여 주고, 작업자가 평가 기준마다 점수와 의견을 입력하면 기준별 점수와 의견 열을 만든다.","규칙":["기본 평가 기준은 정확성, 유용성, 안전성이다.","평가 기준이 없거나 이름이 겹치면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-065","이름":"생성형 AI > 질의응답","동작":"문서 열과 질문 답변 생성 단계의 초안 열로 작성 칸을 채우고, 작업자가 고친 질문, 답, 근거 구간과 초안 수정 여부 열을 만든다.","규칙":["작성 칸마다 초안 열과 근거 구간 필수 여부를 정한다.","근거 구간 필수이면 근거를 표시해야 작업을 완료한다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-066","이름":"생성형 AI > 요약","동작":"원문 열과 요약 초안 열로 작성 칸을 채우고, 작업자가 고친 원문, 요약, 초안 수정 여부 열을 만든다.","규칙":["요약이 최대 길이를 넘으면 작업을 완료할 수 없다.","최대 길이가 10자 미만이면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-067","이름":"생성형 AI > 번역","동작":"원문 열과 번역 초안 열로 작성 칸을 채우고, 작업자가 고친 원문, 번역문, 언어, 초안 수정 여부 열을 만든다.","규칙":["원문 언어와 대상 언어가 같으면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-068","이름":"순위 점수 > 문장 유사도","동작":"문장 1 열과 문장 2 열을 보여 주고, 작업자가 유사도 척도로 점수를 매기면 문장 쌍과 유사도 점수 열을 만든다.","규칙":["앞 단계 출력에 텍스트 열이 2개 미만이면 고를 수 없다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-069","이름":"순위 점수 > 검색 관련도","동작":"질의 열과 후보 열을 보여 주고, 작업자가 후보마다 관련도 등급을 매기면 정답 기준 등급 이상인 후보를 정답, 나머지를 오답으로 질의와 함께 만든다.","규칙":["관련도 등급은 관련 없음, 부분 관련, 관련, 매우 관련이다.","후보 열은 구분 기호나 줄바꿈으로 나눈 후보 문서다.","텍스트 열이 2개 미만이면 고를 수 없다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-070","이름":"멀티모달 > 이미지 캡셔닝","동작":"이미지 열과 캡션 초안 열로 작성 칸을 채우고, 작업자가 고친 이미지, 캡션, 초안 수정 여부 열을 만든다.","규칙":["정의 항목은 캡션 수, 최대 길이, 초안 열이다.","이미지 열이 없으면 고를 수 없다.","최대 길이가 10자 미만이면 실행을 막는다."],"엣지":[],"미정":[]},{"묶음":"라벨링 유형","fn":"FN-DPL-071","이름":"멀티모달 > 시각 질의응답","동작":"이미지 열과 이미지 질의응답 생성 단계의 초안 열로 작성 칸을 채우고, 작업자가 고친 이미지, 질문, 답, 초안 수정 여부 열을 만든다.","규칙":["작성 칸마다 초안 열을 정한다.","이미지 열이 없으면 고를 수 없다."],"엣지":[],"미정":[]}]},{"모듈":"데이터 관리","코드":"DAT","개요":"원본 데이터와 데이터셋을 폴더와 파일로 관리한다. 업로드, 편집, 이동, 복사, 다운로드, 삭제를 하고, 내용이 바뀌면 원본 데이터는 새 회차로, 데이터셋은 새 버전으로 남겨 그것을 쓰는 작업이 어느 회차·버전을 읽는지 지킨다.","상태":["업로드 → 0회차","n회차 → 미리보기 편집 저장·파일 교체·같은 이름 덮어쓰기 → n+1회차","데이터셋 vN → 발행 또는 「기존 데이터셋에 버전 추가」 업로드 → vN+1(vN 유지)","편집 가능 → 다른 구성원이 상세 열기·수정·이동·삭제 시작 → 편집 중(점유) → 창 닫음·접속 종료·3분 무조작 → 편집 가능","다운로드 권한 없음: [다운로드 요청] → 승인 대기 → 승인 → 1회 다운로드 가능 → 다운로드·7일 경과·회차 변경 → 승인 끝"],"공통":["데이터 관리의 두 구분은 원본 데이터와 데이터셋이다. 작업이 생성한 데이터(system 폴더: 체크포인트, 모델, RAG, 서비스)는 보기만 한다.","연결 작업이 있는 데이터는 연결 작업이 가리키는 대상을 없애는 조작(이름 변경, 이동, 삭제)만 막는다. 내용 변경(미리보기 편집, 파일 교체, 업로드 덮어쓰기)은 「새 회차로 저장」 확인 창을 거쳐 새 회차로 저장하고, 복사와 다운로드는 허용한다.","연결 작업은 파운데이션 모델(학습·테스트 데이터셋), RAG, 데이터 파이프라인 소스, 모델 배포 벤치마크(저장한 결과)다. 연결 작업이 배포 전이든 중지든 막고, 연결 작업이 지워지면 그 순간부터 풀린다.","새 회차·버전이 생기면 RAG는 자동으로 바뀌어 [검색 DB 업데이트] 전까지 반영 대기이고, 파인 튜닝·RAG 평가셋·Custom 벤치마크는 지금 버전을 고정하고 최신을 알리며, 모델 배포 벤치마크는 저장한 결과의 버전을 그대로 두고, 데이터 파이프라인 소스는 실행할 때의 최신을 읽는다.","원본 데이터의 회차는 파일 내용이 바뀔 때만 열린다(미리보기 편집 저장, 파일 교체, 같은 이름 덮어쓰기). 이름 변경, 이동, 복사, 다운로드는 회차를 열지 않고 지금 회차의 작업 내역 한 줄로 남는다. 데이터 파이프라인은 원본 데이터에 쓰지 않는다.","발행된 데이터셋 버전 폴더의 내용은 그대로 덮어쓰지 않는다. 고쳐서 저장하면 새 버전 vN+1이 되고 원래 버전은 남는다.","편집 점유는 데이터 한 개의 상세 열기, 수정, 이동, 삭제 동안이다. 점유 중 다른 구성원의 이름 변경, 편집, 이동, 삭제, 복사, 다운로드, 업로드 덮어쓰기, 체크 선택을 막고 「{이름}님이 편집 중입니다.」를 보인다. 창을 닫거나 접속이 끝나거나 3분 무조작(2분 30초에 미리 알림)이면 풀린다.","원본 데이터가 새 회차로 저장되거나 데이터셋 새 버전이 생기면 그 데이터를 쓰는 작업마다 생성자와 관리자 전원에게 알림을 한 건 보낸다(「데이터 새 회차」, 「데이터셋 새 버전」). 수신 설정의 연결 자원 변경 묶음에서 끈다.","다운로드는 다운로드 권한 유형으로 판정한다. 다른 조작(업로드, 편집, 이동, 복사, 삭제)은 권한이 필요 없다.","스토리지 할당량은 GPUBASE가 이 워크로드에 정한 값이고, 업로드 파일과 작업 산출물(원본 데이터, 데이터셋, 체크포인트, 모델, RAG, 서비스, 실행 기록)이 함께 쓴다.","스토리지 사용률이 알림 기준(처음 값 80%, 운영 설정)에 닿으면 구성원 전원에게 알리고, 95%에 닿으면 다시 알리며 새 파운데이션 모델, 커밋, 검색 DB, 모델 배포 생성을 막고 진행 중인 업로드를 실패로 끝낸다. 95% 아래로 내려가면 풀린다.","지금 연 폴더는 주소에 남아 새로 고침과 공유 링크에서 같은 폴더를 연다.","막힌 조작은 숨기지 않고 비활성 + 이유로 둔다."],"기능":[{"묶음":"파일 목록","fn":"FN-DAT-001","이름":"데이터 관리 조회","동작":"데이터 관리를 열면 원본 데이터와 데이터셋 아래 폴더와 파일을 계층별로 보여 준다. 폴더를 열면 그 안의 목록으로 바뀌고 경로가 주소에 남는다.","규칙":["목록은 회차, 이름, 설명, 용량, 연결 작업, 최근 업데이트 일시, 생성자를 보인다.","회차 규칙 말풍선은 목록의 회차 열 머리 한 곳에 둔다.","작업이 생성한 데이터는 체크 선택을 막는다(「작업이 생성한 데이터라 선택할 수 없습니다.」).","발행된 데이터셋 버전 폴더는 「파이프라인이 발행한 버전 폴더입니다. 데이터 파이프라인에서 관리합니다.」를 보인다."],"엣지":["다른 구성원이 편집 중인 데이터는 체크 선택을 막는다(일괄 조작에 섞이지 않게)."],"미정":[]},{"묶음":"파일 목록","fn":"FN-DAT-002","이름":"파일 검색","동작":"지금 폴더에서 데이터 이름이나 생성자로 검색하면 맞는 파일과 폴더만 목록에 남긴다.","규칙":["검색 대상은 이름과 생성자이고 설명은 검색하지 않는다.","검색 범위는 지금 폴더다."],"엣지":[],"미정":[]},{"묶음":"파일 목록","fn":"FN-DAT-003","이름":"파일 보기 방식 전환","동작":"보기 방식을 목록과 카드 사이에서 바꾼다. 같은 데이터를 같은 정렬로 보여 준다.","규칙":["카드 보기의 폴더와 파일은 같은 항목(유형, 생성자, 이름, 설명, 용량, 항목 수, 연결 작업, 최근 업데이트 일시)을 보인다.","목록의 이름 열은 이름만 보인다.","고른 보기 방식은 그 사용자의 브라우저에 남는다."],"엣지":[],"미정":[]},{"묶음":"파일 목록","fn":"FN-DAT-004","이름":"스토리지 사용 현황 조회","동작":"데이터 스토리지 하나의 할당, 사용, 잔여, 사용률과 사용 구성(원본 데이터, 데이터셋, 체크포인트, 모델, RAG, 서비스)을 보여 준다. 값은 대시보드 스토리지와 같다.","규칙":["할당은 GPUBASE가 정한 스토리지다.","보관한 중간 산출물과 실행 결과도 사용량에 든다."],"엣지":[],"미정":["보관 중인 지난 회차의 용량을 사용량과 파일 상세에 어떻게 표시할지 정하지 않았다(P-15)."]},{"묶음":"데이터 업로드","fn":"FN-DAT-005","이름":"데이터 업로드","동작":"내 컴퓨터의 파일과 폴더를 골라 원본 데이터나 데이터셋으로 올린다. 데이터셋은 「새 데이터셋 생성」이나 「기존 데이터셋에 버전 추가」로 저장하고, 버전 추가는 앞 버전을 그대로 두고 새 버전을 만든다. 업로드는 다른 화면으로 옮겨도 계속되고 상단바의 데이터 업로드 현황에서 진행과 중지를 본다.","규칙":["원본 데이터는 모든 파일과 폴더를 받는다.","데이터셋은 Parquet, CSV, JSONL 파일만 받고 CSV·JSONL은 Parquet으로 바꿔 저장한다. 폴더는 받지 않는다(「데이터셋에는 Parquet, CSV, JSONL 파일만 업로드할 수 있습니다({파일}).」).","데이터셋 업로드는 열을 검사하지 않는다. 학습 데이터 형식 판정은 파인 튜닝이 한다.","새 데이터셋은 이름(/, \\\\ 금지)과 설명(선택, 200자)을, 버전 추가는 대상 데이터셋과 버전 설명(선택, 200자)을 받는다.","선택 파일 합이 잔여 스토리지보다 크면 막는다(「선택한 파일(n GB)이 잔여 스토리지 n GB를 초과합니다. 파일을 줄이거나 데이터 관리에서 용량을 확보하세요.」).","한 번에 올리는 개수와 파일 하나의 크기 상한은 운영 설정 값이고 처음 값은 제한 없음이다.","작업이 생성한 데이터 폴더에는 올릴 수 없다.","외부에서 가져오기(SCP, wget, Git)는 없다. 외부 데이터는 데이터 파이프라인 수집 노드가 가져온다.","업로드 처음 파일은 0회차이고, 데이터셋 버전 추가는 「데이터셋 새 버전」 알림을 만든다."],"엣지":["파일 줄 [중지]나 [전체 중지]는 확인 창을 거치고, 중지한 파일은 「중지됨」, 끝난 파일은 남는다.","네트워크 단절, 브라우저 종료, 스토리지 95% 도달이면 올리던 파일은 저장하지 않고 실패로 끝내며 어느 화면에서든 「업로드 실패」 창을 연다.","실패한 파일은 다시 골라 처음부터 올린다."],"미정":[]},{"묶음":"데이터 업로드","fn":"FN-DAT-006","이름":"업로드 중복 파일 처리","동작":"올릴 파일과 같은 이름이 저장 위치에 있으면 중복 파일 확인 창에서 파일마다 새 이름으로 저장, 덮어쓰기, 건너뛰기를 고른다. 덮어쓰기는 그 파일의 새 회차로 저장한다.","규칙":["처음 값은 새 이름으로 저장이다.","건너뛴 파일은 용량 계산에서 뺀다.","연결 작업이 있는 파일도 덮어쓸 수 있고 「새 회차로 저장」을 거친다.","기존 파일을 다른 구성원이 편집 중이면 [덮어쓰기]만 비활성(「{이름}님이 편집 중이라 덮어쓸 수 없습니다.」)이다."],"엣지":["두 구성원이 같은 이름을 거의 동시에 올리면 먼저 저장을 마친 파일이 이름을 갖고, 나중 쪽은 저장 직전 다시 확인해 새 이름으로 저장한다. 고르지 않은 덮어쓰기는 일어나지 않는다.","덮어쓴 파일에 받지 않은 다운로드 승인이 있으면 그 승인은 끝난다."],"미정":[]},{"묶음":"파일 관리","fn":"FN-DAT-007","이름":"파일 관리","동작":"폴더를 만들고, 파일과 폴더를 수정(이름, 설명, 파일 교체), 이동, 복사, 삭제하고, 압축 파일을 고르면 압축을 해제해 그 자리에 안의 파일을 둔다. 여러 데이터를 골라 일괄로 처리한다. 파일 교체는 새 회차로 저장하고 그 파일을 쓰는 작업의 생성자와 관리자에게 알린다.","규칙":["연결 작업이 있는 데이터는 이름 변경, 이동, 삭제를 막고(「연결 작업이 있어 이름 변경, 이동, 삭제할 수 없습니다. 연결 작업에서 이 데이터를 해제하면 변경할 수 있습니다.」) 복사만 허용한다.","연결 작업이 있는 파일의 데이터 수정 창은 이름 칸이 비활성이고 새 파일 교체만 한다.","연결 작업이 있는 데이터와 없는 데이터를 함께 고르면 [삭제]는 비활성(「선택한 데이터 중 n개는 연결 작업이 있어 삭제할 수 없습니다.」)이고 [이동/복사]는 방식이 「복사」로 고정된다.","수정 창은 바꾼 값이 없으면 저장을 막는다.","복사는 복사 크기로 잔여 스토리지를 검사하고, 이동은 검사하지 않는다.","작업이 생성한 데이터는 수정, 이동, 삭제, 복사, 다운로드를 모두 막는다(「작업이 생성한 데이터라 다운로드, 이동, 삭제할 수 없습니다.」). 평가셋 파일만 하나씩 지울 수 있다.","데이터셋 버전 폴더는 쓰는 작업(파인 튜닝 학습·테스트, RAG의 지금·반영 대기 버전, 모델 배포의 저장한 벤치마크 결과)이 있으면 삭제를 막는다.","파일 삭제는 파일과 작업 이력을 함께 지우고, 삭제 사실은 감사 이력에 남는다.","확인 창은 연결 작업 이름을 모두 적는다(「외 n개」로 줄이지 않음)."],"엣지":["복사본은 연결 작업이 없는 새 데이터다. 원본을 지우려면 연결 작업에서 원본을 해제해야 한다.","RAG가 [검색 DB 업데이트]를 마치거나 파인 튜닝이 새 버전으로 바꿔 저장하면 앞 버전은 사용에서 빠지고 그때부터 지울 수 있다.","같은 데이터셋의 여러 버전을 지울 때 쓰는 작업이 있는 버전이 하나라도 섞이면 [삭제]를 막고 그 개수를 적는다.","연결 작업이 없는 파일의 교체는 알림을 만들지 않는다.","이동·복사로 같은 이름 파일을 덮어쓰면 원래 파일 삭제로 보아 그 파일의 다운로드 승인도 사라진다."],"미정":["RAG 평가셋과 저장 전 Custom 벤치마크가 고정해 쓰는 버전의 삭제를 막을지, 허용하고 「삭제됨」으로 표시할지 정하지 않았다(N-01).","쓰는 작업이 없는 데이터셋 버전을 사람이 지울지, 최근 n개를 넘으면 자동으로 지울지 정하지 않았다(P-18)."]},{"묶음":"파일 관리","fn":"FN-DAT-008","이름":"데이터 다운로드","동작":"고른 파일이나 폴더를 「다운로드」 확인 창(대상 목록)을 거쳐 받는다. 폴더는 안의 파일을, 여러 건은 압축 파일 하나로 받는다. 권한이 없으면 [다운로드 요청]을 보내고 관리자가 승인하면 요청자가 같은 자리에서 1회 받는다.","규칙":["다운로드 권한이 있으면(관리자 포함) 확인 창 뒤 바로 받는다.","본인이 만든 파일도 권한 규칙이 같다.","승인은 요청 시점의 파일 목록과 각 파일의 회차에 고정한다. 승인 뒤 폴더에 더해진 파일은 들어가지 않는다.","승인은 1회 다운로드, 승인 후 7일, 그 파일의 회차 변경 가운데 먼저 오는 때 끝난다.","내 요청이 승인 대기 중이면 그 데이터의 내 다운로드는 비활성(「다운로드 요청이 관리자의 승인을 기다리고 있습니다.」)이고 [다운로드 요청 취소]를 둔다.","작업이 생성한 데이터는 권한과 상관없이 받을 수 없다. 커밋은 파운데이션 모델의 커밋 목록에서 받는다.","다른 구성원이 편집 중이면 권한이나 승인이 있어도 막는다.","누가 받든 감사 이력에 「다운로드」 한 건, 파일 작업 이력에 한 줄을 남긴다."],"엣지":["다운로드 요청은 구성원마다 따로다. 다른 구성원의 요청이 대기 중이어도 막지 않는다.","요청 뒤 다운로드 권한이 생기면 대기 요청은 자동 취소되고(「권한이 생겨 요청 없이 실행할 수 있습니다.」) 바로 받는다.","승인을 받은 뒤 권한을 회수당해도 받지 않은 승인은 끝날 조건까지 유효하다."],"미정":[]},{"묶음":"데이터 상세","fn":"FN-DAT-009","이름":"정보 조회","동작":"파일 상세의 정보 탭에서 이름, 경로, 형식, 용량, 규격(해상도, 길이, 행 수), 회차, 생성자, 최근 업데이트 일시를 조회한다. 상세를 여는 동안 그 데이터는 편집 점유 상태다.","규칙":["[경로 복사]와 [다운로드]는 어느 탭에서나 쓴다."],"엣지":[],"미정":[]},{"묶음":"데이터 상세","fn":"FN-DAT-010","이름":"미리보기","동작":"미리보기 탭에서 파일 내용을 형식에 맞게(표, 문서, 글, 이미지, 오디오, 비디오) 보여 준다. 표는 열 이름, 자료형, 결측, 첫 값을 함께 보인다.","규칙":["한 번에 읽는 범위는 플랫폼 설정 값이고 제안값은 200행, 50칸, 글 500줄이다.","미리보기를 지원하지 않는 형식은 이유를 보인다.","미리보기 열람은 작업 이력에 남기지 않는다."],"엣지":[],"미정":[]},{"묶음":"데이터 상세","fn":"FN-DAT-011","이름":"작업 이력 조회","동작":"작업 이력 탭에서 파일의 회차별 변경을 조회한다. 회차는 파일 내용이 바뀔 때 열리고, 회차마다 내용, 이름과 경로, 연결 작업 알림, 다운로드의 변경을 변경 전후, 반영 상태, 승인자와 함께 기록한다.","규칙":["0회차는 처음 업로드다. 회차는 다음 회차 시작 직전에 끝난다.","회차 정보는 회차를 연 일, 파일 크기, 행 수, 실행 일시, 실행자, 업데이트 알림을 받은 연결 작업이다.","이름 변경, 폴더 이동은 회차를 유지하고 「설정 변경」 줄로 남는다.","미리보기 편집 뒤 [취소]는 남지 않는다.","화면은 관리 설정의 표시 회차 수만큼 최근 회차를 보이고, 기록은 지우지 않는다.","작업이 생성한 데이터는 작업 이력 탭이 없고, 평가셋 파일만 둔다."],"엣지":[],"미정":["지난 회차 파일 실물을 어디까지 보관할지(P-12), 언제 누가 지울지(P-13), 조회·다운로드·되돌리기를 둘지(P-14) 정하지 않았다."]},{"묶음":"데이터 상세","fn":"FN-DAT-012","이름":"연결 작업 조회","동작":"연결 작업 탭에서 이 파일을 쓰는 작업의 작업 유형, 작업 이름, 용도, 사용 회차, 사용자, 사용 일시를 조회하고 작업으로 이동한다.","규칙":["사용 회차는 원본 데이터 n회차, 데이터셋 vN이다.","최신이 아니면 값 옆에 「최신 아님」을 보인다.","RAG 검색 DB가 앞 회차로 검색 중이면 「반영 대기」를 보인다.","데이터 파이프라인 소스는 「-」(실행할 때의 최신을 읽음)다."],"엣지":[],"미정":[]},{"묶음":"데이터 상세","fn":"FN-DAT-013","이름":"데이터 편집","동작":"지원하는 형식의 파일을 미리보기에서 편집해 저장하면 새 회차로 저장한다. 연결 작업이 있으면 저장 전에 「새 회차로 저장」 확인 창(연결 작업 수, 반영 방식, 연결 작업 이름 전부)을 거치고, 저장 뒤 쓰는 작업의 생성자와 관리자에게 알린다.","규칙":["편집 지원 형식은 CSV, TSV, XLSX, XLS(표), DOCX, DOC(문서), TXT, MD, JSON, JSONL(글)이다.","편집할 수 있는 크기는 플랫폼 설정 값이고 제안값은 10MB 이하다.","편집 중에는 다른 구성원의 수정, 편집, 다운로드, 복사, 이동, 삭제, 업로드 덮어쓰기를 막는다(「{이름}님이 편집 중입니다.」).","작업이 생성한 데이터는 편집할 수 없다.","발행된 데이터셋 버전을 고쳐 저장하면 새 버전 vN+1로 저장하고 원래 버전은 남긴다."],"엣지":["편집 중 3분 무조작이면 창을 닫고 저장하지 않은 입력은 버린다.","연결 작업이 없는 파일의 편집은 알림을 만들지 않는다."],"미정":["연결 작업이 없는 파일의 편집에서도 회차가 오르는지 정하지 않았다(P-16)."]}]},{"모듈":"파운데이션 모델 학습","코드":"FTM","개요":"Hugging Face 검증 베이스 모델을 데이터셋으로 파인 튜닝(PEFT)하고, 학습 중 저장한 체크포인트 가운데 쓸 것을 커밋으로 확정해 모델 배포에 제공한다. 학습 실행 한 번이 회차 하나다.","상태":["생성됨 → (베이스 모델 불러오기 끝) → 생성됨, [실행] 활성","생성됨·종료·중지·실패 → [실행](자원 확보) → 설치중 → 실행중","생성됨·종료·중지·실패 → [실행](자원 부족, 예약, 피크외 시간, 승인 대기) → 대기","대기 → (자원 반환, 예약 시각, GPUBASE 배정 시각, 승인) → 설치중 → 실행중","대기 → [실행 취소] → 대기 직전 상태 또는 생성됨(N-05 미정)","설치중 → (시작 실패) → 실패","실행중 → (학습 완료) → 종료","실행중 → [중지] → 중지","실행중 → (학습 오류, 스토리지 부족) → 실패","커밋을 가져와 만든 작업(커밋에서 생성, 커밋 파일 업로드)은 학습한 적이 없어도 종료로 시작한다"],"공통":["상태는 생성됨, 대기, 설치중, 실행중, 종료, 중지, 실패 일곱이다. 배포가 없어 배포중은 없다.","학습이 중지되면 커밋이 있어도 중지, 실패하면 커밋이 있어도 실패로 보인다. 학습 기록을 읽지 못한 회차는 산출물이 남아 종료로 보인다.","자원(노드 풀, GPU, CPU, RAM)은 설치중에 잡고 종료·중지·실패 때 돌려준다. 대기 중에는 아무 자원도 잡지 않는다.","회차는 학습이 실행중에 들어간 순간(요청이면 승인 뒤) 열리고 종료·중지·실패로 닫힌다. 0회차는 생성이다.","대기, 대기 취소, 설치중 실패는 회차 번호가 없는 줄로 앞 회차의 작업 내역에 남는다.","학습 실행과 학습 중지는 컴퓨팅 자원 사용 권한이 필요하고, 없으면 요청 뒤 승인으로 한다. 생성, 설정 저장, 커밋은 권한이 필요 없다.","커밋 다운로드는 다운로드 권한이 필요하고, 없으면 요청 뒤 승인되면 요청자가 1회 받는다. 승인은 7일 뒤 만료된다.","승인 대기 요청은 작업 하나에 1건이다. 대기 중에는 요청자, 다른 구성원, 관리자 모두 학습 설정을 바꾸거나 작업을 지울 수 없다.","관리자가 [승인]을 누르는 순간 대상 상태와 요청자 권한을 다시 확인하고, 실행할 수 없으면 [승인]을 막고 이유를 보인다.","편집 점유는 작업 하나에 1명이다. 다른 구성원이 편집 중이면 학습 설정, [실행], [커밋], 커밋 불러오기, 커밋 수정과 삭제를 막는다.","대기에는 만료가 없다. 대기 사유가 모두 풀리면 자동으로 시작하고, 취소는 사람이 한다.","스토리지 사용률 95% 이상이면 새 작업 생성과 커밋 저장을 막는다.","알림: 베이스 모델 불러오기의 종료·실패는 작업 종료 알림, 학습 시작은 실행자와 관리자에게 작업 시작 알림, 회차 시작은 모든 구성원에게 회차 시작 알림, 학습 실패는 실행자와 관리자에게 실패 알림이다.","작업 이력은 지우지 않는다. 관리 설정의 이력 표시 기간은 화면에 보이는 기간일 뿐이고, 리포트에는 모든 기록이 남는다."],"기능":[{"묶음":"파운데이션 모델 목록","fn":"FN-FTM-001~002","이름":"작업 목록 조회와 탐색","동작":"파운데이션 모델 메뉴에 들어오면 학습 작업 목록을 보이고, 상태와 타입으로 거르고 이름으로 찾는다. 목록의 상태는 그 작업의 최근 학습 상태다.","규칙":["목록 검색은 이름과 생성자만 대상으로 한다. 설명은 검색하지 않는다.","상태 필터는 일곱 상태를 모두 둔다."],"엣지":["작업이 하나도 없으면 빈 목록과 생성 버튼 하나만 둔다."],"미정":[]},{"묶음":"파운데이션 모델 목록","fn":"FN-FTM-003, FN-FTM-023","이름":"파운데이션 모델 생성(Hugging Face 베이스)","동작":"사용자가 이름, 설명, 타입, 모델(AGENTBASE가 제공하는 Hugging Face 검증 베이스 모델), 학습 프레임워크, 학습 방식을 정해 [생성]하면 작업을 생성됨으로 만들고 베이스 모델 불러오기를 시작한다. 불러오기가 끝나야 [실행]이 열리고, 끝나거나 실패하면 작업 종료 알림을 보낸다. 자원과 데이터셋은 생성에서 받지 않고 파인 튜닝 탭에서 정한다.","규칙":["생성은 권한이 필요 없다.","타입은 LLM, VLM 둘이다. 임베딩, 리랭커는 파인 튜닝 대상이 아니다.","타입은 처음부터 선택되어 있고, 선택한 타입의 후보가 없으면 모델 칸은 「이 타입으로 등록된 후보가 없습니다.」로 막는다.","베이스 모델, 학습 프레임워크, 학습 방식, 양자화는 생성 뒤 바꿀 수 없다.","생성하면 기본 커밋(source_model) 하나가 함께 저장된다.","스토리지 사용률 95% 이상이면 생성을 막는다."],"엣지":["불러오기 중에는 머리 안내 줄이 진행을 알리고 [실행]을 막는다.","불러오기가 실패하면 작업 종료 알림(실패)을 보내고 [실행]은 계속 막힌다."],"미정":[]},{"묶음":"학습 구성","fn":"FN-FTM-024","이름":"커밋에서 새 작업 생성","동작":"이 AGENTBASE의 커밋 목록 줄에서 [이 커밋으로 모델 생성]을 고르면 생성 창이 열리고, 타입과 모델은 그 커밋이 거슬러 올라간 Hugging Face 베이스 모델로, 시작 커밋은 고른 커밋으로 채워 잠긴다. 생성하면 그 커밋을 시작점으로 고정한 새 작업이 생기고, 커밋을 가진 채 만들어져 종료로 보인다.","규칙":["source_model(기본 커밋)은 시작 커밋이 될 수 없다.","학습 프레임워크와 학습 방식은 생성 창에서 고른다."],"엣지":["원 작업의 커밋이 뒤에 지워져도 새 작업에 들어간 시작 커밋은 남는다."],"미정":[]},{"묶음":"학습 구성","fn":"FN-FTM-025","이름":"커밋 파일로 생성(업로드)","동작":"다른 AGENTBASE에서 다운로드한 커밋 파일(.zip)을 생성 창의 선택 칸 「커밋 파일」에 올리면, 타입과 모델을 먼저 고른 뒤 파일의 베이스 모델이 같은지 확인한다. [생성]하면 창을 바로 닫고 작업을 만든 뒤 업로드를 이어서 하고, 업로드가 끝나면 커밋 목록에 더해 불러온 뒤 베이스 모델을 불러온다. 커밋의 학습 설정, 지표, 학습 로그를 함께 가져오고, 커밋에 데이터셋이 있으면 데이터셋도 가져온다.","규칙":["학습 프레임워크, 학습 방식, 양자화의 처음 값은 커밋 파일의 값이고 바꿀 수 있다. 학습 프레임워크를 바꾸면 커밋 파일의 config 파일은 적용하지 않는다.","AGENTBASE 커밋 파일이 아니면 「AGENTBASE 커밋 파일이 아닙니다. 커밋 목록에서 다운로드한 .zip 파일을 업로드하세요.」로 막는다.","이 AGENTBASE가 제공하지 않는 베이스 모델이면 [생성]을 막는다(「이 커밋의 베이스 모델({모델 ID})은 이 AGENTBASE에서 제공하지 않아 생성할 수 없습니다.」).","고른 타입·모델과 커밋의 베이스 모델이 다르면 [생성]을 막고 [모델을 {모델}로 변경]을 함께 준다.","파일에 커밋이 여럿이면 커밋을 고르기 전까지 [생성]을 막는다.","파일이 잔여 스토리지보다 크면 막는다."],"엣지":["업로드 중에는 학습 설정, config 파일, [실행], [커밋]을 막는다.","[업로드 중지]하면 커밋을 더하지 않고 베이스 모델만 남긴다.","업로드가 실패하면(네트워크, 스토리지 95%, 브라우저 종료) 어느 화면이든 실패 창을 띄우고 커밋 없이 베이스 모델만 남긴다.","밖에서 학습한 어댑터라 스텝별 지표가 없으면 곡선 없이 가져온다."],"미정":[]},{"묶음":"정보","fn":"FN-FTM-004","이름":"작업 정보 조회","동작":"정보 탭에서 작업의 이름, 설명, 타입, 베이스 모델과 그 설명(README), 학습 프레임워크, 학습 방식, 저장 용량, 생성자와 일시를 보인다.","규칙":["보는 일은 작업 이력에 남지 않는다."],"엣지":["베이스 모델 설명을 불러오지 못하면 그 칸만 비운다."],"미정":[]},{"묶음":"정보","fn":"FN-FTM-005","이름":"작업 수정, 복제, 삭제","동작":"이름과 설명은 바로 고친다. 복제하면 수정 창과 같은 복제 창에서 원본의 설정을 복사한 새 작업을 생성됨으로 만들고, 이름은 「{원본}_복제」, 설명은 「{원본}을 복제한 파운데이션 모델입니다.」로 채운다. 삭제하면 작업과 체크포인트, 커밋을 함께 지운다.","규칙":["수정 창은 생성 창과 같은 칸이며 바꿀 수 없는 칸(베이스 모델, 학습 프레임워크, 학습 방식, 양자화)은 비활성이다.","대기 중이면 삭제를 막는다(「학습 대기 중인 작업은 삭제할 수 없습니다. [실행 취소] 뒤 삭제합니다.」).","실행중이면 삭제를 막는다(「학습 중인 작업은 삭제할 수 없습니다. [중지] 뒤 삭제합니다.」).","이 작업의 커밋을 쓰는 모델 배포가 하나라도 있으면 배포 상태와 상관없이 삭제를 막는다.","승인 대기 요청이 있으면 삭제를 막는다(「{요청자}님의 {일} 요청이 승인을 기다리고 있습니다. 요청이 취소되거나 처리된 뒤에 삭제할 수 있습니다.」)."],"엣지":["복제본은 베이스 모델, 데이터셋, 파라미터를 가져오고 학습 지표, 커밋, 이력은 비운다. 베이스 모델은 새로 불러온다.","삭제한 작업의 작업 이력은 리포트와 감사 이력에 남는다."],"미정":[]},{"묶음":"파인 튜닝","fn":"FN-FTM-006","이름":"데이터셋 선택","동작":"학습·테스트에 쓸 데이터셋 버전과 스플릿을 고르면 시스템이 앞·중간·뒤 일부 행에 학습 데이터 형식(프리셋) 일곱을 모두 적용해 「n행 중 m행 통과」를 보이고, 통과한 행이 있는 프리셋만 고르게 한다. 데이터셋마다 프리셋을 하나 이상 고르고, 여럿이면 하나라도 통과한 행을 학습한다. [저장]해야 다음 실행에 반영된다.","규칙":["프리셋은 single, choice, sharegpt, messages, cauldron, glaive, oasst 일곱이다. alpaca(instruction, input, output)는 single로 읽는다.","통과한 프리셋이 하나도 없는 데이터셋은 고를 수 없다.","고른 데이터셋 버전은 고정한다. 더 새 버전이 생기면 줄마다 「최신 vM이 있습니다.」와 [vM으로 변경]을 보이고, 바꾸고 [저장]해야 다음 실행에 반영한다. 자동으로 따라가지 않는다.","더 새 버전이 생기면 생성자와 관리자에게 데이터셋 새 버전 알림을 보낸다.","학습이 쓰는 데이터셋 버전은 데이터 관리에서 지울 수 없다.","대기·설치중·실행중에는 데이터셋 선택과 [vM으로 변경]을 막는다."],"엣지":["열 이름이 맞지 않으면 화면에서 매핑하지 않고 데이터 파이프라인에서 고친다.","커밋에서 이어서 학습할 때도 데이터셋은 바꿀 수 있다.","여러 데이터셋을 고르면 새 버전 안내를 줄마다 따로 보인다."],"미정":[]},{"묶음":"파인 튜닝","fn":"FN-FTM-007","이름":"학습 파라미터 설정","동작":"작업의 학습 프레임워크와 학습 방식에 맞는 파라미터와 체크포인트 저장 규칙을 정하고 [저장]한다. 최대 입력 길이를 넘어 잘리는 샘플 수를 함께 보인다. 저장한 값은 다음 실행에 반영되고, 학습이 끝난 뒤 바꾼 값은 끝난 회차의 작업 내역에 칸마다 한 줄로 남는다.","규칙":["Test Steps는 Train Logging Steps의 배수, Checkpoint Steps는 Test Steps의 배수다. 앞 값을 바꾸면 뒤 값을 가장 가까운 배수로 맞춘다.","Checkpoint Keep(top_k)은 2~50이고 처음 값은 2다. 넘으면 가장 오래된 체크포인트부터 지운다.","Tensor Parallel Size와 Pipeline Parallel Size는 1~8, LoRA Dropout은 0~0.9다.","대기·설치중·실행중이거나 내 실행 요청이 승인을 기다리면 바꿀 수 없다(이유 문구는 상태마다 다르다).","저장하지 않은 변경이 있으면 [실행]을 막는다."],"엣지":["다른 구성원의 실행 요청이 승인을 기다리면 설정을 막고 「{요청자}님의 … 승인되거나 취소된 뒤에 수정합니다.」를 보인다.","학습 상태가 종료여도 내 실행 요청이 승인을 기다리면 잠근다."],"미정":["체크포인트를 몇 개까지 남길지(커밋한 것과 마지막만 남길지, top_k로 둘지) 정하지 않았다(P-28)."]},{"묶음":"파인 튜닝","fn":"FN-FTM-008","이름":"config 파일 업로드","동작":"작업의 학습 프레임워크에 맞는 config 파일을 올리면 파일의 값을 학습 파라미터 칸에 채운다. [저장]해야 학습 설정에 반영된다.","규칙":["선택 항목이다.","DeepSpeed는 JSON, NVIDIA NeMo는 YAML만 받는다. 형식이 다르면 적용하지 않고 형식 오류를 알린다.","커밋에서 이어서 학습할 때는 적용할 수 없다.","대기·설치중·실행중, 커밋 파일 업로드 중에는 막는다."],"엣지":["파일에 없는 칸은 지금 값을 유지한다."],"미정":[]},{"묶음":"파인 튜닝","fn":"FN-FTM-009","이름":"커밋 불러오기(롤백)","동작":"커밋을 골라 [커밋 불러오기]하면 그 커밋의 학습 설정과 지표 곡선을 불러오고, 다음 학습을 그 커밋에서 이어서 하도록 시작점을 바꾼다. source_model을 불러오면 다음 학습은 처음부터다. 시작점 변경은 작업 이력에 반영 대기로 남았다가 다음 학습 회차에 들어가면 「n회차에 반영」이 된다.","규칙":["커밋하지 않은 체크포인트가 있으면 불러오기 전에 확인 창으로 묻고, 불러오면 그 체크포인트와 지표는 지운다.","이어서 학습할 때 바꿀 수 있는 항목은 Learning Rate, Num Train Epochs, 데이터셋뿐이다. 어댑터 모양을 정하는 값(rank, alpha, 양자화 등)은 커밋 값으로 잠근다.","학습 방식은 생성 때 정한 값을 유지한다.","불러와도 커밋은 지워지지 않는다.","대기·설치중·실행중, 승인 대기, 커밋 저장 중에는 막는다."],"엣지":["source_model을 불러오면 잠금이 없다."],"미정":[]},{"묶음":"파인 튜닝","fn":"FN-FTM-010","이름":"학습 실행","동작":"실행 자원(노드 풀, GPU, CPU, RAM)과 실행 시점(즉시, 예약, 피크외 시간)을 정해 [실행]하면, 자원이 있으면 설치중을 거쳐 실행중이 되고 새 회차가 열린다. 시작할 때 전체 행을 다시 검사해 프리셋을 통과하지 못한 행은 빼고 학습하며 뺀 행 수를 작업 이력에 남긴다. 불러온 커밋이 있으면 그 커밋에서 이어서 학습한다.","규칙":["권한(컴퓨팅 자원 사용)이 없으면 [실행]이 [실행 요청]이 되고, 승인되면 요청한 자원과 실행 시점으로 실행한다.","[실행]이 막히는 이유는 다음 차례로 먼저 걸린 하나를 보인다: 다른 구성원 편집 중, 다른 구성원 실행 요청 대기, 저장하지 않은 변경, 커밋 파일 업로드 중, 베이스 모델 불러오는 중, Steps 배수 오류, 학습 데이터셋 없음, 프리셋 미선택, DeepSpeed 설정 파일 없음.","자원이 모자라면 대기(자원 부족)로 들어간다. 요청이 그 풀의 GPU 총량보다 크면 대기에 들어가지 않고 막는다(「이 풀의 GPU는 모두 n EA입니다.」).","실행하면 커밋하지 않은 지난 체크포인트와 지표가 지워지므로 실행 전에 확인 창으로 알린다."],"엣지":["요청 중에 권한이 생기면 대기 요청은 자동 취소되고 [실행]으로 바뀐다. 관리자로 지정된 경우만 요청을 남겨 본인이 승인하거나 거절한다.","예약이 담긴 요청을 승인하는 순간 예약 일시가 지났으면 [승인]을 막을지 정하지 않았다(P-10)."],"미정":["스토리지 사용률 95% 이상에서 실행 시작을 막을지 정하지 않았다(P-37).","같은 노드 풀에서 여러 대기 작업이 있을 때 반환 자원을 누구에게 먼저 줄지 정하지 않았다(P-01)."]},{"묶음":"파인 튜닝","fn":"FN-FTM-011~012","이름":"학습 대기 조회와 대기 취소","동작":"대기 중인 학습은 대기 사유(자원 부족, 예약, 피크외 시간, 승인 대기)와 실행 예정 일시, 필요한 자원을 보인다. 자원 부족은 자원이 돌아올 때, 예약은 지정 시각에, 피크외 시간은 GPUBASE가 배정한 시각에 자동으로 시작한다. [실행 취소]하면 확인 창 뒤 바로 대기를 끝내며, 잡은 자원이 없어 돌려줄 것도 없다.","규칙":["[실행 취소]는 권한이 필요 없다.","승인 대기는 [실행 취소]가 아니라 [요청 취소]로 끝낸다.","대기와 대기 취소는 회차 번호 없이 작업 이력에 두 줄로 남는다.","자원 부족으로 대기에 들어가면 실행자와 관리자에게 한 번 알린다. 대기 사유가 바뀌면 작업 이력에 시스템 줄만 남긴다."],"엣지":["취소 확인 창을 연 사이 자원이 잡혀 설치중이 되면 설치를 취소하고 중지로 둔다(권한 무관).","예약 시각에 자원이 모자라면 자원 부족 대기로 바뀐다.","대기 중에 노드 풀 할당이 줄어 요청이 풀 총량보다 커지면 대기를 끝내고 실패(사유 「노드 풀 총량 초과」)로 두고 실행자와 관리자에게 알린다."],"미정":["대기를 취소한 뒤 돌아갈 상태(대기 직전 상태인지, 생성됨인지) 정하지 않았다(N-05).","실행자가 아닌 구성원도 대기를 취소할 수 있는지 정하지 않았다(P-09).","대기가 길어질 때 다시 알리는 기준 시간의 처음 값을 정하지 않았다."]},{"묶음":"파인 튜닝","fn":"FN-FTM-013~014","이름":"학습 진행과 지표 곡선","동작":"실행 중에는 진행률, 에포크, 스텝, 처리 속도, 경과 시간을 보인다. Train Logging Steps마다 지표 점이 더해지고, Checkpoint Steps마다 체크포인트가 저장되어 곡선에 채운 점으로 보인다. 베이스 모델의 지표와 겹쳐 학습 효과를 비교한다.","규칙":["남은 시간은 계산하지도 보이지도 않는다. 경과 시간만 보인다.","불러온 커밋의 지표는 곡선에 「불러온 지표」로 구분한다."],"엣지":["학습 기록을 읽지 못하면 그 회차는 결과 불명으로 남고 [커밋]을 누르면 산출물을 확인할 수 없다고 알린다."],"미정":[]},{"묶음":"파인 튜닝","fn":"FN-FTM-015","이름":"학습 지표 다운로드","동작":"스텝을 골라 그 스텝까지의 학습 지표를 파일로 내려받는다.","규칙":["다운로드 권한이 필요하고, 없으면 요청 뒤 승인되면 1회 받는다."],"엣지":["지표가 없는 작업(학습 전, 업로드한 어댑터)은 막는다."],"미정":[]},{"묶음":"파인 튜닝","fn":"FN-FTM-016","이름":"학습 중지","동작":"실행 중인 학습을 [중지]하면 GPU를 바로 돌려주고, 마지막으로 저장한 스텝까지의 지표와 체크포인트를 남겨 커밋할 수 있게 하며, 그 회차는 중지로 끝난다.","규칙":["권한(컴퓨팅 자원 사용)이 없으면 학습 중지 요청을 보내고 승인되면 중지한다.","다음 실행: 커밋했으면 그 커밋에서 이어서 학습하고, 커밋하지 않았으면 남은 체크포인트와 지표를 지운 뒤 불러온 커밋부터(없으면 처음부터) 학습한다."],"엣지":["학습이 실패해도 마지막 저장 체크포인트는 남아 커밋할 수 있고, 자원은 자동으로 돌아간다. 실패 사유가 스토리지 부족이어도 같다.","끝난 학습에 온 중지 요청은 실행하지 않는다."],"미정":["권한 없는 구성원의 중지 요청이라는 개념을 남길지 배포 중지 요청과 함께 정하지 않았다(C-27)."]},{"묶음":"커밋 목록","fn":"FN-FTM-017~018","이름":"커밋 목록과 상세 조회","동작":"커밋 목록에서 커밋을 고르면 상세에서 커밋 정보, 학습 설정, 지표 곡선, 쓴 데이터셋, 그 커밋을 쓰는 모델 배포를 보인다. 기본 커밋(source_model)은 지표가 없다.","규칙":["저장 중인 커밋은 맨 위에 「저장 중」으로 서고, 끝날 때까지 선택, 불러오기, 수정, 삭제를 막는다."],"엣지":["커밋에서 생성한 작업이 이 커밋을 시작점으로 쓰는지도 함께 보인다."],"미정":[]},{"묶음":"커밋 목록","fn":"FN-FTM-019","이름":"커밋 생성","동작":"학습이 종료되거나 중지된 뒤 저장된 체크포인트를 골라 이름과 설명을 붙여 [커밋]하면 커밋으로 저장한다. 저장이 끝나면 커밋 목록에 올라 모델 배포에서 고를 수 있고, 그 커밋을 불러온 상태로 바뀐다.","규칙":["한 회차 안에서 체크포인트마다 한 번씩 여러 번 커밋할 수 있다. 같은 체크포인트를 다시 커밋하는 것만 막는다(「이미 커밋한 체크포인트입니다.」).","설치중·실행중이면 막는다(「학습이 끝나거나 중지된 뒤에 커밋할 수 있습니다.」).","커밋 저장 중에는 다른 커밋, [실행], 불러오기를 막는다.","스토리지 사용률 95% 이상이면 막는다.","권한이 필요 없다.","작업 이력에는 같은 회차에 「결과물 | 커밋 이름 | 생성」으로 남고, 회차 정보의 커밋 칸은 그 회차에서 만든 커밋 이름을 모두 적는다."],"엣지":["다음 학습을 실행하면 커밋하지 않은 체크포인트가 지워져 앞 회차 체크포인트는 더 커밋할 수 없다.","커밋하지 않고 끝난 회차는 커밋 칸에 「커밋 안 함」이 남는다."],"미정":[]},{"묶음":"커밋 목록","fn":"FN-FTM-020","이름":"커밋 수정, 삭제","동작":"커밋의 이름과 설명을 고치거나 커밋을 지운다. 이름 변경은 바로 보이고, 불러온 커밋을 지우면 source_model을 불러온 상태로 돌아간다.","규칙":["그 커밋을 쓰는 모델 배포가 하나라도 있으면 배포 상태와 상관없이 삭제를 막는다(「{모델 배포, …} 모델 배포가 커밋 {커밋}을 사용하고 있어 삭제할 수 없습니다. 모델 배포에서 다른 커밋으로 바꾸거나 모델 배포를 삭제한 뒤 삭제합니다.」).","이름과 설명 수정은 실행 중인 모델 배포가 쓸 때만 막는다. 종료된 배포가 쓰면 허용하고 그 배포의 생성자와 관리자에게 연결 자원 변경 알림을 보낸다.","대기·실행 중인 학습이 이어서 학습하는 커밋은 학습이 끝나거나 중지될 때까지 삭제를 막는다.","기본 커밋(source_model)은 수정, 삭제, 다운로드를 막는다.","여러 커밋을 골라 지울 때 쓰는 배포가 있는 커밋이 하나라도 섞이면 [삭제]를 막는다."],"엣지":["모델 배포가 다른 커밋으로 바꾸면 그 순간부터 앞 커밋을 지울 수 있다."],"미정":[]},{"묶음":"커밋 목록","fn":"FN-FTM-021","이름":"커밋 다운로드","동작":"커밋의 모델 파일을 내려받는다. 여러 커밋을 고르면 압축 파일 하나로 받는다. 받은 파일은 다른 AGENTBASE에서 커밋 파일 업로드로 쓸 수 있다.","규칙":["다운로드 권한이 필요하고, 없으면 요청 뒤 승인되면 요청자가 1회 받는다. 승인은 요청 때의 커밋 목록에 고정된다.","기본 커밋(source_model)은 받을 수 없다.","작업 이력에 다운로드로 남는다."],"엣지":["승인 뒤 7일 안에 받지 않으면 승인이 만료된다."],"미정":[]},{"묶음":"작업 이력","fn":"FN-FTM-022","이름":"학습 이력 조회","동작":"학습 회차별로 상태, 실행 시간, 실행자, 중지한 구성원, 승인자, 실행 자원, 데이터셋, 학습 방식, 커밋을 보이고, 회차 상세에서 자원 사용 요청, 학습 실행, 학습 설정 변경, 커밋 변경, 다운로드를 변경 전후, 반영 상태, 승인자와 함께 보인다.","규칙":["회차 표기는 n회차이고 0회차는 생성이다.","회차 상세의 작업 유형별 탭은 학습 결과(학습 지표, 만든 커밋)다.","학습 중에는 학습 설정을 바꿀 수 없어 그런 줄이 없다."],"엣지":["기록은 지우지 않고, 화면에는 이력 표시 기간 안의 회차만 보인다."],"미정":[]},{"묶음":"학습 구성","fn":"FN-FTM-026~027","이름":"학습 프레임워크(DeepSpeed, NVIDIA NeMo)","동작":"생성 때 학습 프레임워크를 하나 정한다. DeepSpeed는 ZeRO 단계로 옵티마이저 상태와 기울기를 GPU에 나누고, NVIDIA NeMo는 텐서 병렬과 파이프라인 병렬로 모델을 여러 GPU에 나눈다. 둘 다 학습 데이터셋과 config 파일을 받아 학습 지표와 체크포인트를 낸다.","규칙":["DeepSpeed가 처음 값이다. 파라미터는 learning rate, batch size, gradient accumulation steps이고 config 파일은 JSON이다.","NVIDIA NeMo의 파라미터는 learning rate, micro batch size, global batch size, epoch, 최대 입력 길이, 텐서 병렬 크기, 파이프라인 병렬 크기, LoRA 항목이고 config 파일은 YAML이다.","DeepSpeed 설정 파일이 없으면 [실행]을 막는다.","생성 뒤 바꿀 수 없다."],"엣지":["config 파일 형식이 맞지 않으면 적용하지 않고 형식 오류를 알린다."],"미정":[]},{"묶음":"학습 구성","fn":"FN-FTM-028~030","이름":"학습 방식(LoRA, QLoRA, DoRA)","동작":"생성 때 학습 방식을 하나 정한다. LoRA는 원본 가중치를 고정하고 저차원 행렬만 학습하고, QLoRA는 원본을 양자화해 올린 뒤 LoRA를 학습해 GPU 메모리를 가장 적게 쓰며, DoRA는 가중치를 크기와 방향으로 나눠 방향에 LoRA를 적용하고 크기 벡터를 함께 학습한다. 산출은 어댑터(DoRA는 크기 벡터 포함)가 든 체크포인트다.","규칙":["LoRA가 처음 값이다.","QLoRA 양자화 처음 값은 4비트이고 생성 뒤 바꿀 수 없다.","고른 모델이 지원하지 않는 방식은 비활성이고 이유를 보인다.","생성 뒤 바꿀 수 없다."],"엣지":[],"미정":[]},{"묶음":"학습 유형","fn":"FN-FTM-031~032","이름":"타입별 학습(LLM, VLM)","동작":"타입은 LLM(Text to Text), VLM(Image, Text to Text) 둘이다. 정의 항목은 베이스 모델, 학습 프레임워크, 학습 방식, 학습 파라미터, 학습·테스트 데이터셋이고, 데이터셋은 열 이름이 아니라 프리셋 판정으로 고른다. 산출은 학습 지표와 체크포인트다.","규칙":["학습 지표는 여덟이다: Loss(Train, Test), Perplexity(Train, Test), Grad Norm, Learning Rate, Generalization Gap, Token Accuracy.","데이터셋은 Parquet이다. 데이터셋 업로드 때는 열을 검사하지 않는다.","프리셋을 고르지 않은 데이터셋 줄이 있으면 [실행]을 막는다."],"엣지":["벤치마크 평가의 answer 열 조건은 이 판정과 따로다.","이미 만든 다른 타입(LLM, VLM 밖)의 작업은 그대로 두고 새로 만들 수만 없다."],"미정":[]}]},{"모듈":"모델 배포","코드":"SRV","개요":"모델 배포는 모델을 실행해 워크플로우, RAG, 데이터 파이프라인이 부를 수 있게 한다. 생성만 하면 자원을 잡지 않고 [배포]로 자원을 할당해 실행하며, 외부 엔드포인트와 상용 API는 자원 없이 접속만 확인해 쓴다. 호출 현황과 성능을 모니터링하고, LLM·VLM은 벤치마크로 평가해 리더보드에서 다른 모델과 비교한다.","상태":["생성됨 → [배포] → 설치중 → 배포중(자원이 있으면)","생성됨·중지·실패 → [배포] → 대기(자원 부족, 예약, 피크외 시간, 승인 대기) → 조건 충족(자동) → 설치중","대기 → [배포 중지] → 중지(대기·예약 취소, 반환할 자원 없음)","설치중 → 시작 실패(이미지 받기 실패 등) → 실패(회차 열리지 않음, 자원 자동 반환)","배포중 → [배포 중지](모두 중지) → 중지(GPU 반환, 회차 종료)","배포중(레플리카 2개 이상) → [배포 중지](1개 유지) → 배포중(레플리카 1개)","배포중 → 레플리카 응답 없음 → 자동 다시 시작 → 성공이면 배포중 유지, 실패면 실패(자원 자동 반환, 회차 종료)","배포중 → 버전·실행 설정 변경(롤링 업데이트 사용) → 배포중 유지(레플리카를 하나씩 교체)","외부 엔드포인트·상용 API: 생성(접속 확인) → 배포중 → [배포 중지] → 중지 → [배포](접속 확인) → 배포중","외부 엔드포인트·상용 API: 배포중 → 응답 없음 → 자동 다시 연결 → 실패하면 실패 → [배포] → 접속 성공 시 배포중"],"공통":["등록 유형은 Hugging Face, AGENTBASE, 외부 엔드포인트, 상용 API 넷이고 타입은 LLM, VLM, Embedding, Reranker, STT, TTS, Image Generation이다.","Hugging Face, AGENTBASE 모델 배포는 생성됨, 대기, 설치중, 배포중, 중지, 실패 여섯 상태를 쓴다. 실행중과 종료는 없다.","외부 엔드포인트와 상용 API는 자원을 점유하지 않고 배포중, 중지, 실패 셋만 쓴다. 배포와 배포 중지는 권한과 자원 창을 거치지 않는다.","실행 단위는 레플리카다. 점유 GPU는 레플리카 수 × 레플리카 1개의 GPU이고, 레플리카 1개의 자원(노드 풀, GPU, CPU, RAM)은 [배포] 창에서 정한다.","레플리카 수는 오토 스케일링이 최소~최대 사이에서 정하고, 오토 스케일링을 쓰지 않으면 1개다. 레플리카는 최대 16개다.","컴퓨팅 자원 사용 권한을 거치는 일은 [배포]와 오토 스케일링에서 자원을 늘리는 조작이다. [배포 중지 요청]은 두지 않는다.","배포중에는 컴퓨팅 자원과 추론 엔진 칸을 고칠 수 없다. 처리량은 오토 스케일링으로 늘리고, 그 밖의 자원 값은 배포를 중지한 뒤 바꾼다.","회차는 배포 회차다. 배포중에 들어간 순간 열리고 [배포 중지]나 실패로 닫힌다. 롤링 업데이트로 버전을 바꿔도 회차는 그대로다.","버전(커밋)을 바꾸면 이 모델을 쓰는 워크플로우는 다시 배포하지 않고 교체가 끝난 뒤의 호출부터 새 버전을 부르고, 생성자와 관리자에게 연결 자원 변경 알림이 간다.","레플리카가 멈추면 자동으로 다시 시작하고 생성자와 관리자에게 자동 복구 알림을 보낸다. 다시 시작에 실패하면 실패로 바꾸고 중단 알림을 보낸다.","자원 회수(오버쿼터)로 레플리카가 내려가면 대기로 돌아가고 자원이 반환되면 자동으로 다시 배포한다(D-33).","AGENTBASE 모델 배포가 쓰는 커밋은 배포 상태와 관계없이 파운데이션 모델에서 삭제할 수 없다(D-40). 그 커밋의 파운데이션 모델 삭제도 같다.","편집자는 변경 조작을 시작하는 순간 정해지고, 화면 이탈, 접속 종료, 3분 무조작으로 풀린다. 다른 구성원에게는 수정, 삭제, 배포, 중지, 평가 실행이 비활성이고 「{이름}님이 편집 중입니다.」다.","배포 전 워크플로우나 검색 DB가 없는 RAG가 쓰던 모델 배포를 지우면 그 참조는 「삭제됨」으로 남고 편집자가 해제한다(D-38).","작업 이력과 시스템 로그는 지우지 않는다. 관리 설정의 「이력 표시 기간」은 화면에 보이는 기간일 뿐이다.","오케스트레이터는 모델 배포 생성, 배포, 배포 중지를 입력자 권한으로 대신 실행한다. 삭제와 리더보드 등록은 하지 않고 그 화면을 안내한다(D-50, D-52)."],"기능":[{"묶음":"모델 배포 목록","fn":"FN-SRV-001~002","이름":"배포 목록 조회, 배포 검색","동작":"사용자가 모델 배포 메뉴를 열면 → 시스템이 모델 배포마다 상태, 이름, 설명, 모델, 실행 자원, 최근 업데이트 일시, 생성자를 돌려준다. 상태, 등록 유형, 타입으로 거르고 이름이나 모델로 검색한다.","규칙":["상태 필터는 종료를 뺀 일곱이다.","등록 유형과 타입은 목록 열로 두지 않는다.","검색어는 설명을 대상으로 하지 않는다.","실행 자원은 배포 중(설치중, 배포중)일 때만 적는다.","목록 줄 메뉴의 [배포]와 [배포 중지]는 상세와 같은 창을 연다."],"엣지":[],"미정":[]},{"묶음":"배포 생성","fn":"FN-SRV-003","이름":"Hugging Face 모델 배포","동작":"사용자가 이름, 설명, 타입, Hugging Face 모델 ID를 고르고 [생성]하면 → 시스템이 자원을 잡지 않은 모델 배포를 만든다 → 상태는 생성됨이고 [배포]로 실행한다.","규칙":["모델 버전은 모델 ID이고 리비전은 지정하지 않는다.","등록 유형, 타입, 모델은 생성 뒤 바꿀 수 없다.","이름은 필수이고 같은 이름은 저장을 막는다.","롤링 업데이트 사용 여부는 생성·수정 창과 [배포] 창에서 정한다."],"엣지":[],"미정":["Hugging Face 모델 목록의 출처(미리 받아 둔 모델 저장소)와 갱신 방법 개발 확인"]},{"묶음":"배포 생성","fn":"FN-SRV-004","이름":"AGENTBASE 모델 배포","동작":"사용자가 파인 튜닝한 AGENTBASE 모델과 그 커밋을 고르고 [생성]하면 → 시스템이 생성됨 상태의 모델 배포를 만든다. 커밋 목록은 커밋마다 체크포인트 step과 그 시점의 Test Loss를 함께 보여 준다.","규칙":["커밋은 생성 뒤에도 버전 교체로 바꿀 수 있다(D-41). 모델은 바꿀 수 없다.","Test Loss 측정값이 없으면 step만 적는다.","한 학습 회차에 커밋이 여럿이면 모두 고를 수 있다(D-42)."],"엣지":["이미 커밋이 지워진 채 남은 배포(기존 기록)는 [배포]를 막고 정보의 커밋 칸에 「삭제됨」을 적는다. 수정 창에서 다른 커밋을 고르면 다시 배포한다."],"미정":[]},{"묶음":"배포 생성","fn":"FN-SRV-005~006","이름":"외부 엔드포인트 등록, 상용 API 등록","동작":"사용자가 외부 엔드포인트(Base URL, 원격 서버의 모델 ID, API Key)나 상용 API(제공자 OpenAI·Anthropic·Google, 모델, API Key)를 넣고 [생성]하면 → 시스템이 접속을 확인하고 → 성공하면 자원 없이 바로 배포중으로 등록한다.","규칙":["접속 확인에 실패하면 저장을 막는다(D-39).","자원을 점유하지 않아 권한, 자원 창, 실행 시점, 오토 스케일링이 없다(「외부 엔드포인트와 상용 API는 레플리카가 없어 오토 스케일링을 사용할 수 없습니다.」).","Base URL이나 API Key를 고쳐 저장하면 저장할 때 접속을 다시 확인하고 실패하면 저장을 막는다.","API Key는 가려서 보이고 작업 이력에도 값을 남기지 않는다."],"엣지":["배포중에 응답이 없으면 자동으로 다시 연결해 보고, 다시 연결되면 배포중을 유지하며 생성자와 관리자에게 자동 복구 알림을 보낸다. 정해진 횟수 안에 실패하면 실패로 바꾸고 중단 알림을 보낸다(D-36).","실패 상태에서 [배포]하면 접속을 다시 확인해 성공하면 배포중, 실패하면 실패를 유지하고 사유를 시스템 로그에 남긴다."],"미정":["다시 연결 시도 횟수와 간격(C-25와 같은 값)"]},{"묶음":"배포","fn":"FN-SRV-007","이름":"자원 설정","동작":"사용자가 [배포] 창에서 레플리카 1개의 노드 풀, GPU 수, CPU·RAM 요청과 상한, 추론 엔진 설정(KV 캐시 비율, 최대 배치 크기), 예상 초당 요청 수, 오토 스케일링, 롤링 업데이트, 실행 시점을 정한다 → 시스템은 이 값을 이번 배포 회차의 실행 자원으로 저장한다.","규칙":["GPU 수는 1부터 그 노드 풀의 전체 GPU 수까지다.","CPU·RAM 상한은 요청 이상이어야 하고 비우면 요청과 같은 값이다.","권장 자원을 모델 크기로 안내한다.","배포중에는 이 칸들을 고칠 수 없다."],"엣지":["실행 중인 배포의 자원을 남은 GPU보다 크게 늘리는 변경은 막는다."],"미정":["배포 중 GPU 수 변경을 막을지, 반영 대기로 두고 다시 배포할 때 반영할지(C-16)"]},{"묶음":"배포","fn":"FN-SRV-008","이름":"오토 스케일링 설정","동작":"사용자가 오토 스케일링을 활성화하고 최소·최대 레플리카 수, 스케일링 기준, 기준값, 확장·축소 지속 시간을 정하면 → 시스템이 레플리카 평균이 기준값을 확장 지속 시간 이상 넘으면 1개 늘리고, 절반 미만이 축소 지속 시간 이상 이어지면 1개 줄이며, 늘린 뒤에는 확장 후 대기 시간 동안 판정을 보류한다. 비활성화하면 바로 해제하고 지금 레플리카 수를 유지한다.","규칙":["스케일링 기준은 LLM·VLM이 포화도(처음 값 80%)와 대기 요청(처음 값 4건), 그 밖의 타입이 GPU 사용률(처음 값 70%)이다.","최소 1~15, 최대는 최소보다 크고 16 이하다. 확장 지속 시간 처음 값 1분(30초~1시간), 축소 지속 시간 처음 값 5분(1분~6시간)이다.","자원을 늘리는 조작(활성화, 최소 올림, 최대 올림)만 컴퓨팅 자원 사용 권한을 거친다. 권한이 없으면 [다음] → 「오토 스케일링 적용 요청」·「오토 스케일링 설정 변경 요청」 → [요청]이고 승인 즉시 저장한다.","비활성화, 낮춤, 기준·기준값·지속 시간만 바꿈은 권한과 확인 창 없이 바로 저장한다. 비활성화하면 지금 레플리카 수를 유지한다.","생성됨, 중지, 실패에서는 비활성이고 대기, 설치중, 배포중에서 쓴다. 외부 엔드포인트와 상용 API는 늘 비활성이다.","같은 배포에 다른 컴퓨팅 자원 사용 요청이 기다리면 비활성이고, 내 요청이 기다리면 요청 취소 창을 연다.","승인 시점에 요청 값이 지금 값보다 낮아졌으면 [승인]을 막고 이유를 표시한다(D-26).","지표는 LLM, VLM, Embedding, Reranker가 15초마다, 그 밖의 타입이 1분마다 모인다."],"엣지":["최대 레플리카 × 레플리카 1개 GPU가 노드 풀에서 쓸 수 있는 GPU보다 크면 저장은 막지 않고 「최대 n개까지 확장하려면 GPU n EA가 필요합니다. 이 노드 풀에서 사용할 수 있는 GPU는 n EA입니다.」를 안내한다.","확장할 자원이 없으면 기존 레플리카로 계속 응답하고 확장은 대기했다가 자원이 반환되면 1개 늘린다. 확장 대기는 상태를 바꾸지 않고 작업 이력에 남기지 않는다(D-34).","확장 대기 중 부하가 내려가거나 오토 스케일링을 비활성화하면 확장 대기를 끝낸다."],"미정":["배포 중 비활성화 시 레플리카 수를 유지할지 1개로 줄일지 최종 확정(C-26, 현재 문장은 유지)","확장 대기와 새 배포 대기의 자원 배정 차례(P-02)","축소할 레플리카의 진행 중 요청을 끝내고 내릴지와 상한 시간(P-35)"]},{"묶음":"배포","fn":"FN-SRV-009~010","이름":"롤링 업데이트","동작":"사용자가 배포중인 AGENTBASE·Hugging Face 모델 배포의 버전(커밋)이나 실행 설정을 바꾸면 → 롤링 업데이트를 쓰는 배포는 새 레플리카 1개를 먼저 띄워 준비되면 이전 레플리카 1개를 내리기를 끝까지 되풀이해 호출을 멈추지 않는다 → 교체가 끝나면 작업 종료 알림을 보낸다. 롤링 업데이트를 쓰지 않으면 배포를 중지한 뒤 새 버전으로 다시 실행하고 그동안 호출은 응답하지 못한다.","규칙":["롤링 업데이트는 사용 여부 스위치 하나다. 최대 추가 수, 최대 중단 수, 준비 대기 시간은 받지 않는다.","교체하는 동안 레플리카 1개만큼 자원이 더 필요하다.","진행 중인 교체를 멈추는 조작은 없다. 끝나거나 실패할 때까지 진행한다(D-35).","대기, 설치중인 배포는 버전을 바꿀 수 없다(「대기 중이거나 설치 중인 모델 배포는 버전을 변경할 수 없습니다. 설치를 마친 뒤 변경할 수 있습니다.」).","평가 중에는 버전 교체를 막는다(「평가를 실행하고 있습니다. 평가 탭에서 [평가 중지]한 뒤 진행합니다.」).","버전 교체는 회차를 바꾸지 않고 작업 이력에 「모델 버전 | 롤링 업데이트 | 이전 → 새」 줄로 남는다."],"엣지":["새 버전 레플리카가 시작에 실패하면 새로 띄운 레플리카를 내리고 바꾼 레플리카도 기존 버전으로 되돌려 기존 버전으로 계속 응답하고 실패 알림을 보낸다.","배포 중인 워크플로우가 쓰는 모델 배포는 롤링 업데이트를 끈 채 버전을 바꿀 수 없다."],"미정":["교체에 필요한 추가 자원이 모자랄 때 막을지, 확장 대기처럼 기다렸다 교체할지(P-34)"]},{"묶음":"배포","fn":"FN-SRV-011","이름":"배포","동작":"사용자가 [배포] 창에서 자원과 실행 시점을 정해 [배포]하면 → 시스템이 자원이 있으면 설치중(자원 받기, 모델 적재)을 거쳐 배포중으로, 없거나 예약이면 대기로 둔다 → 배포중에 들어간 순간 새 배포 회차가 열린다. 외부 엔드포인트와 상용 API는 접속만 확인해 바로 배포중으로 바꾼다.","규칙":["권한이 없으면 [다음] → 「배포 요청」 → [요청]이고 승인 뒤 요청한 자원과 실행 시점으로 진행한다. 요청에는 메모를 쓴다. 거절과 취소는 요청 전 상태로 돌아간다.","요청 취소는 요청자 본인만 한다.","실행 시점은 즉시 실행, 지정 시각(반복 한 번·매일·매주, 종료 시각), 피크외 시간이다. 외부 엔드포인트와 상용 API는 즉시 실행만이다.","요청이 노드 풀 총량보다 크면 막는다(「이 풀의 GPU는 모두 n EA입니다.」).","대기에는 만료가 없고 조건이 풀리면 자동으로 시작한다(D-30). 대기 사유 창은 대기 차례와 예상 대기 시간을 적지 않는다.","다시 배포하는 창은 마지막 자원 값이 채워져 열린다."],"엣지":["예약 시각에 GPU가 모자라면 자원 부족 대기로 바뀐다.","대기 취소 확인 창을 연 사이 설치가 시작되면 설치를 취소하고 중지로 둔다(D-31).","승인 시점에 실행할 수 없으면 [승인]을 막는다(D-26)."],"미정":["대기 배정 차례, 대기 알림, 예약 종료·겹침, 대기 취소 주체, 승인 시 예약 경과(P-01, P-03~P-06, P-09, P-10)","레플리카 응답 없음을 실패로 판정하는 다시 시작 횟수(C-25)"]},{"묶음":"배포","fn":"FN-SRV-012","이름":"배포 중지","동작":"사용자가 [배포 중지]하면 → 레플리카가 1개면 확인 뒤 모두 중지하고 GPU를 반환해 회차를 닫는다. 레플리카가 둘 이상이면 중지 창에서 「모두 중지」와 「레플리카 1개 유지」를 고르고, 1개 유지는 엔드포인트를 살린 채 나머지 GPU만 반환한다. 대기나 예약 중이면 대기·예약을 취소한다.","규칙":["다음 중 하나면 비활성이고 가장 앞선 이유 하나를 적는다. 1) 오케스트레이터에 연결됨: 「오케스트레이터에 연결된 모델 배포입니다. GPUBASE에서 연결을 해제한 뒤 배포를 중지할 수 있습니다.」 2) 평가 중: 「평가를 실행하고 있습니다. 평가 탭에서 [평가 중지]한 뒤 진행합니다.」 3) 배포 중인 워크플로우가 직접 부르거나, 배포 중인 워크플로우가 연결한 RAG가 임베딩·리랭커·LLM으로 씀: 「{이름, …}에서 사용 중인 모델 배포입니다.」 4) 다른 구성원이 편집 중.","배포 중이 아닌 워크플로우, 워크플로우에 연결되지 않은 RAG, 데이터 파이프라인은 중지를 막지 않는다.","요청 흐름은 없다. 범위를 고르는 창이나 확인 창 뒤 바로 중지한다.","배포 중에 중지하면 남은 반복 예약도 지운다.","모델과 설정은 남아 [배포]로 다시 실행한다."],"엣지":["대기·예약 중의 [배포 중지]는 1)~3)과 관계없이 연다(편집 점유만 본다).","RAG를 거친 사용은 그 RAG가 배포중이 아니어도 배포 중인 워크플로우가 그 RAG를 연결했으면 막는다.","워크플로우 밖 RAG·데이터 파이프라인이 쓰던 배포를 중지하면 그 RAG의 검색 DB 생성과 파이프라인 실행은 그 단계에서 실패를 표시한다."],"미정":["레플리카가 여럿일 때 중지 범위 선택을 둘지 항상 모두 중지할지(C-17)","「1개 유지」를 고를 때 활성인 오토 스케일링을 함께 비활성화할지(N-06)","배포 중지를 권한 있는 구성원으로 제한할지(C-27)"]},{"묶음":"모니터링","fn":"FN-SRV-013~014","이름":"타입별 지표 조회, 자원 사용률 추이","동작":"사용자가 모니터링에서 기간을 고르면 → 시스템이 모델 타입에 맞는 성능 지표(예: LLM·VLM은 처리량, 첫 토큰 시간, 포화도, 대기 요청)와 레플리카 수, GPU·CPU·RAM 사용률 추이를 돌려준다.","규칙":["LLM, VLM, Embedding, Reranker는 15초마다, STT, TTS, Image Generation과 외부 엔드포인트, 상용 API는 1분마다 집계한다.","배포중이 아니면 수집하지 않고, 호출이 없어도 배포중이면 자원 사용률은 계속 수집한다.","외부 엔드포인트와 상용 API에는 자원 사용률이 없다.","오토 스케일링에 따른 레플리카 수 변화는 모니터링이 담고 작업 이력에는 남기지 않는다."],"엣지":[],"미정":[]},{"묶음":"모니터링","fn":"FN-SRV-015","이름":"상태 코드 집계","동작":"시스템이 호출을 응답 코드별로 세어 정상, 경고, 에러로 나눠 돌려준다.","규칙":["정상은 성공 응답, 경고는 권한 거부와 호출 한도 초과, 에러는 요청 오류와 서버 오류다."],"엣지":[],"미정":[]},{"묶음":"모니터링","fn":"FN-SRV-016~018","이름":"활동별 호출 조회, 호출처 조회, 호출 이력 조회","동작":"사용자가 호출을 AGENTBASE 호출과 서비스 호출로 나눠 보고, 이 배포를 부른 작업(워크플로우, RAG, 데이터 파이프라인)별 호출 현황과 호출 이력, 호출별 로그를 조회한다.","규칙":["조회는 작업 이력에 남기지 않는다.","호출 이력은 끝까지 내리면 다음 묶음을 이어 읽는다."],"엣지":[],"미정":[]},{"묶음":"평가","fn":"FN-SRV-019","이름":"평가 실행","동작":"사용자가 제공 벤치마크(10개)와 추가한 Custom 데이터셋을 골라 [평가 실행]하면 → 시스템이 고정 조건으로 모델을 평가하고 → 끝나면 결과를 저장하지 않은 결과로 남긴다. 사용자는 이름(필수)과 설명을 넣어 저장한다.","규칙":["LLM, VLM 모델 배포만 평가한다. 다른 타입은 평가가 비활성(「LLM, VLM 타입만 평가할 수 있습니다.」)이다.","배포중일 때만 [평가 실행]이 활성이다(「배포중 상태에서만 평가를 실행할 수 있습니다.」). 다른 구성원이 편집 중이면 막는다.","측정 조건은 고정이고 바꿀 수 없다(사고 모드 사용 안 함, 각 반복 1회 생성, 3회 반복 평균).","평가 중에는 이 배포의 배포 중지, 버전 교체, 삭제를 막는다.","평가 실행, 중지, 결과 저장은 작업 이력에 평가 줄로 남는다.","평가는 권한을 거치지 않는다."],"엣지":["저장하지 않은 결과가 있을 때 다시 실행하면 확인 창 뒤 그 결과를 지운다.","평가 도중 모델 배포가 실패하면 평가도 실패로 끝나고, 완료한 데이터셋의 결과를 남길지 중지와 같게 고른다.","Custom 벤치마크로 쓴 데이터셋 버전은 저장한 결과가 쓰는 동안 데이터 관리에서 지울 수 없다."],"미정":["저장하기 전 평가 설정이 쓰는 데이터셋 버전을 지울 때의 처리(N-01)"]},{"묶음":"평가","fn":"FN-SRV-020","이름":"평가 중지","동작":"사용자가 [평가 중지]하면 → 중지 창에서 「완료한 데이터셋 n개의 결과 저장」과 「결과를 저장하지 않음」을 고른다 → 저장을 고르면 완료한 데이터셋만 담은 결과가 중지 상태로 남고 이름을 넣어 저장한다.","규칙":["완료한 데이터셋이 0개면 저장 선택지는 비활성이다.","제공 벤치마크를 모두 측정하지 못한 결과는 종합 점수가 없다.","중지는 권한을 거치지 않는다."],"엣지":["작업 관리에서 평가를 중지하면 결과를 남기지 않는다."],"미정":[]},{"묶음":"평가","fn":"FN-SRV-021","이름":"평가 결과 관리","동작":"사용자가 이 배포의 평가 결과 가운데 비교할 결과를 고르고, 결과의 이름과 설명을 고치거나 결과를 지운다.","규칙":["실행 중인 결과는 수정·삭제할 수 없다(「실행 중인 결과는 {수정할|삭제할} 수 없습니다. 실행이 끝난 뒤 {수정|삭제}합니다.」).","다른 구성원이 편집 중이면 수정과 삭제를 막는다.","리더보드에 등록한 결과는 지울 수 없다(「리더보드에 등록한 결과는 삭제할 수 없습니다. 등록을 해제한 뒤 삭제합니다.」)."],"엣지":[],"미정":[]},{"묶음":"평가","fn":"FN-SRV-022","이름":"평가 결과 요약","동작":"사용자가 벤치마크를 고르면 → 시스템이 이 배포와 다른 모델의 점수와 순위를 그 벤치마크 기준으로 비교해 돌려준다.","규칙":["비교 대상은 고른 데이터셋을 모두 측정한 모델이다.","결과마다 평가 당시 모델 버전(커밋)을 적는다."],"엣지":[],"미정":[]},{"묶음":"평가","fn":"FN-SRV-023","이름":"벤치마크 리더보드 조회","동작":"사용자가 리더보드를 열면 → 시스템이 등록된 모델 배포마다 평가 당시 버전, 벤치마크별 점수, 종합 점수, 순위를 돌려준다.","규칙":["리더보드 줄은 평가할 때의 커밋과 점수로 고정된다. 새 버전의 점수는 다시 평가해 등록할 때 바뀐다.","등록한 결과는 배포 상태와 관계없이 리더보드에 남는다."],"엣지":["대시보드에서 연 리더보드는 고른 모델 배포가 없어 [리더보드 등록]·[등록 해제]가 비활성이다(D-44)."],"미정":[]},{"묶음":"평가","fn":"FN-SRV-024","이름":"리더보드 등록","동작":"사용자가 저장한 평가 결과 하나를 골라 [리더보드 등록]하면 → 리더보드 등록 권한이 있으면 즉시 리더보드에 반영한다. 다른 결과가 이미 등록되어 있으면 버튼은 [등록 결과 변경]이고 고른 결과로 바꾼다.","규칙":["모델 배포마다 평가 결과 하나만 등록한다.","등록할 수 있는 결과는 제공 벤치마크 10개를 모두 측정하고 종료해 저장한 결과다(종합 점수가 있음).","권한이 없으면 [리더보드 등록 요청]·[등록 결과 변경 요청]이고 승인 즉시 요청한 결과로 반영한다.","저장하지 않은 결과는 「저장한 결과만 리더보드에 등록할 수 있습니다. 이름을 입력해 결과를 저장하세요.」로 막는다.","10개를 다 측정하지 않은 결과는 「제공 벤치마크 10개를 모두 측정하고 종료한 결과만 리더보드에 등록할 수 있습니다.」로 막는다.","같은 배포에 다른 구성원의 리더보드 요청이 기다리면 요청 버튼은 비활성이다."],"엣지":["등록한 뒤 버전을 바꾸면 등록은 유지하고 「리더보드에 등록한 {결과}는 모델 버전 {버전}입니다.」를 안내한다."],"미정":[]},{"묶음":"평가","fn":"FN-SRV-025","이름":"리더보드 등록 해제","동작":"사용자가 [등록 해제]하면 → 권한이 있으면 바로 리더보드에서 내린다. 권한이 없으면 [등록 해제 요청] → 요청 창 → [요청]이고 관리자가 승인하면 해제한다.","규칙":["등록 해제는 설정 창 없이 요청 창이 바로 열린다.","해제한 결과는 결과 목록에 남고 이제 지울 수 있다."],"엣지":[],"미정":[]},{"묶음":"작업 이력","fn":"FN-SRV-026","이름":"작업 이력 조회","동작":"사용자가 작업 이력을 열면 → 시스템이 배포 회차마다 상태, 노드 풀, GPU, GPU 수, CPU, RAM, 레플리카 구성, 모델 버전, 실행 시간, 배포 일시, 실행자를 돌려준다. 회차를 열면 자원 사용 요청, 배포 시작과 중지, 설정 변경, 모델 버전 교체, 평가, 리더보드 등록, 다운로드를 변경 전후, 반영 상태, 승인자와 함께 보여 준다.","규칙":["회차 표기는 n회차이고 0회차는 생성이다.","외부 엔드포인트와 상용 API의 회차는 배포와 배포 중지로 나뉜다.","권한이 없어 요청한 배포는 「컴퓨팅 자원 사용 요청」 줄 뒤에 「배포 시작」 줄이 남고 두 줄 모두 승인자를 적는다.","자원 대기, 대기 끝에 중지, 설치중 실패는 회차 번호가 없는 줄이다.","응답 없음과 복구는 「시스템」 줄이고 회차를 유지한다. 응답 없음이 이어져 실패하면 그 회차가 실패로 끝난다.","오토 스케일링에 따른 레플리카 수 변화, 확장 대기, 모니터링 보기는 남기지 않는다.","목록은 최근 10회차(관리자가 3~50회차로 바꿈)를 보이고, 오래된 회차는 리포트에서 본다."],"엣지":[],"미정":[]},{"묶음":"정보","fn":"FN-SRV-027","이름":"배포 정보 조회","동작":"사용자가 정보를 열면 → 시스템이 이름, 설명, 등록 유형, 타입, 모델, 버전(커밋), 실행 자원, 레플리카, 오토 스케일링, 롤링 업데이트, 추론 엔진 설정, 엔드포인트, 이 배포를 쓰는 작업(자원 유형, 이름, 역할, 상태)을 돌려준다.","규칙":["실행 자원은 배포 중일 때만 적고 그 밖은 「실행 자원 -」 한 칸이다. 레플리카, 오토 스케일링, 최대 배치, 롤링 업데이트도 「-」다.","레플리카는 오토 스케일링을 쓰지 않으면 「1개」, 쓰면 「현재 n개, 오토 스케일링 a~b개」다.","오토 스케일링을 쓰지 않으면 「사용 안 함」, 롤링 업데이트를 쓰지 않으면 「-」다."],"엣지":[],"미정":[]},{"묶음":"정보","fn":"FN-SRV-028","이름":"모델 배포 수정, 복제, 삭제","동작":"사용자가 이름, 설명, 연결 설정(커밋, Base URL, API Key, 롤링 업데이트)을 고치거나, 설정을 복사해 생성됨 상태의 새 모델 배포로 복제하거나, 모델 배포를 지운다. 삭제하면 평가 결과와 리더보드 등록을 함께 지운다.","규칙":["등록 유형, 타입, 모델은 수정할 수 없다.","외부 엔드포인트와 상용 API는 복제할 수 없다.","삭제는 권한을 거치지 않고 이름을 입력해 확인한다. 삭제 창은 이 모델을 쓰는 작업을 모두 적는다.","다음 중 하나면 삭제가 비활성이다. 1) 대기·설치중·배포중: 「{대기 중인|설치 중인|배포 중인} 모델 배포는 삭제할 수 없습니다. [배포 중지] 뒤 삭제합니다.」 2) 평가 중 3) 배포된 워크플로우가 부름, 검색 DB가 준비된 RAG가 임베딩·리랭커·LLM으로 씀, 실행 중인 데이터 파이프라인이 씀: 「{이름, …}에서 사용 중인 모델 배포입니다.」 4) 승인 대기 중인 요청이 있음(리더보드 요청 포함) 5) 다른 구성원이 편집 중.","리더보드에 등록한 결과가 있어도 막지 않고, 삭제할 때 등록과 평가 결과를 함께 지운다는 문장을 창에 적는다(D-43)."],"엣지":["배포 전 워크플로우, 검색 DB가 없는 RAG가 쓰던 배포를 지우면 그 참조는 「삭제됨」으로 남는다.","중지 상태인데 오케스트레이터 연결이 남아 있으면 삭제는 막지 않고 「오케스트레이터가 이 모델을 사용하고 있어 홈 입력창과 오케스트레이터 패널도 사용할 수 없습니다.」를 창에 적는다.","커밋을 중지된 배포에서 바꾼 뒤에는 이전 커밋을 파운데이션 모델에서 지울 수 있다.","배포중인 배포가 쓰는 커밋의 이름·설명 수정은 막고, 중지된 배포가 쓰면 허용하며 그 배포 상세에 변경을 적는다."],"미정":[]}]},{"모듈":"RAG","코드":"RAG","개요":"RAG는 문서를 청킹하고 임베딩해 검색 DB 버전을 만들고, 워크플로우의 질의에 근거 문서를 검색해 돌려준다. 생성만 한 RAG는 자원을 잡지 않고, [배포]로 검색 컨테이너를 띄운 뒤 그 자원으로 검색 DB를 생성하고 검색, 테스트, 평가한다.","상태":["생성됨 → [배포] → 설치중 → 배포중(자원이 있으면)","생성됨·중지·실패 → [배포] → 대기(자원 부족, 예약, 피크외 시간, 승인 대기) → 조건 충족(자동) → 설치중","대기 → [배포 중지] → 중지(대기·예약 취소, 반환할 자원 없음)","설치중 → 시작 실패 → 실패(회차를 열지 않고 자원 자동 반환)","배포중 → [검색 DB 생성]·[검색 DB 업데이트] → 실행중 → 완료·중지·실패 → 배포중","배포중 → [배포 중지] → 중지(자원 반환, 검색 DB와 문서 유지)","배포중 → 응답 없음이 이어짐 → 실패(자원 자동 반환, 회차 종료)","검색 DB: 생성 중 → 완료 vN / 중지 「vN 중지」 / 실패 「vN 실패」(번호는 완료에만 확정, 다시 완료하면 같은 vN)"],"공통":["메뉴와 작업 유형 이름은 RAG다(화면 이름 「지식베이스」는 메뉴 이름 결정 전까지 문서에 쓰지 않는다).","상세는 설정, 검색 DB, 평가, 모니터링, 작업 이력, 정보로 나뉜다. 문서와 모델 설정(임베딩, 리랭커, Graph RAG의 LLM)은 설정에 함께 있다.","생성한 RAG는 자원을 점유하지 않는다. 자원은 [배포]부터 [배포 중지]나 실패까지 레플리카 수 × 레플리카 1개의 자원(노드 풀, GPU, CPU, RAM)을 점유한다.","검색 DB 생성, 업데이트는 배포한 검색 컨테이너의 자원으로 실행하고 자원을 더 잡지 않는다. 자원을 바꾸려면 배포를 중지한 뒤 [배포]에서 다시 정한다.","컴퓨팅 자원 사용 권한을 거치는 일은 [배포]와 오토 스케일링에서 자원을 늘리는 조작뿐이다. 권한이 없으면 [배포 요청] → 승인 뒤 실행이고, 요청 취소는 요청자 본인만 한다.","[배포 중지 요청]은 두지 않는다. 배포 중지는 자원을 반환하는 조작이라 요청과 승인을 거치지 않는다.","검색 DB 생성, 문서와 설정 변경, 검색 테스트, 평가는 권한을 거치지 않는다. 문서 다운로드만 다운로드 권한을 거친다.","회차는 배포 회차다. 배포중에 들어간 순간 열리고 [배포 중지]나 실패로 닫힌다. 0회차는 생성이다. 검색 DB 생성은 그 회차 안의 작업이다.","검색 DB는 버전(vN)으로만 부른다. 배포를 중지했다가 다시 배포하면 회차는 오르고 검색 DB 버전은 그대로다.","문서와 색인 관련 설정 변경은 「반영 대기」로 쌓였다가 다음 검색 DB 생성이 끝날 때 함께 반영된다. 반영 전까지 검색은 직전 버전과 그 설정으로 한다.","검색 DB 생성이 끝나면 연결한 워크플로우는 다시 배포하지 않고 다음 질문부터 새 버전으로 검색한다. 연결한 워크플로우의 작업 이력에 시스템 줄이 남는다.","업데이트 중과 업데이트 실패 뒤에는 마지막으로 완료한 버전으로 검색을 계속한다. 이전 버전으로 되돌리는 롤백은 없다(D-12).","편집자는 변경 조작을 시작하는 순간 정해지고, 화면 이탈, 접속 종료, 3분 무조작으로 풀린다. 다른 구성원에게는 수정, 삭제, 실행, 중지, 업로드, 검색 테스트, 대기 취소가 비활성이고 「{이름}님이 편집 중입니다.」다.","이미 시작한 검색 DB 생성, 업로드, 평가는 편집 점유가 풀려도 계속된다.","서비스 사용자의 RAG 접근 권한과 사용자별 한도는 권한 설정이 정한다. RAG 상세에는 권한 탭이 없다.","워크플로우가 연결한 RAG 하나에 서비스 사용자의 접근 권한이 없거나 한도를 넘으면 그 RAG만 빼고 요청을 이어 간다(D-15). 응답에 제외한 RAG를 알린다.","전체 일일 요청 상한은 모든 서비스 사용자의 검색 요청 합계다. 생성·수정 창에서 정하고 빈 값은 제한 없음이다. 넘은 요청은 막고 기록한다.","자원 회수(오버쿼터)로 검색 컨테이너가 내려가면 대기로 돌아가고 자원이 반환되면 자동으로 다시 배포한다(D-33).","배포 전 워크플로우가 참조하던 RAG를 지우면 그 참조는 「삭제됨」으로 남고 편집자가 해제한다(D-38).","작업 이력과 시스템 로그는 지우지 않는다. 관리 설정의 「이력 표시 기간」은 화면에 보이는 기간일 뿐이다.","오류와 영향 범위 알림은 전체 구성원에게 보내고 수신 설정에서 끌 수 있다(D-53). 영향 범위는 연결 사슬을 따라 서비스 API 오픈까지 적는다(D-54)."],"기능":[{"묶음":"RAG 목록","fn":"FN-RAG-001~002","이름":"RAG 목록 조회, 목록 탐색","동작":"사용자가 RAG 메뉴를 열면 → 시스템이 RAG마다 상태, 이름, 설명, 유형, 검색 DB 버전, 실행 자원, 최근 업데이트 일시, 생성자를 돌려준다. 상태와 유형으로 거르고 이름이나 생성자로 검색한다.","규칙":["상태 칩은 생성됨, 대기, 설치중, 배포중, 실행중, 중지, 실패 일곱 가운데 하나다(RAG에는 종료가 없다).","「검색 DB」 열은 지금 검색에 쓰는 버전 「v9」다. 업데이트 중이면 「v9, v10 업데이트 중」, 처음 생성 중이면 「생성 중」, 업데이트 실패면 마지막 성공 버전 「v9」, 처음 생성 실패면 「생성 실패」다.","검색어는 설명을 대상으로 하지 않는다.","실행 자원은 배포 중(설치중, 배포중, 실행중)일 때만 적고 그 밖은 「-」다.","목록 줄 메뉴의 [배포]와 [배포 중지]는 상세와 같은 창을 연다."],"엣지":["대기 칩은 승인 대기를 포함해 자원 점유가 0인 상태를 모두 뜻한다. 대기 사유는 줄을 선택해 대기 사유 창에서 본다."],"미정":[]},{"묶음":"RAG 목록","fn":"FN-RAG-003","이름":"RAG 작업 생성","동작":"사용자가 이름, 설명, 유형(Simple, Graph), 전체 일일 요청 상한을 넣고 [생성]하면 → 시스템이 자원을 잡지 않은 RAG를 만든다 → 상태는 생성됨이고 만든 사람이 편집자로 상세에 들어간다.","규칙":["이름은 필수이고 같은 이름은 저장을 막는다.","유형은 처음 값이 Simple이고 생성 뒤 바꿀 수 없다.","필수 모델은 Simple RAG가 임베딩 모델, Graph RAG가 LLM과 임베딩 모델이다. 리랭커는 선택이다.","전체 일일 요청 상한은 선택 칸이고 단위는 회다."],"엣지":["오케스트레이터도 RAG 생성(문서 연결, 배포, 검색 DB 생성)을 맡을 수 있고, 그 작업 이력 줄에는 오케스트레이터 경유를 표시한다(D-52)."],"미정":["전체 일일 요청 상한의 하루를 나누는 기준(정시 구간 또는 이동 구간)과 초기화 시각(P-36)","전체 상한을 사용자별 한도보다 작게 줄일 때의 처리(N-11)"]},{"묶음":"문서","fn":"FN-RAG-004","이름":"문서 목록 조회","동작":"설정의 문서 표가 RAG에 추가한 문서마다 구분(데이터 관리, 내 PC), 문서 이름, 확장자, 회차·버전, 반영 상태, 용량, 추가 일시, 메타데이터를 돌려준다.","규칙":["반영 상태는 반영 대기, 반영됨, 삭제 대기, 반영 실패 넷이다.","데이터 관리의 원본 데이터나 데이터셋이 새 회차·버전이 되면 문서 표의 회차와 버전은 즉시 바뀌고 반영 상태는 반영 대기가 된다."],"엣지":["만료 기한이 지난 문서는 표에 남지만 그 시각부터 검색 대상에서 빠진다."],"미정":[]},{"묶음":"문서","fn":"FN-RAG-005","이름":"문서 추가, 삭제","동작":"사용자가 [문서 추가]로 데이터 관리의 파일이나 데이터셋 버전, 내 PC 파일을 고르면 → 시스템이 문서 표에 반영 대기로 더한다 → 다음 검색 DB 생성이 끝나면 반영됨이 된다. 반영된 문서를 지우면 확인 뒤 삭제 대기가 되고, 다음 검색 DB 생성에서 빠진다.","규칙":["문서 추가와 삭제는 검색 DB 생성 중이나 평가 중에도 막지 않는다. 다음 생성에 반영한다.","내 PC 업로드는 받는 형식 16종이고, 받지 않는 형식이 하나라도 섞이면 업로드 전체를 막는다.","내 PC에서 올린 파일은 데이터 관리에 저장된다.","데이터셋 버전으로 추가한 문서는 버전을 바꿀 수 있고, 바꾸면 반영 대기다.","반영 대기 문서는 확인 없이 바로 지운다. 반영된 문서만 확인 창을 거쳐 삭제 대기가 된다.","삭제 대기는 [삭제 취소]로 되돌린다.","삭제한 문서를 근거로 저장해 둔 응답은 검색 DB 업데이트를 기다리지 않고 삭제하는 즉시 지운다.","문서 줄의 다운로드와 삭제는 줄 끝 메뉴에서 한다."],"엣지":["다른 구성원이 편집 중인 데이터 관리 파일은 고를 수 없다(「{이름}님이 편집 중인 데이터입니다. 편집이 끝난 뒤에 사용할 수 있습니다.」).","RAG에 연결한 데이터 관리 파일은 이름 변경, 이동, 삭제가 막히고, 내용을 바꾸면 새 회차로 저장되어 RAG는 새 회차를 가리키는 반영 대기가 된다.","스토리지 사용률이 95% 이상이면 내 PC 업로드를 막는다."],"미정":[]},{"묶음":"문서","fn":"FN-RAG-006","이름":"문서 미리보기","동작":"사용자가 문서를 선택하면 → 시스템이 문서 내용을 쪽 단위로 보여 준다. 조회만 하고 기록을 남기지 않는다.","규칙":["미리보기는 뷰어도 한다."],"엣지":[],"미정":[]},{"묶음":"문서","fn":"FN-RAG-007","이름":"문서 다운로드","동작":"사용자가 문서 하나를 다운로드하면 → 다운로드 권한이 있으면 확인 창(대상, 용량) 뒤 받고, 없으면 [다운로드 요청] → 요청 창 → [요청]이며 승인되면 같은 자리에서 1회 받는다. 받은 일은 감사 이력과 이 RAG의 작업 이력에 남는다.","규칙":["다운로드는 한 건씩이다.","승인은 1회 다운로드, 승인 후 7일 경과, 그 파일의 회차 변경 가운데 먼저 오는 때 끝난다.","요청은 구성원마다 따로이고 같은 파일에 다른 구성원의 요청이 있어도 막지 않는다.","요청 대기 중에는 요청자에게 다운로드가 비활성(「다운로드 요청이 관리자의 승인을 기다리고 있습니다.」)이고 [요청 취소]를 둔다."],"엣지":["요청 뒤 다운로드 권한을 받으면 대기 요청은 자동 취소되고 바로 받는다.","승인 뒤 받기 전에 파일이 새 회차로 바뀌면 승인이 끝나고 다시 요청한다."],"미정":[]},{"묶음":"문서","fn":"FN-RAG-008","이름":"메타데이터 스키마 설정","동작":"사용자가 [메타데이터 유형 설정]에서 항목 이름과 유형(텍스트, 숫자, 날짜와 시간)을 정해 저장하면 → 시스템이 이 RAG의 모든 문서에 같은 메타데이터 항목을 둔다.","규칙":["스키마는 RAG 하나에 하나이고 문서별 값은 FN-RAG-009에서 넣는다."],"엣지":[],"미정":["값이 들어 있는 메타데이터 항목을 지우거나 유형을 바꿀 때의 처리","스키마 변경이 반영 대기를 거치는지(검색 DB 다시 생성이 필요한지)"]},{"묶음":"문서","fn":"FN-RAG-009","이름":"문서별 메타데이터 입력","동작":"사용자가 문서마다 메타데이터 값과 만료 기한을 넣으면 → 시스템이 값을 저장하고 반영 대기로 둔다 → 다음 검색 DB 생성에서 반영된다. 만료 기한은 업데이트 없이 그 시각부터 검색 대상에서 문서를 뺀다.","규칙":["만료 기한은 선택이고 빈 값은 만료 없음이다.","값은 스키마의 유형을 따른다."],"엣지":["만료 기한을 지난 시각으로 고치면 그 즉시 검색에서 빠진다."],"미정":[]},{"묶음":"모델 설정","fn":"FN-RAG-010","이름":"임베딩 모델 선택","동작":"사용자가 배포중인 Embedding 타입 모델 배포 가운데 하나를 고르면 → 시스템이 반영 대기로 저장한다 → 다음 검색 DB 생성에서 전체 문서를 다시 색인할 때 적용된다.","규칙":["임베딩 모델을 바꾸면 업데이트 창의 반영 방식은 「전체 문서로 생성」만 고를 수 있다(「임베딩 모델이나 청킹 값이 변경되어 전체 문서로 생성만 선택할 수 있습니다.」).","검색 DB가 없으면 반영 대기 없이 바로 저장하고 첫 생성에 쓴다.","검색 DB 생성 중과 평가 중에는 설정을 고칠 수 없다(「검색 DB를 생성하는 동안에는 설정을 수정할 수 없습니다. 생성이 끝나거나 중지하면 수정할 수 있습니다.」)."],"엣지":["반영 대기 값을 저장 전 값으로 되돌리면 반영 대기에서 빠진다.","쓰던 임베딩 모델 배포가 중지되면 다음 검색 DB 생성은 그 단계에서 실패하고, 검색은 그 모델이 다시 배포될 때까지 실패로 센다."],"미정":[]},{"묶음":"모델 설정","fn":"FN-RAG-011","이름":"청킹 설정","동작":"사용자가 청킹 방식과 청크 최소, 최대 토큰, 오버랩, 검색 결과 수를 저장하면 → 시스템이 반영 대기로 둔다 → 다음 검색 DB 생성이 끝날 때 반영된다.","규칙":["청킹 값(최소, 최대, 오버랩)을 바꾸면 반영 방식은 「전체 문서로 생성」만이다.","검색 결과 수는 색인을 건드리지 않아 「변경분 반영」도 고를 수 있다."],"엣지":[],"미정":[]},{"묶음":"모델 설정","fn":"FN-RAG-012","이름":"리랭커 설정","동작":"사용자가 배포중인 Reranker 타입 모델 배포와 리랭크 결과 수를 고르면 → 시스템이 반영 대기로 저장한다 → 다음 검색 DB 업데이트가 끝날 때 반영된다.","규칙":["리랭커는 선택이고 없으면 정보의 리랭커 칸은 「-」다.","리랭커와 리랭크 결과 수는 색인을 건드리지 않아 「변경분 반영」으로도 반영한다.","Simple RAG의 LLM 변경도 같은 규칙이다."],"엣지":[],"미정":[]},{"묶음":"모델 설정","fn":"FN-RAG-013","이름":"그래프 추출 설정","동작":"Graph RAG에서 사용자가 엔티티와 관계를 추출할 LLM, 도메인, 엔티티 유형을 저장하면 → 시스템이 반영 대기로 두고 → 다음 검색 DB 생성에서 전체 문서로 그래프를 다시 추출한다.","규칙":["Graph RAG에만 있다.","LLM은 배포중인 LLM 타입 모델 배포에서 고른다.","셋 중 하나라도 바꾸면 반영 방식은 「전체 문서로 생성」만이다."],"엣지":[],"미정":[]},{"묶음":"검색 DB","fn":"FN-RAG-014~015","이름":"검색 DB 생성 실행, 생성 진행 표시","동작":"사용자가 [검색 DB 생성](처음) 또는 [검색 DB 업데이트]를 실행하면 → 시스템이 배포한 자원으로 문서를 청킹, 임베딩해 새 버전을 만들고 상태를 실행중으로 바꾼다 → 끝나면(완료, 중지, 실패) 배포중으로 돌아가고, 완료면 새 버전을 검색에 쓴다. 진행 중에는 부제가 「검색 DB를 생성하고 있습니다.」 또는 「검색 DB를 업데이트하고 있습니다.」이고 [생성 중지]·[업데이트 중지]로 멈춘다.","규칙":["RAG가 배포중일 때만 실행한다. 설치중이면 「설치 중입니다. 배포가 완료되면 검색 DB 생성을 할 수 있습니다.」, 대기면 「자원 대기 중입니다. 배포가 실행되면 …」, 생성됨·중지·실패면 「[배포]로 자원을 점유한 뒤 …」로 막는다.","실행 조건은 문서 1건 이상과 필수 모델이다. 모자라면 「{문서, 임베딩 모델 …}을 지정해야 {생성|업데이트}할 수 있습니다.」다.","스토리지 사용률이 95% 이상이면 「스토리지 사용률이 95% 이상이라 새로 생성할 수 없습니다.」로 막는다.","평가나 평가셋 생성 중에는 막는다(「평가를 실행하는 동안에는 검색 DB를 생성할 수 없습니다. 평가 탭에서 [중지]한 뒤 진행합니다.」).","업데이트 창은 반영 방식(변경분 반영, 전체 문서로 생성)을 고르고 자원은 받지 않는다. 배포한 실행 자원을 한 줄로 적는다.","반영할 문서도 바뀐 설정도 없으면 「반영 예정 문서가 없어 전체 문서로 생성만 선택할 수 있습니다.」다.","진행률과 세부 단계는 표시하지 않는다.","업데이트 중에는 직전 버전으로 검색을 계속한다(D-10). 처음 생성 중에는 검색할 버전이 없다.","버전 번호는 완료한 생성에만 붙는다. 중지·실패는 「v7 중지」, 「v7 실패」로 남고 다시 완료하면 같은 v7이다.","중지나 실패 뒤에도 반영 대기는 그대로 남아 다음 생성에 반영된다.","실패하면 실행자와 관리자에게 실패 알림을 보낸다.","검색 DB 생성은 권한을 거치지 않는다."],"엣지":["일부 문서만 처리에 실패해도 생성은 완료이고 새 버전을 준다. 실패 문서는 반영 실패로 두고 다음 업데이트에서 다시 처리한다. 모든 문서가 실패하면 생성 실패다(D-11).","생성 도중 스토리지가 가득 차면 실패(사유 스토리지 부족)이고 직전 버전이 있으면 그 버전으로 검색을 계속한다.","처음 생성이 실패하거나 중지되면 쓸 버전이 없어 테스트와 평가를 할 수 없다.","쓰던 모델 배포가 중지되어 있으면 그 단계에서 실패를 표시한다."],"미정":["업데이트가 끝난 뒤 직전 버전의 색인을 언제 지울지(P-19)","검색 DB 버전이 바뀔 때 연결한 워크플로우의 누구에게 알릴지(P-20)","[검색 DB 업데이트] 창에 연결한 워크플로우와 서비스 API 오픈 여부를 적을지(P-21)","생성 전에 예상 용량으로 잔여 스토리지를 검사할지(P-24)","검색 DB 생성 중 [배포 중지]를 막을지, 허용하고 「vN 중지」로 남길지(P-23)"]},{"묶음":"검색 DB","fn":"FN-RAG-016~017","이름":"청크 산점도 조회, 엔티티 관계 그래프 조회","동작":"사용자가 검색 DB를 열면 → 시스템이 지금 버전의 청크 분포와 청크 내용(Simple RAG), 엔티티 관계 그래프와 엔티티 정보(Graph RAG)를 돌려준다. 조회는 작업 이력에 남기지 않는다.","규칙":["검색 DB 버전이 있어야 보인다. 처음 생성 중이거나 버전이 없으면 비어 있다.","업데이트 중에는 직전 버전을 보여 준다."],"엣지":[],"미정":["배포 중지 상태에서 시각화를 열 수 있는지(검색 컨테이너 없이 조회 가능한지) 개발 확인"]},{"묶음":"검색 DB","fn":"FN-RAG-018~019","이름":"검색 테스트, 테스트 질문 저장","동작":"사용자가 질문을 넣어 [테스트]하면 → 시스템이 지금 검색에 쓰는 버전으로 검색해 결과 청크와 점수를 돌려준다. 질문을 저장해 두고 다시 실행한다. 테스트 한 번은 작업 이력 한 줄이다.","규칙":["RAG가 배포중이나 실행중이고 검색 DB 버전이 있을 때만 한다.","처음 생성 중이면 「검색 DB를 처음 생성하는 동안에는 테스트할 수 없습니다.」, 처음 생성 실패면 「검색 DB 생성이 실패해 테스트할 수 없습니다.」, 버전이 없으면 「검색 DB가 없어 테스트할 수 없습니다. [검색 DB 생성]을 실행하면 테스트할 수 있습니다.」다.","다른 구성원이 편집 중이면 [테스트]가 비활성이다."],"엣지":["업데이트 중이나 업데이트 실패 뒤에는 직전 성공 버전으로 테스트한다.","배포를 중지하면 검색 DB는 남지만 테스트는 비활성이다."],"미정":["테스트 검색을 전체 일일 요청 상한에 셀지 개발 확인"]},{"묶음":"검색 DB","fn":"FN-RAG-020","이름":"청크 품질 집계","동작":"검색 DB를 생성할 때 시스템이 청크 품질 문제를 문서별로 집계해 그 버전에 남긴다 → 작업 이력 회차 상세의 문서 품질에서 본다.","규칙":["집계는 생성마다 하고 버전에 묶인다.","처리에 실패한 문서는 반영 실패로 표시한다."],"엣지":[],"미정":[]},{"묶음":"평가","fn":"FN-RAG-021","이름":"평가셋 생성 설정","동작":"사용자가 평가셋 생성 모델과 대상 문서, 문항 수, 검증 항목을 고르면 → 시스템이 문서에서 질문과 기준 답변을 생성하고 검증 항목(기준 답변 근거, 답 노출, 중복, 질문 명확성, 형식, 질문 유형 비율)에 걸린 문항을 뺀다 → 남은 문항을 데이터 관리 /RAG/{RAG 이름}/evaluations/에 평가셋으로 저장한다.","규칙":["평가셋 생성 모델은 배포중인 LLM이다.","저장 위치는 저장할 때 바꿀 수 있다.","같은 이름이면 다음 버전으로 저장한다.","중복은 질문 의미 유사도로 판정해 뒤 문항을 뺀다.","제외한 문항과 걸린 검사는 평가셋 상세에서 본다.","평가셋 생성 중에는 검색 DB 생성, 설정 수정, 배포 중지, 삭제를 막는다."],"엣지":["검색 DB 버전이 없으면 평가셋 생성을 막는다."],"미정":[]},{"묶음":"평가","fn":"FN-RAG-022","이름":"실사용 질문 평가셋","동작":"사용자가 서비스 API로 오픈한 워크플로우가 받은 실제 질문을 기간과 워크플로우로 가져오면 → 시스템이 개인정보, 중복, 질문 명확성, 범위 밖을 검증해 걸린 문항을 빼고 평가셋으로 저장한다.","규칙":["서비스 요청 평가셋에는 기준 답변이 없다.","기준 답변이 없는 문항은 기준 답변이 필요한 지표를 계산하지 않는다.","비슷한 질문은 묶어 대표 질문 하나만 남긴다."],"엣지":["서비스 API로 오픈한 워크플로우가 이 RAG를 연결하지 않았으면 가져올 질문이 없다."],"미정":[]},{"묶음":"평가","fn":"FN-RAG-023","이름":"파일 평가셋 사용","동작":"사용자가 데이터 관리의 데이터셋이나 내 PC 파일을 평가셋으로 고르면 → 시스템이 평가 실행 때 형식, 중복, 답 노출, 질문 명확성을 검증해 빈 질문, 중복 질문, 길이 초과 문항을 빼고 → 업로드한 파일은 evaluations 폴더에 저장한다.","규칙":["받는 형식은 csv, jsonl, parquet이다.","원본 데이터 폴더는 대상이 아니다.","파일에 기준 답변 열이 없으면 기준 답변이 필요한 지표를 측정하지 않는다.","파일에는 근거 문서가 없어 기준 답변 근거는 검증하지 않는다."],"엣지":[],"미정":["평가셋이 고정해 쓰는 데이터셋 버전을 데이터 관리에서 지울 때의 처리(N-01)"]},{"묶음":"평가","fn":"FN-RAG-024","이름":"평가 실행","동작":"사용자가 평가셋, 답변 생성 모델, 채점 모델, 임베딩 모델, 평가 지표를 정해 [평가 실행]하면 → 시스템이 문항마다 지금 검색 DB 버전으로 검색하고 답변을 생성해 채점한다 → 문항마다 통과, 실패, 판정 보류를 정하고 결과를 저장하지 않은 결과로 남긴다.","규칙":["검색 DB 버전이 있을 때만 하고 검색 DB 생성 중에는 막는다(「검색 DB를 생성하는 동안에는 평가할 수 없습니다. 생성이 끝난 뒤 평가합니다.」).","채점 모델은 배포중인 LLM이다. 둘 이상이면 서로 다른 계열로 최대 3개이고, 점수는 중앙값, 판정은 다수결이다. 채점 모델 의견이 갈리면 판정 보류다.","같은 계열 둘을 고르면 「채점 모델을 2개 이상 선택할 때는 서로 다른 계열로 선택하세요.」로 막는다.","평가 지표는 Context Precision, Context Recall, Faithfulness, Response Relevancy, Factual Correctness, Semantic Similarity, Noise Sensitivity 가운데 고른다.","평가 중에는 검색 DB 생성, 설정 수정, 배포 중지, 삭제를 막는다.","결과에는 평가 당시 검색 DB 버전을 적는다.","평가 실행은 이 RAG의 작업 이력에 평가 줄로 남는다(검색 DB 버전과 지표)."],"엣지":["지금 버전이 아닌 검색 DB로 만든 평가셋은 「이전 검색 DB 기준 평가셋입니다. 확인을 선택해야 평가할 수 있습니다.」를 확인해야 실행한다.","저장하지 않은 결과가 있을 때 다시 실행하면 확인 창 뒤 그 결과를 지운다.","답변 생성 모델과 채점 모델이 같으면 막지 않고 점수가 높게 나올 수 있다고 안내한다."],"미정":["검색 DB 버전이 바뀐 뒤 이전 평가 결과를 유효로 볼지(P-22)"]},{"묶음":"평가","fn":"FN-RAG-025~026","이름":"평가 작업 진행 표시, 평가 중지","동작":"평가나 평가셋 생성이 도는 동안 시스템이 진행 상황을 보여 주고, 사용자가 [중지]하면 → 진행 중인 평가나 평가셋 생성을 멈춘다. 중지한 평가는 결과로 남기지 않는다.","규칙":["중지는 권한을 거치지 않는다.","다른 구성원이 편집 중이면 [중지]가 비활성이다."],"엣지":["작업 관리에서 중지해도 같은 결과다."],"미정":[]},{"묶음":"평가","fn":"FN-RAG-027~028","이름":"평가 결과 조회, 문항별 결과 조회","동작":"평가가 끝나면 시스템이 판정 분포, 실패 지점(검색, 답변 생성), 응답 시간과 토큰 사용량, 지표별 점수를 돌려준다. 문항을 고르면 질문, 검색 결과, 답변, 기준 답변, 지표별 점수, 판정 이유를 보여 준다.","규칙":["결과에는 평가 당시 검색 DB 버전과 평가 설정이 함께 남는다."],"엣지":[],"미정":[]},{"묶음":"평가","fn":"FN-RAG-029","이름":"기준 답변 입력","동작":"사용자가 기준 답변이 없는 문항(서비스 요청 평가셋 등)에 기준 답변을 넣으면 → 시스템이 그 문항만 다시 채점해 결과를 바꾼다.","규칙":["다시 채점은 원래 평가 설정(채점 모델, 지표)을 쓴다."],"엣지":[],"미정":["기준 답변 입력을 평가셋 원본에 덮어쓸지 새 버전으로 남길지 확정"]},{"묶음":"평가","fn":"FN-RAG-030, FN-RAG-032","이름":"평가 결과 목록 조회, 평가 결과 관리","동작":"사용자가 평가 결과에 이름과 설명을 넣어 저장하면 → 결과 목록에 남는다. 목록에서 결과를 고르면 그 결과를 보여 주고, 저장한 결과의 이름·설명을 고치거나 지운다.","규칙":["이름은 필수다.","저장하지 않은 결과가 있으면 새 평가를 실행하기 전에 확인한다.","실행 중인 결과는 수정·삭제할 수 없다."],"엣지":["RAG를 지우면 평가 결과도 함께 지운다(D-13)."],"미정":[]},{"묶음":"평가","fn":"FN-RAG-031","이름":"평가 결과 비교","동작":"사용자가 측정 조건이 같은 두 결과를 고르면 → 시스템이 지표별 점수와 판정 차이를 나란히 돌려준다.","규칙":["측정 조건은 평가셋(이름과 버전), 답변 생성 모델, 채점 모델, 평가 지표가 모두 같은 것이다.","조건이 다른 결과는 비교 대상으로 고를 수 없다."],"엣지":["검색 DB 버전은 측정 조건에 들지 않아 버전이 다른 두 결과를 비교할 수 있다. 버전은 결과마다 적는다."],"미정":[]},{"묶음":"평가","fn":"FN-RAG-033","이름":"저장된 평가셋 조회","동작":"사용자가 저장된 평가셋을 범위(현재 RAG, 전체 RAG)와 문항 소스(문서에서 생성, 서비스 요청, 파일 업로드)로 거르고 이름으로 검색하면 → 시스템이 평가셋마다 문항, 검증 결과, 사용 이력을 돌려준다.","규칙":["다른 RAG의 평가셋도 고를 수 있다.","평가셋 파일은 데이터 관리에 있고 사람이 지우기 전까지 남는다."],"엣지":[],"미정":[]},{"묶음":"모니터링","fn":"FN-RAG-034~037","이름":"검색 현황 조회, 검색 단계 분석, 문서 활용 조회, 워크플로우 활용 조회","동작":"사용자가 모니터링을 열고 기간을 고르면 → 시스템이 검색 요청 수, 성공률, 응답 시간, 에러 발생 현황, 검색 단계별 소요 시간(임베딩, 검색, 리랭크), 문서별 검색 활용 정도, 이 RAG를 쓰는 워크플로우별 검색 현황을 돌려준다.","규칙":["배포중이 아니면 수집하지 않는다.","성공과 결과 없음은 정상, 권한 거부와 한도 초과는 경고, 시간 초과와 검색 실패만 에러로 센다.","조회는 작업 이력에 남기지 않는다."],"엣지":["배포를 중지해도 지난 기간의 지표는 남아 조회한다."],"미정":[]},{"묶음":"모니터링","fn":"FN-RAG-038","이름":"검색 컨테이너 오토 스케일링","동작":"사용자가 오토 스케일링을 활성화하고 최소·최대 레플리카 수, 스케일링 기준(CPU 사용률, RAM 사용률), 기준값, 확장·축소 지속 시간을 정하면 → 시스템이 레플리카 평균이 기준값을 확장 지속 시간 이상 넘으면 1개 늘리고, 기준값 절반 미만이 축소 지속 시간 이상 이어지면 1개 줄인다. 비활성화하면 바로 해제하고 지금 레플리카 수를 유지한다.","규칙":["자원을 늘리는 조작(활성화, 최소 올림, 최대 올림)만 컴퓨팅 자원 사용 권한을 거친다. 권한이 없으면 [다음] → 「오토 스케일링 적용 요청」·「오토 스케일링 설정 변경 요청」 → [요청]이고 승인 즉시 저장한다.","비활성화, 최소·최대 낮춤, 기준·기준값·지속 시간만 바꿈은 권한과 확인 창 없이 바로 저장한다.","최소 1~15, 최대는 최소보다 크고 16 이하다. 사용률 기준값의 처음 값은 70%, 확장 지속 시간 1분(30초~1시간), 축소 지속 시간 5분(1분~6시간)이다.","생성됨, 중지, 실패에서는 비활성(「[배포]한 뒤 오토 스케일링을 설정할 수 있습니다.」)이고 대기, 설치중, 배포중, 실행중에서 쓴다.","같은 RAG에 다른 컴퓨팅 자원 사용 요청이 기다리면 비활성이다(「{행위} 요청이 관리자의 승인을 기다리고 있습니다. 승인되거나 취소된 뒤 오토 스케일링을 변경할 수 있습니다.」).","내 요청이 기다리는 동안 스위치와 설정은 요청 취소 창을 연다.","승인 시점에 요청 값이 지금 값보다 낮아졌으면 [승인]을 막고 이유를 표시한다(D-26)."],"엣지":["최대 레플리카 × 레플리카 1개 자원이 노드 풀 잔여보다 크면 저장은 막지 않고 필요한 양과 쓸 수 있는 양을 안내한다.","확장할 자원이 없으면 기존 레플리카로 계속 응답하고 확장은 대기했다가 자원이 반환되면 1개 늘린다. 확장 대기는 상태를 바꾸지 않고 작업 이력에 남기지 않는다(D-34)."],"미정":["확장 대기와 새 배포 대기가 같은 노드 풀에서 기다릴 때 차례(P-02)","축소할 때 그 레플리카의 진행 중 요청을 끝내고 내릴지와 상한 시간(P-35)"]},{"묶음":"작업 이력","fn":"FN-RAG-039","이름":"작업 이력 조회","동작":"사용자가 작업 이력을 열면 → 시스템이 배포 회차마다 상태, 검색 DB 버전, 노드 풀, GPU, CPU, RAM, 실행 시간, 배포 일시, 실행자를 돌려준다. 회차를 열면 그 회차의 배포 시작과 중지, 문서·설정 변경, 검색 DB 생성, 테스트, 평가, 다운로드를 변경 전후, 반영 상태, 승인자와 함께 보여 준다.","규칙":["회차 표기는 n회차이고 0회차는 생성이다. 시스템 로그의 회차 번호와 같다.","검색 DB 버전 칸은 회차 시작 때 쓰던 버전이고, 그 회차 안에서 새로 만들었으면 「v6 → v9」다.","버전 번호는 완료한 생성에만 붙는다.","자원 대기, 대기 끝에 중지, 설치중 실패는 회차 번호가 없는 줄이다.","반영 대기 변경은 생성이 끝나면 「v9에 반영」으로 바뀐다.","응답 없음, 복구, 연결 데이터의 새 회차처럼 시스템이 바꾼 일은 「시스템」 줄이고 실행자는 「-」다.","목록은 최근 10회차(관리자가 3~50회차로 바꿈)를 보이고, 오래된 회차는 리포트에서 본다.","조회, 저장하지 않은 편집, 편집 점유, 검색 DB 시각화 보기는 남기지 않는다."],"엣지":["배포하지 않은 동안 바꾼 문서와 설정은 다음 배포 회차의 작업 내역에 이어 남는다."],"미정":[]},{"묶음":"정보","fn":"FN-RAG-040","이름":"RAG 정보 조회","동작":"사용자가 정보를 열면 → 시스템이 이름, 설명, 유형, 생성자, 생성 일시, 검색 구성(임베딩, 리랭커, LLM, 청킹 값), 실행 자원, 레플리카, 오토 스케일링, 전체 일일 요청 상한, 이 RAG를 쓰는 워크플로우와 상태를 돌려준다.","규칙":["실행 자원은 배포 중일 때만 적고 그 밖은 「실행 자원 -」 한 칸이다.","레플리카는 오토 스케일링을 쓰지 않으면 「1개」, 쓰면 「현재 n개, 오토 스케일링 a~b개」다.","전체 일일 요청 상한은 「n회」 또는 「제한 없음」이다."],"엣지":[],"미정":[]},{"묶음":"정보","fn":"FN-RAG-041","이름":"RAG 수정, 복제, 삭제","동작":"사용자가 이름, 설명, 전체 일일 요청 상한을 고치거나, 설정과 문서를 복사해 새 RAG로 복제하거나, RAG를 지운다. 복제본은 생성됨으로 만들어지고 자원과 검색 DB가 없다. 삭제하면 내 PC에서 올린 문서, 검색 DB의 모든 버전, 검색 컨테이너, 평가 결과를 함께 지운다.","규칙":["유형은 바꿀 수 없다. 실행 자원은 배포를 중지한 뒤 다시 배포해 바꾼다.","배포 상태(대기, 설치중, 배포중, 실행중)이면 삭제할 수 없다(「배포 중인 RAG는 삭제할 수 없습니다. [배포 중지] 뒤 삭제합니다.」)(D-37).","검색 DB 생성 중, 평가·평가셋 생성 중, 배포된 워크플로우가 연결함, 승인 대기 요청이 있음, 다른 구성원이 편집 중이면 삭제를 막는다.","삭제는 권한을 거치지 않고 이름을 입력해 확인한다. 삭제 창에 함께 지우는 범위와 남는 범위를 적는다.","데이터 관리에서 고른 문서와 평가셋 파일은 데이터 관리에 남는다(D-13)."],"엣지":["배포 전 워크플로우가 연결했으면 삭제를 막지 않고 「배포 전 사용 중인 곳: {이름}. 삭제하면 해당 작업에 삭제된 참조로 표시됩니다.」를 적는다.","내 PC에서 올린 문서를 다른 작업이 쓰면 그 파일은 지우지 않는다.","다른 RAG가 이 RAG에서 만든 평가셋을 써도 평가셋 파일은 남으므로 막지 않는다."],"미정":["복제본에 저장한 테스트 질문과 평가셋 연결을 복사할지"]},{"묶음":"배포","fn":"FN-RAG-042","이름":"RAG 배포","동작":"사용자가 [배포] 창에서 노드 풀, GPU, CPU·RAM 요청과 상한, 오토 스케일링, 실행 시점(즉시 실행, 지정 시각, 피크외 시간)을 정하면 → 시스템이 자원이 있으면 설치중을 거쳐 배포중으로, 없거나 예약이면 대기로 둔다 → 배포중에 들어간 순간 새 배포 회차가 열린다.","규칙":["권한이 없으면 [다음] → 「배포 요청」 → [요청]이고 승인 뒤 요청한 값과 실행 시점으로 진행한다. 요청에는 메모를 쓴다.","요청 취소는 요청자 본인만 한다. 거절·취소되면 요청 전 상태로 돌아간다.","CPU·RAM 상한은 요청 이상이어야 하고 비우면 요청과 같은 값이다.","요청이 노드 풀 총량보다 크면 대기에 들지 않고 막는다(「이 풀의 GPU는 모두 n EA입니다.」).","대기에는 만료가 없다. 조건이 풀리면 자동으로 설치중이 되고 취소는 사람이 한다(D-30).","대기 사유 창은 실행 시점, 대기 사유, 실행 예정 일시, 종료 시각, 대기 시간을 적고 대기 차례와 예상 대기 시간은 적지 않는다.","지정 시각은 반복(한 번, 매일, 매주)과 종료 시각을 받고, 종료 시각에 배포를 중지한다.","다시 배포하는 창은 마지막 자원 값이 채워져 열린다."],"엣지":["예약 시각에 자원이 모자라면 자원 부족 대기로 바뀌고 실행 예정 일시는 「GPU 반환 시(예약 일시 …)」다.","대기 취소 확인 창을 연 사이 설치가 시작되면 설치를 취소하고 중지로 둔다(D-31).","승인 시점에 대상 상태가 바뀌어 실행할 수 없으면 [승인]을 막고 이유를 표시한다(D-26)."],"미정":["자원 반환 시 대기 작업 배정 차례(P-01)","대기 사유가 바뀔 때 기록과 알림(P-03)","자원 부족 대기 알림(P-04)","예약 종료 시각까지 시작 못 한 대기(P-05)","반복 예약 겹침(P-06)","대기 취소 주체를 실행자와 관리자로 좁힐지(P-09)","승인 시 예약 일시가 지난 경우(P-10)"]},{"묶음":"배포","fn":"FN-RAG-043","이름":"RAG 배포 중지","동작":"사용자가 [배포 중지]하면 → 시스템이 검색 컨테이너를 내리고 실행 자원을 반환한다 → 상태는 중지이고 회차가 닫힌다. 검색 DB와 문서는 남아 다시 배포하면 그대로 검색한다. 대기나 예약 중이면 대기·예약을 취소한다.","규칙":["평가나 평가셋 생성 중이면 막는다(「{평가를 실행하는|평가셋을 생성하는} 동안에는 배포를 중지할 수 없습니다. 평가 탭에서 [중지]한 뒤 진행합니다.」).","배포 중인 워크플로우가 연결하면 막는다(「배포 중인 {워크플로우, …}에서 사용 중이라 중지할 수 없습니다. 그 워크플로우의 배포를 중지하면 중지할 수 있습니다.」).","다른 구성원이 편집 중이면 막는다.","요청 흐름은 없다. 확인 창 뒤 바로 중지한다.","배포 중에 중지하면 남은 반복 예약도 함께 지운다."],"엣지":["대기·예약 중의 [배포 중지]는 자원을 점유하지 않아 평가·연결 조건과 관계없이 연다(편집 점유만 본다).","배포 전 워크플로우가 연결한 RAG를 중지하면 창에 「{이름} 워크플로우의 테스트에서 이 RAG를 검색할 수 없습니다.」를 적는다."],"미정":["검색 DB 생성 중의 배포 중지 처리(P-23)","배포 중지를 컴퓨팅 자원 사용 권한이 있는 구성원으로 제한할지(C-27)"]}]},{"모듈":"도구","코드":"TOL","개요":"도구는 워크플로우의 에이전트 노드가 외부 시스템을 부르는 수단이다. 시스템이 두는 제공 도구와 사용자가 외부 REST API·MCP 서버로 만드는 Custom 도구가 있고, 도구는 [배포]로 도구 컨테이너를 띄운 뒤 선택한 동작만 에이전트에서 호출한다.","상태":["생성됨 → [배포] → 설치중 → 배포중(자원이 있으면)","생성됨·중지·실패 → [배포] → 대기(자원 부족, 예약, 피크외 시간, 승인 대기) → 조건 충족(자동) → 설치중","대기 → [배포 중지] 또는 마지막 동작 해제 → 중지(반환할 자원 없음)","설치중 → 시작 실패(MCP 서버가 동작 목록을 주지 못함 포함) → 실패(회차 열리지 않음, 자원 자동 반환)","배포중 → [배포 중지] 또는 마지막 동작 해제 → 중지(자원 반환)","배포중 → 응답 없음 → 자동 다시 연결 → 성공이면 배포중 유지, 정해진 횟수 실패면 실패"],"공통":["메뉴와 작업 유형 이름은 도구다(화면 이름 「도구·MCP」는 메뉴 이름 결정 전까지 문서에 쓰지 않는다).","도구는 배포형 작업이고 상태는 생성됨, 대기, 설치중, 배포중, 중지, 실패다. 실행중은 없다.","제공 도구도 같은 상태를 쓰고 [배포]해야 호출된다.","생성한 도구는 자원을 점유하지 않는다. [배포]부터 [배포 중지]나 실패까지 레플리카 수 × 레플리카 1개의 자원(노드 풀, CPU, RAM, 필요하면 GPU)을 점유한다.","컴퓨팅 자원 사용 권한을 거치는 일은 [배포]와 오토 스케일링에서 자원을 늘리는 조작뿐이다. [배포 중지 요청]은 두지 않는다.","회차는 배포 회차다. 배포중에 들어간 순간 열리고 [배포 중지]나 실패로 닫힌다. 정보 수정, 엔드포인트 추가·삭제, 동작 선택 변경은 그 회차 안의 작업이다.","에이전트 노드는 배포중인 도구의 선택한 동작만 고르고 호출한다.","동작 선택 해제는 즉시 반영된다. 그 밖의 연결 설정 변경은 다음 배포 회차부터 적용되고, 지금 회차는 바꾸기 전 값으로 호출한다.","도구는 공용 인증 값을 갖지 않는다(D-18). 외부 REST API는 인증 방식, MCP 서버는 인증 항목(환경 변수 이름)만 정하고, 값은 워크플로우 테스트와 서비스에서 부르는 사용자가 그때마다 개인 인증으로 넣는다. 그래서 도구에는 연결 상태와 인증 만료가 없다.","서비스 사용자의 개인 인증이 없는 도구가 호출되면 그 도구만 빼고 요청을 이어 가며 응답에 인증 필요 안내를 담는다(D-17).","서비스 사용자의 도구 접근 권한과 사용자별 호출 한도는 권한 설정이 정한다. 전체 시간당 호출 상한은 생성·수정 창에서 정하고 빈 값은 제한 없음이다.","한도를 넘은 호출은 그 호출만 거절 문장으로 돌려주고 기록하며 요청은 계속 진행한다.","도구 호출이 실패하면 그 호출만 실패로 처리하고, 워크플로우는 노드 실패의 기본 동작을 따른다.","외부 서비스가 응답하지 않으면 자동으로 다시 연결해 보고, 다시 연결에 실패하면 실패로 바꾸고 생성자와 관리자에게 중단 알림을 보낸다(D-36). 그동안 들어온 호출은 시간 초과 에러로 센다.","외부 서비스가 서비스 사용자의 인증을 거부하면 다시 연결하지 않고 그 호출만 「외부 인증 실패」로 센다. 도구 상태와 다른 사용자의 호출은 그대로다.","편집자는 변경 조작을 시작하는 순간 정해지고, 화면 이탈, 접속 종료, 3분 무조작으로 풀린다. 다른 구성원에게는 수정, 삭제, 배포, 중지, 동작 선택이 비활성이고 「{이름}님이 편집 중입니다.」다.","자원 회수(오버쿼터)로 도구 컨테이너가 내려가면 대기로 돌아가고 자원이 반환되면 자동으로 다시 배포한다(D-33).","배포 전 워크플로우가 참조하던 도구나 동작이 사라지면 그 참조는 「삭제됨」·「사용 안 함」으로 남고 편집자가 해제한다(D-38).","작업 이력과 시스템 로그는 지우지 않는다. 관리 설정의 「이력 표시 기간」은 화면에 보이는 기간일 뿐이다."],"기능":[{"묶음":"도구 목록","fn":"FN-TOL-001~002","이름":"도구 목록 조회, 목록 탐색","동작":"사용자가 도구 메뉴를 열면 → 시스템이 제공 도구와 Custom 도구마다 상태, 이름, 설명, 도구 유형, 카테고리, 실행 자원, 최근 업데이트 일시, 생성자를 돌려준다. 도구 유형과 카테고리로 거르고 도구 이름이나 주소로 검색한다.","규칙":["검색어는 설명을 대상으로 하지 않는다.","실행 자원은 배포 중(설치중, 배포중)일 때만 적고 그 밖은 「-」다.","목록에는 연결 상태와 인증 만료 칸이 없다.","목록 줄 메뉴의 [배포]와 [배포 중지]는 상세와 같은 창을 연다."],"엣지":[],"미정":[]},{"묶음":"도구 목록","fn":"FN-TOL-003","이름":"외부 REST API 도구 생성","동작":"사용자가 이름, 설명, 카테고리, 기본 주소, API 인증 방식, 시간 제한, 전체 시간당 호출 상한, 엔드포인트(메서드, 경로, 동작 이름과 설명, 파라미터)를 넣고 [생성]하면 → 시스템이 자원을 잡지 않은 Custom 도구를 만든다 → 상태는 생성됨이고 엔드포인트마다 동작이 하나씩 생긴다.","규칙":["기본 주소와 인증 방식은 생성 뒤 바꿀 수 없다.","이름은 필수이고 같은 이름은 저장을 막는다.","시간 제한의 처음 값은 60초다.","인증 방식을 「인증 없음」으로 정하면 개인 인증 없이 호출한다.","파라미터는 이름, 타입, 설명, 필수 여부를 받는다."],"엣지":["오케스트레이터는 도구 등록만 하고 배포하지 않는다."],"미정":[]},{"묶음":"도구 목록","fn":"FN-TOL-004","이름":"MCP 서버 도구 생성","동작":"사용자가 실행 방식(실행 중인 서버의 주소, 서버를 실행할 명령)과 주소 또는 실행 명령, 인증 항목, 시간 제한, 전체 시간당 호출 상한을 넣고 [생성]하면 → 시스템이 Custom 도구를 만든다. [연결 테스트]는 서버의 동작 목록을 미리 보기만 하고 저장하지 않는다.","규칙":["주소(또는 실행 명령)와 인증 항목은 생성 뒤 바꿀 수 없다.","동작 목록은 [배포]할 때마다 서버에서 다시 받는다(D-19). 새 동작은 선택하지 않은 상태로 더하고, 있던 동작의 선택 여부는 그대로 둔다.","동작이 아직 없는 MCP 서버 도구도 [배포]를 막지 않는다. 배포할 때 동작 목록을 받는다."],"엣지":["서버가 목록을 주지 못해 시작에 실패하면 설치중 → 실패이고 이전 목록은 그대로 둔다."],"미정":["다시 받은 목록에서 이전에 선택한 동작이 사라졌을 때의 처리(N-07)"]},{"묶음":"도구 목록","fn":"FN-TOL-005","이름":"Custom 도구 수정, 삭제","동작":"사용자가 Custom 도구의 이름, 설명, 카테고리, 시간 제한, 전체 시간당 호출 상한을 고치거나 도구를 지운다. 삭제하면 도구 컨테이너와 설정을 지우고 복구할 수 없다.","규칙":["바꾼 연결 설정은 다음 배포 회차부터 적용된다.","실행 자원은 배포를 중지한 뒤 다시 배포해 바꾼다.","배포 상태(대기, 설치중, 배포중)이면 삭제할 수 없다(「배포 중인 도구는 삭제할 수 없습니다. [배포 중지] 뒤 삭제합니다.」)(D-37).","배포된 워크플로우가 연결함(「{워크플로우}에서 사용 중인 도구입니다.」), 승인 대기 요청이 있음, 다른 구성원이 편집 중이면 삭제를 막는다.","제공 도구는 삭제할 수 없다(「제공 도구는 삭제할 수 없습니다. 사용하지 않을 동작은 동작 목록에서 선택을 해제합니다.」).","삭제는 권한을 거치지 않고 이름을 입력해 확인한다."],"엣지":["배포 전 워크플로우가 연결했으면 삭제를 막지 않고 그 노드에 「삭제됨」 참조를 남긴다.","삭제한 도구를 쓰던 워크플로우의 생성자와 관리자에게 「연결한 {이름}이 삭제되었습니다.」 알림을 보낸다."],"미정":[]},{"묶음":"모니터링","fn":"FN-TOL-006~009","이름":"도구 호출 현황 조회, 동작별 현황 조회, 도구 컨테이너 자원 조회, 워크플로우 활용 조회","동작":"사용자가 모니터링을 열고 기간을 고르면 → 시스템이 호출 수, 성공률, 응답 시간, 에러 발생 현황, 동작별 호출 현황, 도구 컨테이너의 CPU·RAM 사용률 추이, 이 도구를 쓰는 워크플로우와 호출 이력을 돌려준다.","규칙":["권한 거부와 호출 한도 초과는 경고로 따로 세고, 외부 서비스의 시간 초과, 외부 인증 실패, 외부 서비스 오류만 에러로 센다.","배포중이 아니면 수집하지 않는다.","인증 상태는 보이지 않는다. 인증 문제는 호출마다 「외부 인증 실패」로만 남는다.","조회는 작업 이력에 남기지 않는다."],"엣지":[],"미정":["전체 시간당 호출 상한의 한 시간을 정시 구간으로 볼지 최근 한 시간으로 볼지(P-36)"]},{"묶음":"모니터링","fn":"FN-TOL-010","이름":"도구 컨테이너 오토 스케일링","동작":"사용자가 오토 스케일링을 활성화하고 최소·최대 레플리카 수, 스케일링 기준(CPU 사용률, RAM 사용률), 기준값, 확장·축소 지속 시간을 정하면 → 시스템이 기준값을 넘는 상태가 지속되면 1개 늘리고, 절반 미만이 지속되면 1개 줄인다. 비활성화하면 바로 해제하고 지금 레플리카 수를 유지한다.","규칙":["규칙은 RAG·모델 배포 오토 스케일링과 같다(FN-RAG-038). 자원을 늘리는 조작만 권한을 거치고, 권한이 없으면 [다음] → 요청 → 승인 즉시 저장이다.","비활성화, 낮춤, 기준만 바꿈은 권한과 확인 창 없이 바로 저장한다.","생성됨, 중지, 실패에서는 비활성(「[배포]한 뒤 오토 스케일링을 설정할 수 있습니다.」)이다."],"엣지":["확장할 자원이 없으면 기존 레플리카로 응답하고 확장은 대기했다가 자원이 반환되면 늘린다(D-34)."],"미정":[]},{"묶음":"정보","fn":"FN-TOL-011~012","이름":"도구 정보 조회, 제공 동작 조회","동작":"사용자가 정보를 열면 → 시스템이 이름, 설명, 도구 유형, 카테고리, 기본 주소 또는 서버 주소·실행 명령, 인증 방식·인증 항목, 시간 제한, 전체 시간당 호출 상한, 실행 자원, 레플리카, 이 도구를 쓰는 워크플로우, 도구가 제공하는 동작 목록과 선택 여부를 돌려준다.","규칙":["인증 값은 저장하지 않으므로 표시하지 않는다.","실행 자원은 배포 중일 때만 적고 그 밖은 「실행 자원 -」다.","전체 시간당 호출 상한은 「n회」 또는 「제한 없음」이다."],"엣지":[],"미정":[]},{"묶음":"정보","fn":"FN-TOL-013","이름":"동작 선택","동작":"사용자가 에이전트 노드에서 쓸 동작을 선택하거나 해제하면 → 시스템이 저장하고 노드에 보이는 동작을 바꾼다. 선택은 바로 노드에 보이고, 해제도 즉시 반영된다. 배포중인 도구에서 마지막 동작을 해제하면 확인 창 뒤 배포를 중지하고 실행 자원을 반환한다.","규칙":["배포 중인 워크플로우가 쓰는 동작은 해제할 수 없다(「배포 중인 {워크플로우, …}에서 사용 중이라 선택을 해제할 수 없습니다. 그 워크플로우의 배포를 중지하면 해제할 수 있습니다.」).","동작을 더 선택하는 것은 막지 않는다.","동작 선택 변경은 그 배포 회차의 작업 내역(사용 ↔ 사용 안 함)으로 남는다."],"엣지":["대기·설치중인 도구에서 마지막 동작을 해제하면 대기나 설치를 끝내고 중지로 둔다.","해제한 동작을 쓰던 배포 전 워크플로우의 노드는 그 동작을 「사용 안 함」으로 표시하고 생성자에게 연결 자원 변경 알림을 보낸다."],"미정":["배포 중지를 권한 있는 구성원으로 제한하면(C-27) 권한이 없는 구성원의 마지막 동작 해제도 막는다"]},{"묶음":"정보","fn":"FN-TOL-014","이름":"REST API 엔드포인트 관리","동작":"사용자가 외부 REST API 도구의 엔드포인트(메서드, 경로, 동작 이름과 설명, 파라미터)를 추가, 수정, 삭제하면 → 시스템이 동작 목록을 바꾼다. 추가한 엔드포인트는 선택하지 않은 동작으로 생긴다.","규칙":["기본 주소는 바꿀 수 없고 경로만 바꾼다.","배포 중인 워크플로우가 쓰는 동작의 엔드포인트는 삭제할 수 없다.","수정한 엔드포인트는 다음 배포 회차부터 적용된다."],"엣지":[],"미정":["배포 중인 워크플로우가 쓰는 엔드포인트의 경로·파라미터 수정을 막을지"]},{"묶음":"작업 이력","fn":"FN-TOL-015","이름":"작업 이력 조회","동작":"사용자가 작업 이력을 열면 → 시스템이 배포 회차마다 상태, 노드 풀, GPU, CPU, RAM, 실행 시간, 배포 일시, 실행자를 돌려준다. 회차를 열면 배포 시작과 중지, 설정과 실행 자원 변경, 동작 선택 변경, 엔드포인트 변경, 다운로드를 변경 전후, 반영 상태, 승인자와 함께 보여 준다.","규칙":["회차 표기는 n회차이고 0회차는 생성이다.","자원 대기, 대기 끝에 중지, 설치중 실패는 회차 번호가 없는 줄이다.","응답 없음, 복구, 실패처럼 시스템이 바꾼 일은 「시스템」 줄이고 실행자는 「-」다.","배포하지 않은 동안 바꾼 내용은 다음 배포 회차의 「이전 회차 대비 변경」으로 보인다.","인증 상태 변화(인증 만료) 줄은 두지 않는다. 공용 인증이 없기 때문이다.","모니터링 지표 보기, 도구 호출 시험은 남기지 않는다(호출 시험은 워크플로우 테스트 줄로 남는다)."],"엣지":[],"미정":[]},{"묶음":"배포","fn":"FN-TOL-016","이름":"도구 배포","동작":"사용자가 [배포] 창에서 노드 풀, CPU·RAM 요청과 상한, 필요하면 GPU, 오토 스케일링, 실행 시점을 정하면 → 시스템이 자원이 있으면 설치중을 거쳐 배포중으로, 없거나 예약이면 대기로 둔다 → 배포중에 들어간 순간 새 배포 회차가 열리고 MCP 서버 도구는 동작 목록을 다시 받는다.","규칙":["선택한 동작이 없는 도구는 [배포]가 비활성(「선택한 동작이 없습니다. 정보 탭에서 동작을 선택한 뒤 배포합니다.」)이다. 동작이 아직 없는 MCP 서버 도구는 예외다.","권한이 없으면 [다음] → 「배포 요청」 → [요청]이고 승인 뒤 요청한 값과 실행 시점으로 진행한다. 요청 취소는 요청자 본인만 한다.","요청이 노드 풀 총량보다 크면 막는다.","대기에는 만료가 없고, 대기 규칙과 예약 규칙은 RAG 배포(FN-RAG-042)와 같다."],"엣지":["대기 취소 확인 창을 연 사이 설치가 시작되면 설치를 취소하고 중지로 둔다(D-31)."],"미정":["대기 배정 차례, 대기 알림, 예약 겹침, 대기 취소 주체(P-01, P-03~P-06, P-09)"]},{"묶음":"배포","fn":"FN-TOL-017","이름":"도구 배포 중지","동작":"사용자가 [배포 중지]하면 → 시스템이 도구 컨테이너를 내리고 실행 자원을 반환한다 → 상태는 중지이고 회차가 닫힌다. 대기나 예약 중이면 대기·예약을 취소한다.","규칙":["배포 중인 워크플로우가 사용 중이면 막는다(「배포 중인 {워크플로우, …}에서 사용 중이라 중지할 수 없습니다.」).","다른 구성원이 편집 중이면 막는다.","요청 흐름은 없다. 확인 창 뒤 바로 중지한다.","배포 중에 중지하면 남은 반복 예약도 지운다."],"엣지":["대기·예약 중의 [배포 중지]는 사용 조건과 관계없이 연다(편집 점유만 본다).","중지한 도구를 쓰던 배포 전 워크플로우는 테스트에서 그 도구를 부를 수 없다."],"미정":["배포 중지를 권한 있는 구성원으로 제한할지(C-27)"]}]},{"모듈":"워크플로우","코드":"WFL","개요":"모델, RAG, 도구를 노드로 연결해 요청 하나를 처리하는 흐름을 설계하고, 배포한 뒤 테스트와 보안 평가로 확인한다. 실행할 때는 요청한 사용자의 권한으로 쓸 수 있는 RAG와 도구만 쓴다.","상태":["생성됨 → [배포] → 설치중 → 배포중","설치중 → 설치 실패 → 실패","배포중 → [배포 중지] → 배포 중지 중(진행 중인 대화가 끝나기를 기다림) → 중지","중지 → [배포] → 설치중 → 배포중(새 회차)","실패 → [배포] → 설치중","배포중 → [이 회차로 롤백] → 지금 회차 중지 → 설치중 → 배포중(새 회차)","배포중 → 보안 평가 [실행] → 배포중(평가 중 잠금) → 평가 끝·중지 → 배포중"],"공통":["상태는 생성됨, 설치중, 배포중, 중지, 실패 다섯이다. 대기와 실행중은 없다. 한 번도 배포하지 않은 상태 이름은 「생성됨」이다(D-09).","워크플로우 배포는 실행 자원을 점유하지 않는다. 컴퓨팅 자원 사용 권한이 필요 없고 자원 대기도 없다. 배포, 배포 중지, 롤백은 모든 구성원이 승인 없이 한다.","배포 회차는 배포가 배포중에 들어간 순간 하나 생긴다. 설치에 실패한 배포는 회차를 만들지 않는다. 생성은 0회차다.","편집 점유는 워크플로우 하나에 한 명이다. [편집]으로 편집 모드에 들어가는 순간 편집자가 되고 [편집 완료], 화면 이탈, 접속 종료, 조작 없음 3분 가운데 하나로 풀린다. 2분 30초에 「30초 뒤 뷰어로 전환합니다.」를 알린다. 3분과 30초는 고정 값이다.","뷰어는 조회, 메뉴 이동, 필터, 검색, 정렬, 복사만 한다. 수정, 삭제, 배포, 배포 중지, 테스트 질문, 보안 평가 [실행]은 비활성이고 「{이름}님이 편집 중입니다.」를 보인다. 인계 요청과 강제 인계는 없다.","캔버스는 자동 저장이다. 3분 무조작으로 뷰어가 되어도 고친 내용은 남는다.","배포중에는 프롬프트 계열(에이전트·외부 에이전트 프롬프트, Built-in 추가 기준·점검 기준·추가 지시)만 고친다. 노드, 연결선, 모델, RAG·도구 연결, 변수, 규칙 조건, 입출력 형식은 비활성이고 「배포 중인 워크플로우에서는 프롬프트만 수정 가능합니다. 배포를 중지한 뒤 수정합니다.」를 보인다. 이름과 설명은 배포 중에도 고친다.","설치중, 배포 중지 중, 보안 평가 실행 중에는 편집, 삭제, 롤백을 막는다.","보안 평가를 실행하는 동안 편집, 배포, 배포 중지, 삭제, 롤백, 평가 설정 변경을 막고 「보안 평가를 실행하고 있습니다. 보안 평가를 중지한 뒤 진행합니다.」를 보인다.","노드가 고른 모델 배포, RAG, 도구, 호출 대상 워크플로우가 삭제되면 참조를 지우지 않고 「삭제됨」으로 남기며, 편집자가 다시 고르거나 해제하기 전까지 배포를 막는다(D-38).","워크플로우가 배포중인 동안 연결한 모델 배포, RAG, 도구의 배포 중지와 삭제를 막는다.","연결한 RAG, 도구, 모델 배포가 바뀌면 다시 배포하지 않고 바뀌는 순간부터 쓴다. 회차는 그대로이고, 작업 이력에 시스템 줄, 상세 부제에 변경 문장을 남기고 워크플로우 생성자와 관리자에게 연결 자원 변경을 알린다.","실행할 때 요청한 사용자의 권한으로 쓸 수 있는 RAG와 도구만 쓴다. 권한이 없는 RAG 하나는 요청 전체를 거부하지 않고 그 RAG만 빼고 실행한다(D-15). 개인 인증이 안 된 도구는 빼고 계속하고 응답에 인증 필요 안내를 붙인다(D-17).","외부에서 들어오는 호출은 서비스 API 하나로 받는다. 보안 평가는 서비스 API 오픈의 필수 조건이 아니다. 통과 기준도 두지 않고 방어율은 참고값으로만 보인다(D-01).","작업 이력은 지우지 않는다. 관리 설정의 「이력 표시 기간」은 화면에 보이는 기간일 뿐이고, 리포트와 롤백, 회차 선택 다운로드는 모든 기록과 회차를 쓴다(C-23, P-25).","오케스트레이션이 실행되는 동안에는 편집자 여부와 상관없이 워크플로우 화면 전체가 보기 전용이다."],"기능":[{"묶음":"워크플로우 목록","fn":"FN-WFL-001~002","이름":"워크플로우 목록 조회, 목록 탐색","동작":"사용자가 목록에 들어오면 워크플로우를 상태, 이름, 설명, 최근 업데이트 일시, 생성자와 함께 보여 준다. 상태로 거르고 이름이나 생성자로 검색한다. 목록은 조회만 하므로 편집 점유와 관계없이 모든 구성원이 본다.","규칙":["상태 거르기는 생성됨, 설치중, 배포중, 중지, 실패를 대상으로 한다.","검색 대상은 이름과 생성자다. 설명은 검색하지 않는다.","목록의 상태는 배포 상태만 뜻한다. 홈의 실행중 작업 수에 배포중인 워크플로우는 넣지 않는다."],"엣지":["오케스트레이터가 만든 워크플로우도 만든 순간 목록에 나타나고 생성자는 입력자다."],"미정":[]},{"묶음":"워크플로우 목록","fn":"FN-WFL-003","이름":"워크플로우 생성","동작":"사용자가 이름과 설명을 넣고 [생성]하면 시작 노드, 에이전트 노드, 출력 노드를 연결한 초기 구성으로 워크플로우를 만든다. 만든 사용자가 편집을 점유한 채 상세의 편집 모드로 열린다. 상태는 생성됨이고 작업 이력 0회차가 생긴다.","규칙":["이름은 필수이고 100자까지다. 「/」는 쓸 수 없고 같은 이름(대소문자 무시)은 막는다. 먼저 걸린 이유 하나만 보인다.","설명은 선택이고 500자까지다.","응답 캐시의 처음 값은 사용 안 함이다. 서비스 API 오픈의 응답 캐시도 사용일 때만 실제로 적용한다.","생성에는 권한이 필요 없다."],"엣지":["같은 이름이 있어 실패하면 입력값을 두고 이유만 보인다."],"미정":[]},{"묶음":"설정 > 캔버스","fn":"FN-WFL-004","이름":"편집 모드 진입","동작":"사용자가 [편집]을 누르면 편집 점유를 얻고 편집 모드에 들어간다. [편집 완료]를 누르면 점유를 놓고, 배포중이면 그 순간 바뀐 프롬프트를 운영 중인 회차에 반영한다. 3분 동안 조작이 없으면 편집 모드를 끝내고 뷰어로 바꾼다.","규칙":["다른 구성원이 편집 중이면 [편집]은 비활성이고 「{이름}님이 편집 중입니다.」를 보인다.","설치중이면 「설치 중이라 수정할 수 없습니다. 설치가 끝나면 수정할 수 있습니다.」, 배포 중지 중이면 「배포를 중지하는 중입니다. 중지가 끝나면 수정할 수 있습니다.」로 막는다.","보안 평가를 실행하는 동안에는 편집 모드에 들어갈 수 없다.","편집 모드에서는 [배포]와 보안 평가 [실행]을 막는다. [편집 완료] 뒤에 한다.","같은 워크플로우 안의 탭 이동은 이탈이 아니다."],"엣지":["같은 구성원이 브라우저 탭 둘로 열면 점유는 하나이고, 조작이 없는 탭이 먼저 점유를 놓을 수 있다.","브라우저가 비정상 종료되면 접속 종료로 보고 점유를 놓는다. 판정이 늦으면 3분 무조작으로 놓인다.","편집 시작과 종료는 작업 이력에 남기지 않는다."],"미정":["배포 중 프롬프트를 고치던 편집자가 3분 무조작으로 뷰어가 되면 고친 프롬프트를 운영 회차에 반영하는지(C-14). 개발 구현은 저장만 하고 반영하지 않는다."]},{"묶음":"설정 > 캔버스","fn":"FN-WFL-005","이름":"자동 저장","동작":"편집 모드에서 바꾼 노드, 연결, 설정은 조작할 때마다 자동으로 저장한다. 저장은 정의만 바꾸고 배포 상태와 회차는 바꾸지 않는다. 배포중이면 자동 저장된 프롬프트도 [편집 완료]를 누르기 전까지 운영 회차에 반영하지 않는다.","규칙":["저장하지 않은 편집 같은 중간 상태는 작업 이력에 남기지 않는다.","한 번도 저장하지 않은 워크플로우는 배포 전 검증에서 막는다."],"엣지":["뷰어 전환, 화면 이탈, 접속 종료 때도 자동 저장한 내용은 남는다."],"미정":[]},{"묶음":"설정 > 캔버스","fn":"FN-WFL-006","이름":"편집 되돌리기","동작":"편집 모드에서 [되돌리기]와 [다시 실행]으로 직전 편집을 취소하거나 다시 적용한다. 되돌린 결과도 자동 저장한다.","규칙":["배포중에는 프롬프트 변경만 되돌린다.","배포 상태가 바뀌면 되돌리기 기록을 비운다."],"엣지":["편집 모드를 끝냈다가 다시 들어오면 앞 편집의 되돌리기 기록은 이어지지 않는다."],"미정":[]},{"묶음":"설정 > 캔버스","fn":"FN-WFL-007","이름":"설계 그래프 조회","동작":"워크플로우의 노드 구성과 연결선을 캔버스로 보여 준다. 뷰어도 확대, 이동, 노드 선택으로 설정 값을 읽을 수 있다.","규칙":["확대와 이동은 정의를 바꾸지 않아 저장과 작업 이력에 남지 않는다."],"엣지":["삭제된 연결 대상은 노드에 「삭제됨」으로, 사용 안 함이 된 도구 동작은 「{동작} 사용 안 함」으로 보인다."],"미정":[]},{"묶음":"설정 > 캔버스","fn":"FN-WFL-008","이름":"노드 추가, 연결, 편집","동작":"편집자가 노드를 추가하고 연결선으로 잇고, 노드 이름 수정, 복제, 삭제와 연결선 삭제를 한다. 노드 종류는 시작, 출력, 에이전트, Built-in(마스킹, 가드레일, 코드 에이전트), 외부 에이전트, 규칙, 사용자 검토다. 바꾼 내용은 자동 저장한다.","규칙":["배포중에는 노드 추가, 삭제, 복제, 이름 수정과 연결선 추가, 삭제가 비활성이다.","출력 노드가 둘 이상이면 배포를 막는다.","에이전트 노드(에이전트, Built-in, 외부 에이전트를 모두 셈)가 하나도 없으면 배포를 막는다(D-07).","시작에서 출력까지 경로가 끊기면 배포를 막는다."],"엣지":["외부에서 불러온 정의도 같은 검증을 거친다. 출력 노드 둘은 불러오기로만 생길 수 있다."],"미정":[]},{"묶음":"설정 > 입출력 노드","fn":"FN-WFL-009","이름":"시작 노드 음성 입력 설정","동작":"편집자가 시작 노드의 입력 형식(텍스트, JSON)과 음성 입력 사용 여부를 정한다. 음성 입력을 사용하면 음성 인식 모델을 고르고, 실행할 때 들어온 음성을 글로 바꿔 다음 노드로 넘긴다.","규칙":["음성 입력을 사용하면 음성 인식 모델은 필수다.","음성 인식 모델은 배포중인 모델 배포여야 한다. 아니면 배포를 막는다.","시작 노드에 나가는 연결이 없으면 배포를 막는다.","배포중에는 입력 형식을 바꿀 수 없다."],"엣지":[],"미정":[]},{"묶음":"설정 > 입출력 노드","fn":"FN-WFL-010","이름":"출력 노드 출력 형식","동작":"편집자가 출력 노드의 출력 형식(텍스트, JSON)을 정한다. JSON이면 반환할 키와 그 값으로 쓸 변수를 짝지어, 실행 결과를 그 꼴로 돌려준다.","규칙":["JSON이면 키와 값 매핑에 빈 칸이 없어야 배포한다.","배포중에는 출력 형식을 바꿀 수 없다.","출력 노드는 입력·출력 변수 구역이 없다. 받는 값은 들어오는 연결이, 반환 꼴은 출력 형식이 정한다."],"엣지":[],"미정":[]},{"묶음":"설정 > 입출력 노드","fn":"FN-WFL-011","이름":"출력 노드 음성 출력","동작":"편집자가 출력 노드에서 음성 출력 사용 여부를 정한다. 사용하면 음성 합성 모델로 답을 음성으로 만들어 돌려주고, 원문을 함께 돌려줄지 정한다.","규칙":["음성 출력을 사용하면 음성 합성 모델은 필수이고, 배포중인 모델 배포여야 한다.","배포중에는 음성 출력 설정을 바꿀 수 없다."],"엣지":[],"미정":[]},{"묶음":"설정 > 에이전트 노드","fn":"FN-WFL-012","이름":"에이전트 노드 모델 선택","동작":"편집자가 에이전트 노드가 답을 만들 모델 배포와 모델 파라미터(이미지 생성 수, Continue on Length 포함)를 고른다. 실행할 때 그 모델 배포를 호출하고 사용량을 크레딧과 테스트 실행 내역에 넣는다.","규칙":["모델은 필수다. 고르지 않으면 배포를 막는다.","고른 모델 배포가 배포중이 아니면 배포를 막는다.","배포중에는 모델과 파라미터를 바꿀 수 없다."],"엣지":["워크플로우가 배포중인 동안 그 모델 배포는 배포 중지와 삭제가 막힌다."],"미정":[]},{"묶음":"설정 > 에이전트 노드","fn":"FN-WFL-013","이름":"프롬프트 작성","동작":"편집자가 노드의 프롬프트를 쓰고 변수를 넣는다. 배포 전에는 자동 저장으로 끝나고, 배포중에는 [편집 완료] 때 운영 회차에 반영한다.","규칙":["에이전트 노드의 프롬프트는 필수다.","배포중에도 고칠 수 있는 유일한 설정 묶음이다."],"엣지":[],"미정":[]},{"묶음":"설정 > 에이전트 노드","fn":"FN-WFL-014","이름":"입출력 변수 설정","동작":"편집자가 노드가 받을 입력 변수와 다음 노드로 넘길 출력 변수를 정의하고 앞 노드의 출력과 잇는다. 실행할 때 변수 값을 노드 사이에 넘긴다.","규칙":["변수 이름은 필수이고 영문으로 시작하며 영문, 숫자, 밑줄(_)만 쓴다.","같은 노드 안에서 같은 변수 이름은 막는다.","필수 입력 변수가 연결되지 않으면 배포를 막는다.","배포중에는 변수를 추가하거나 바꿀 수 없다."],"엣지":[],"미정":[]},{"묶음":"설정 > 에이전트 노드","fn":"FN-WFL-015","이름":"RAG 연결","동작":"편집자가 에이전트 노드에 RAG를 연결하거나 해제한다. 실행마다 그 RAG의 최신 검색 DB를 검색해 답의 근거로 쓴다. 연결한 RAG의 검색 DB가 새 버전이 되면 다시 배포하지 않고 지금 회차에 바로 반영한다.","규칙":["연결할 수 있는 RAG는 배포중이고 검색 DB가 있는 RAG 전부다. 권한으로 거르지 않는다.","실행할 때는 요청한 사용자의 권한으로 쓸 수 있는 RAG만 검색한다.","검색 DB 버전이 바뀌면 상세 부제와 작업 이력에 연결 자원 변경을 남기고 워크플로우 생성자와 관리자에게 알린다.","배포중에는 연결을 바꿀 수 없다."],"엣지":["연결한 RAG가 삭제되면 노드에 「삭제됨」을 남기고 그 노드는 그 RAG를 검색하지 못한다.","검색 DB 이전 버전으로 되돌리는 롤백은 없다(D-12)."],"미정":["검색 DB 버전이 바뀔 때 누구에게 어느 시점에 알리는지(P-20)."]},{"묶음":"설정 > 에이전트 노드","fn":"FN-WFL-016","이름":"연결 대상 상태 확인","동작":"상세에 들어올 때와 배포할 때 노드가 고른 모델 배포, RAG, 도구의 상태를 확인한다. 삭제되었으면 「삭제됨」으로 표시하고 다시 고르기 전까지 배포를 막는다. 워크플로우가 배포중인 동안 연결 대상이 내려가면 워크플로우는 배포중으로 남고, 그 노드만 응답하지 못한다는 안내를 상세에 띄운다.","규칙":["배포를 막는 연결 대상 상태는 삭제됨, 모델 배포가 배포중이 아님, RAG의 검색 DB나 실행 자원 없음, 도구 컨테이너가 실행중이 아님이다.","Built-in 노드의 모델, 음성 인식 모델, 음성 합성 모델도 같은 검사를 받는다.","걸린 항목은 노드, 사유, 조치를 함께 보인다."],"엣지":["연결 대상이 실패하거나 지워진 뒤 들어온 요청에서 그 노드는 노드 실패로 처리한다."],"미정":["실행 중 노드 하나가 실패할 때 요청 전체를 끝낼지(D-06). 지금 구현은 그 노드 자리에 오류 문장을 넣고 다음 노드로 진행한다."]},{"묶음":"설정 > 에이전트 노드","fn":"FN-WFL-017","이름":"RAG, 도구 권한 표시","동작":"에이전트 노드에 연결한 RAG와 도구마다 서비스 사용자 접근 권한 범위를 표시한다. 권한 값은 권한 설정에서 바꾸고, 노드에서는 보기만 한다.","규칙":["실행할 때는 요청한 사용자의 권한으로 쓸 수 있는 RAG와 도구만 실행한다.","권한 체계에 항목이 없으면 권한 판정 없이 실행한다."],"엣지":[],"미정":["권한을 정하지 않은 새 워크플로우, RAG, 도구의 서비스 사용자 접근 기본값을 허용과 차단 중 무엇으로 둘지(D-14). 지금 구현은 만들 때 전체 허용을 저장한다."]},{"묶음":"설정 > 에이전트 노드","fn":"FN-WFL-018","이름":"도구 연결","동작":"편집자가 에이전트 노드에 도구와 그 도구의 동작을 골라 연결하거나 해제한다. 실행할 때 모델이 필요하다고 판단한 동작을 호출한다.","규칙":["연결할 수 있는 도구는 배포중인 도구 전부다. 권한으로 거르지 않는다.","배포중에는 동작 선택을 바꿀 수 없다.","워크플로우가 배포중인 동안 그 도구의 배포 중지, 삭제, 사용하는 동작의 선택 해제를 막는다."],"엣지":["도구 동작이 사용 안 함으로 바뀌면 바로 그 동작을 부르지 않고 노드에 「{동작} 사용 안 함」을 보인다.","개인 인증이 안 된 도구는 빼고 계속하며 답에 인증 필요 안내를 붙인다."],"미정":[]},{"묶음":"설정 > 에이전트 노드","fn":"FN-WFL-019","이름":"외부 에이전트 노드 설정","동작":"편집자가 외부 에이전트 노드에서 호출 위치(외부 주소, AGENTBASE 워크플로우)와 인증, 입력·출력 변수, 프롬프트를 정한다. 실행할 때 그 대상을 불러 결과를 다음 노드로 넘긴다.","규칙":["호출 대상은 필수다. 고르지 않으면 배포를 막는다.","외부 주소는 인증 방식(인증 없음, API Key, Bearer Token)마다 받는 칸이 다르다.","AGENTBASE 워크플로우는 배포중인 워크플로우만 고른다. 부르는 워크플로우가 배포중이 아니면 배포를 막는다.","배포중에는 프롬프트만 고친다."],"엣지":["배포중인 워크플로우가 부르고 있는 워크플로우는 배포 중지와 삭제를 막는다.","AGENTBASE 워크플로우를 부르는 노드는 외부 호출로 보지 않아 보호 노드 경고 대상이 아니다.","부르던 워크플로우가 삭제되면 노드에 「삭제됨」을 남기고 배포를 막는다."],"미정":[]},{"묶음":"설정 > 에이전트 노드","fn":"FN-WFL-020","이름":"마스킹·가드레일 설정","동작":"마스킹 노드는 탐지 대상 하나와 탐지 시 조치를 받아, 실행 중 들어온 글에서 대상을 찾으면 알림, 마스킹, 차단 중 하나를 한다. 가드레일 노드는 탐지 대상 없이 점검 기준으로 답의 유해 내용과 규정 위반을 검사해 수정, 알림, 차단 중 하나를 한다. 두 노드의 판정 모델 사용량도 크레딧과 테스트 실행 내역에 넣는다.","규칙":["마스킹의 탐지 대상은 이름, 주민등록번호, 연락처, 주소, 급여 정보, 업무 기록, 금지 주제, 프롬프트 인젝션, 사용자 정의다.","마스킹 조치의 처음 값은 탐지 대상이 정한다. 금지 주제와 프롬프트 인젝션은 차단, 사용자 정의는 알림, 나머지는 마스킹이다.","마스킹의 알림은 탐지 사실을 남기고 원문을 넘긴다. 마스킹은 탐지 구간을 바꿔 넘기고 요청을 끝내지 않는다. 차단은 넘기지 않고 실행을 끝낸다.","탐지 대상이 사용자 정의이면 추가 기준이 필수다.","가드레일은 점검 기준이 필수이고 조치의 처음 값은 차단이다. 수정은 고친 답을, 알림은 원답을 넘기고, 차단은 실행을 끝낸다.","배포중에는 마스킹은 추가 기준만, 가드레일은 점검 기준만 고친다."],"엣지":["판정 답이 최대 토큰에 닿아 끊기고 이어 쓰기가 꺼져 있으면 탐지 실패로 본다. 조치가 알림이면 원문을 넘기고, 그 밖의 조치는 실행을 끝낸다.","탐지 대상을 고른 옛 가드레일 노드는 마스킹 노드로 읽는다."],"미정":["마스킹이 민감 정보를 찾았을 때 요청을 계속하는지(C-11). 지금 구현은 그 자리에서 끝낸다.","차단 뒤 안내 응답 노드로 잇는 차단 경로를 둘지(C-12). 정해지기 전에는 그 자리에서 끝낸다."]},{"묶음":"설정 > 에이전트 노드","fn":"FN-WFL-021","이름":"코드 에이전트 설정","동작":"편집자가 코드 에이전트 노드의 모델과 추가 지시를 정한다. 실행할 때 입력받은 표 형식 파일을 Python 코드로 분석하고 그래프를 만들어 다음 노드로 넘긴다.","규칙":["모델은 필수이고 추가 지시는 선택이다.","언어는 Python 하나다.","코드 에이전트는 외부 호출 보호 노드로 세지 않는다.","배포중에는 추가 지시만 고친다."],"엣지":[],"미정":[]},{"묶음":"설정 > 제어 노드","fn":"FN-WFL-022","이름":"규칙 노드 설정","동작":"편집자가 규칙 노드에 조건을 추가해 조건별 실행 경로와 그 외 경로를 나누고, 분기마다 다음 노드로 넘길 출력을 정한다. 노드를 반복해 지나는 최대 횟수를 정하고, 넘으면 실행을 끝낸다.","규칙":["조건은 1개 이상이어야 하고, 조건 행의 변수와 각 조건 분기, 그 외 분기가 연결되어야 배포한다.","배포중에는 조건과 분기 출력을 바꿀 수 없다.","최대 통과 횟수를 비워 두면 무제한이다."],"엣지":[],"미정":["순환 안의 노드에서 최대 통과 횟수를 비워 두는 것을 허용할지, 기본값을 둘지(N-08).","규칙 노드도 한도를 넘으면 실행을 끝내는지 구현 확인(C-13).","배포중 규칙 조건 수정을 작업 이력에서 「반영 대기」로 남기는 예시를 걷을지(C-15)."]},{"묶음":"설정 > 제어 노드","fn":"FN-WFL-023","이름":"사용자 검토 노드 설정","동작":"실행이 사용자 검토 노드에 닿으면 멈추고 검토자에게 안내 메시지와 분기를 보인다. 검토자가 고른 분기로 이어 가고, 직접 입력 분기는 검토자가 쓴 글을 그대로 넘긴다. 서비스 API로 부른 요청은 검토자가 서비스 사용자이고, 응답으로 검토 대기 상태와 선택지를 돌려준 뒤 재개 호출로 이어 간다(D-08).","규칙":["기본 분기는 승인, 거부, 직접 입력이다. 셋 다 지울 수 없고 이름은 바꾼다.","안내 메시지와 승인, 거부 분기 연결이 있어야 배포한다.","최대 통과 횟수를 넘으면 실행을 끝낸다.","배포중에는 메시지와 분기 출력을 바꿀 수 없다."],"엣지":["검토를 기다린 시간은 응답 시간에 넣지 않는다."],"미정":["서비스 API 호출이 검토 대기로 멈춘 뒤 재개 호출을 얼마나 기다리고, 넘기면 어떻게 끝낼지."]},{"묶음":"설정 > 배포","fn":"FN-WFL-024","이름":"배포 전 검증","동작":"[배포]를 누르면 노드 설정과 연결을 검증한다. 막는 항목이 하나라도 있으면 배포하지 않고 노드, 사유, 조치를 보인다. 외부로 나가는 호출 앞에 마스킹이나 가드레일이 없으면 경고만 하고 배포는 허용한다.","규칙":["막는 항목은 한 번도 저장하지 않음, 노드 설정 누락, 시작에서 출력까지 경로 단절, 부르는 워크플로우가 배포중이 아님, 출력 노드 둘 이상, 에이전트 노드 없음, 연결 대상 삭제됨, 연결 대상이 준비되지 않음이다.","외부로 나가는 호출은 외부 주소를 부르는 외부 에이전트 노드와, 외부 엔드포인트·상용 API 모델 배포를 쓰는 에이전트 노드다.","그 노드에 닿는 경로 중 하나라도 마스킹이나 가드레일이 있으면 경고하지 않는다.","편집 모드에서는 [배포]를 두지 않는다. [편집 완료] 뒤 검증한다.","보안 평가를 실행하는 동안에는 검증을 통과해도 [배포]를 막는다."],"엣지":["검증 실패는 작업 이력에 남기지 않는다. 배포가 시작되지 않았기 때문이다.","외부 에이전트 노드의 호출 대상을 아직 고르지 않았으면 경고가 아니라 설정 누락으로 막는다.","오케스트레이터가 워크플로우를 구성하는 동안(마지막 조작 뒤 2분까지)은 검증 경고를 띄우지 않고 구성 중이라고 보인다."],"미정":[]},{"묶음":"설정 > 배포","fn":"FN-WFL-025","이름":"워크플로우 배포","동작":"검증을 통과하면 저장된 정의로 배포를 시작한다. 상태는 설치중이 되고, 설치가 끝나면 배포중이 되며 그 순간 새 배포 회차가 생긴다. 설치에 실패하면 실패이고 회차는 생기지 않는다.","규칙":["권한이 필요 없고 실행 자원을 점유하지 않는다. 실행 시점(예약) 선택도 없다.","배포할 수 있는 상태는 생성됨, 중지, 실패다.","회차 정보에는 상태, 배포 기간, 실행자, 중지한 구성원, 배포 전 검증 결과, 연결한 RAG와 도구의 회차, 서비스 API 오픈 상태를 남긴다."],"엣지":["실패한 워크플로우는 생성됨과 같이 모든 설정을 고친다.","새 회차는 서비스 API 오픈을 새로 해야 서비스에서 부를 수 있다."],"미정":[]},{"묶음":"설정 > 배포","fn":"FN-WFL-026","이름":"배포 중 프롬프트 수정","동작":"배포중인 워크플로우에서 편집자가 프롬프트 계열만 고치고 [편집 완료]를 누르면 다시 배포하지 않고 지금 회차에 반영한다. 반영 뒤 시작한 요청부터 새 프롬프트를 쓰고, 이미 진행 중인 요청은 시작할 때의 프롬프트로 끝까지 처리한다(D-04). 회차는 바뀌지 않는다.","규칙":["고칠 수 있는 칸은 에이전트 노드와 외부 에이전트 노드의 프롬프트, 마스킹의 추가 기준, 가드레일의 점검 기준, 코드 에이전트의 추가 지시다.","자동 저장만으로는 반영하지 않는다. [편집 완료]를 눌러야 반영한다.","반영할 때 바뀐 노드마다 작업 이력 현재 회차에 프롬프트 변경 한 줄을 남긴다.","다시 배포하지 않으므로 서비스 API 오픈은 그대로 유지된다(D-02).","보안 평가를 실행하는 동안에는 프롬프트도 고칠 수 없다."],"엣지":["고쳤다가 처음 값으로 되돌린 노드는 이력을 남기지 않는다.","반영하는 순간 배포가 점검 중이면 저장만 하고 반영을 건너뛴다.","오래전에 띄운 배포가 반영을 거절하면 「배포를 중지했다가 다시 배포하세요」를 보인다. 다시 배포하면 새 회차다."],"미정":["응답 캐시를 쓰는 워크플로우에서 프롬프트를 반영할 때 저장된 응답을 모두 지울지."]},{"묶음":"설정 > 배포","fn":"FN-WFL-027","이름":"배포 중지","동작":"구성원이 [배포 중지]를 누르고 확인하면 상태가 배포 중지 중이 되고, 진행 중인 대화가 끝나기를 기다린 뒤 주소를 회수해 중지가 된다. 지금 배포 회차는 이때 끝난다.","규칙":["권한이 필요 없다. 모든 구성원이 확인 창을 거쳐 바로 실행한다. 배포 중지 요청은 없다.","서비스 API가 오픈된 동안 그 워크플로우가 오픈됨이거나 해제 승인 대기면 막는다.","워크플로우 오픈 요청이 승인을 기다리면 막는다.","배포중인 다른 워크플로우가 외부 에이전트 노드로 부르고 있으면 막는다.","보안 평가를 실행하는 동안 막는다.","막는 이유가 여럿이면 서비스 API 오픈, 오픈 요청 대기, 다른 워크플로우 호출, 보안 평가 진행 차례로 하나만 보인다."],"엣지":["서비스 API 오픈이 중지된 상태면 오픈해 둔 워크플로우도 중지할 수 있다. 확인 창이 오픈 해제를 경고하고, 중지하면 워크플로우 오픈도 해제하며 서비스 API 오픈 작업 이력에 「오픈 해제(배포 중지)」를 남긴다.","중지한 워크플로우를 다시 배포하면 새 회차라 오픈을 새로 요청해야 한다.","배포 상태가 바뀌면 되돌리기 기록을 비운다."],"미정":[]},{"묶음":"테스트","fn":"FN-WFL-028","이름":"채팅 테스트","동작":"편집자가 배포중인 워크플로우의 지금 회차에 질문을 보내 답을 받는다. 새 대화를 시작하거나 지난 대화를 이어서 본다. 질문 한 건의 크레딧을 크레딧 관리 비율로 계산해 보이지만 서비스 사용자의 사용량과 한도에는 넣지 않는다.","규칙":["배포중일 때만 질문한다.","다른 구성원이 편집 중이면 질문을 보낼 수 없다.","질문 한 건이 작업 이력 테스트 한 줄이다.","테스트 호출은 모니터링에서 AGENTBASE 호출의 「워크플로우 테스트」로 센다."],"엣지":["배포하지 않은 동안의 테스트 이력은 마지막 회차(없으면 0회차)에 속한다."],"미정":[]},{"묶음":"테스트","fn":"FN-WFL-029","이름":"에이전트 실행 내역 조회","동작":"답마다 그 답을 만든 노드별 실행 내역(입력, 출력, 걸린 시간, 모델 사용량, 검색한 RAG와 호출한 도구)을 보여 준다.","규칙":["Built-in 노드의 판정 모델 사용량도 실행 내역에 넣는다.","권한이나 인증 때문에 뺀 RAG와 도구는 빠진 이유와 함께 보인다."],"엣지":[],"미정":[]},{"묶음":"테스트","fn":"FN-WFL-030","이름":"테스트 질문 내역 조회","동작":"지금까지 보낸 테스트 질문과 답을 대화 단위로 보여 주고, 골라서 다시 연다.","규칙":["테스트 대화 이력은 워크플로우 다운로드 패키지에 넣지 않는다."],"엣지":[],"미정":[]},{"묶음":"테스트","fn":"FN-WFL-031","이름":"회차별 응답 비교","동작":"같은 질문에 대해 회차마다 받은 답을 나란히 비교한다.","규칙":["비교 대상은 같은 워크플로우의 배포 회차다."],"엣지":["배포 중 프롬프트를 바꾼 회차는 같은 회차 안에서도 답이 다를 수 있어, 질문한 일시를 함께 보인다."],"미정":[]},{"묶음":"테스트","fn":"FN-WFL-032","이름":"테스트 권한 지정","동작":"테스트할 때 권한을 지정하면 그 권한으로 판정해 접근 권한이 없는 RAG와 도구는 빼고 실행하고, 판정 결과를 함께 보여 준다.","규칙":["권한 체계에 항목이 없으면 권한 판정 없이 실행한다.","판정은 실제 서비스 호출과 같은 규칙을 쓴다."],"엣지":[],"미정":[]},{"묶음":"테스트","fn":"FN-WFL-033","이름":"테스트 도구 연동","동작":"개인 인증 도구를 연결한 경우 테스트하는 구성원의 인증 토큰을 테스트에 연동한다. 연동하지 않은 도구는 빼고 계속하며 답에 인증 필요 안내를 붙인다.","규칙":["연동한 토큰은 테스트에만 쓰고 다운로드 패키지에 넣지 않는다."],"엣지":[],"미정":[]},{"묶음":"보안 평가","fn":"FN-WFL-034","이름":"보안 평가 설정","동작":"편집자가 평가 모드를 고르고 모드에 맞는 값을 정한다. 신규 평가는 공격 모델, 목표, 전략, 횟수 설정, 판정 모델을, 평가셋 선택과 평가셋 업로드는 평가셋(또는 파일)과 판정 모델을 받는다. 설정은 워크플로우마다 저장하고, 기본값으로 되돌리거나 저장한 결과의 설정을 불러온다.","규칙":["평가 모드는 신규 평가, 평가셋 선택, 평가셋 업로드 셋이다.","횟수 설정은 시도 1~5회(처음 1), 대화 턴 1~10턴(처음 5), 강화 0~3단계(처음 1)다. 신규 평가에만 있다.","예상 요청 수를 계산해 보인다.","판정 모델은 하나 이상 고른다. 둘 이상이면 모든 모델이 공격 성공으로 판정한 경우에만 공격 성공으로 남긴다.","공격 모델과 판정 모델이 같은 모델 배포이면 경고만 하고 막지 않는다.","실행하는 동안에는 설정을 바꿀 수 없다."],"엣지":[],"미정":[]},{"묶음":"보안 평가","fn":"FN-WFL-035","이름":"공격 라이브러리 관리","동작":"Built-in과 사용자 작성 목표, 전략을 카테고리와 묶음별로 보여 준다. 사용자가 목표와 전략을 추가, 수정, 삭제하고, AGENTBASE 전체 공용 등록을 요청하면 관리자가 승인한 뒤 공용이 된다.","규칙":["목표는 카테고리에 속하고 성공 기준을 가진다. 카테고리마다 심각도가 정해져 있다.","Built-in 목표와 전략은 고치거나 지울 수 없다.","전략을 고를 때 전략마다 성공한 공격 대화를 보여 준다."],"엣지":["목표에 성공 기준이 없으면 목표 문장과 서비스 목적으로 판정한다."],"미정":[]},{"묶음":"보안 평가","fn":"FN-WFL-036","이름":"보안 평가 실행","동작":"편집자가 [실행]하면 배포중인 워크플로우에 공격 대화를 보낸다. 신규 평가는 목표마다 시도 횟수만큼 전략을 골라 대화하고 실패하면 강화 단계 수만큼 다시 시도한다. 평가셋 모드는 공격 대화를 그대로 다시 보낸다. 판정 모델이 대화가 끝난 뒤 대화 전체를 보고 공격 성공 여부를 한 번 판정한다.","규칙":["[실행]은 배포중, 편집 모드 아님, 워크스페이스에서 다른 보안 평가가 실행 중이 아님, 모드별 입력 채움, 판정 모델 1개 이상, 예상 요청 수 20,000회 이하를 모두 만족해야 열린다. 먼저 걸린 이유 하나를 보인다.","배포중이 아니면 「워크플로우가 배포중일 때만 평가할 수 있습니다.」로 막는다.","다른 구성원이 편집 중이면 [실행]은 비활성이다.","실행하는 동안 편집, 배포, 배포 중지, 삭제, 롤백, 평가 설정 변경을 막는다.","평가 호출은 모니터링에서 AGENTBASE 호출의 「보안 평가」로 세고 서비스 사용자 사용량에는 넣지 않는다.","평가 실행은 작업 이력에 한 줄을 남긴다."],"엣지":["업로드 평가셋은 공격 대화 2,000개까지, 이름은 50자까지다.","평가가 끝나면 실행자와 관리자에게 작업 종료 알림을 보낸다."],"미정":[]},{"묶음":"보안 평가","fn":"FN-WFL-037","이름":"보안 평가 중지","동작":"편집자가 진행 중인 평가를 중지하면 그 시점까지의 대화와 판정을 저장하지 않은 결과로 남기고 워크플로우 잠금을 푼다.","규칙":["평가 중지는 작업 이력에 한 줄을 남긴다.","중지한 결과는 저장하기 전까지 방어율 참고값에 들어가지 않는다."],"엣지":["저장하지 않은 결과는 하나뿐이라 다음 실행 결과로 대체된다."],"미정":[]},{"묶음":"보안 평가","fn":"FN-WFL-038","이름":"보안 평가 결과 관리","동작":"실행이 끝난 결과에 이름과 설명을 넣어 저장하면 공격에 성공한 대화로 평가셋 버전을 만든다. 저장한 결과는 조회, 수정, 삭제한다.","규칙":["같은 이름이면 다음 버전(vN)으로 만든다. 결과와 업로드를 가리지 않고 생성 차례로 매긴다.","공격 성공이 없으면 결과만 저장하고 평가셋은 만들지 않는다.","저장하지 않은 결과는 다음 실행 결과로 대체된다.","실행 중인 결과는 수정, 삭제할 수 없다.","결과 저장(평가셋 생성), 결과 수정, 결과 삭제는 작업 이력에 각각 한 줄을 남긴다.","보안 평가는 서비스 API 오픈의 조건이 아니다. 오픈 창과 승인 창에는 지금 회차에서 끝나고 저장한 결과의 방어율을 참고값으로 보인다."],"엣지":["저장한 결과의 이름을 바꾸면 그 결과로 만든 평가셋 이름도 함께 바뀐다.","편집자가 표시 결과로 고른 결과가 지금 회차에서 끝나고 저장한 결과이면 그 방어율을 참고값으로 보인다."],"미정":["오픈한 워크플로우의 마지막 근거 결과를 삭제하는 것을 막을지(N-09)."]},{"묶음":"보안 평가","fn":"FN-WFL-039","이름":"보안 평가 결과 조회","동작":"결과를 방어율, 심각도별, 카테고리별, 전략별로 보여 주고, 목표별 시도 대화와 판정을 연다. 같은 조건으로 측정한 다른 결과와 방어율 차이를 비교한다.","규칙":["방어율은 공격에 실패한 목표 수를 전체 목표 수로 나눈 값이다. 목표는 N번 중 한 번이라도 성공하면 공격 성공이다.","공격 성공에는 심각도와 공격 성공 턴 번호를, 공격 실패에는 근접도(1~10)를 남긴다. 근접도 7 이상은 공격에 실패했어도 점검 대상이다.","평가셋 모드의 결과는 다시 성공과 막음으로 나눈다.","비교는 같은 모드, 같은 목표 또는 같은 평가셋, 같은 판정 모델로 측정한 결과끼리만 한다."],"엣지":["평가셋 모드에서 공격 실패한 항목은 그 목표로 신규 평가 설정을 채워 다시 실행할 수 있다."],"미정":["평가 도중 모델 배포 장애로 오류 문장이 답이 된 대화를 「판정 불가」로 따로 세어 방어율에서 뺄지."]},{"묶음":"보안 평가","fn":"FN-WFL-040","이름":"평가셋 관리","동작":"결과로 만든 평가셋과 업로드한 평가셋 파일을 등록해 관리한다. 평가셋의 공격 대화를 보고, 다운로드하거나 삭제한다. 평가셋은 데이터 관리의 그 워크플로우 evaluations 폴더에 「이름_v버전.jsonl」로 저장한다.","규칙":["업로드 파일에는 목표, 카테고리, 공격 턴 열이 있어야 한다.","평가셋 업로드는 작업 이력에 한 줄을 남긴다.","다운로드는 다운로드 권한을 거친다. 권한이 없으면 다운로드 요청을 보내고, 승인되면 요청자가 1회 받는다.","다른 워크플로우의 평가셋도 골라 실행할 수 있으나 삭제할 수 없다."],"엣지":[],"미정":[]},{"묶음":"모니터링","fn":"FN-WFL-041","이름":"워크플로우 지표 조회","동작":"워크플로우의 호출을 출처별(서비스 호출, AGENTBASE 호출)로 나누어 요청 수, 에러, 응답 시간, 토큰 사용량을 기간별로 보여 준다. 요청은 끝난 뒤에 세고, 화면을 다시 열거나 기간을 바꿀 때 최신 값을 읽는다.","규칙":["서비스 호출은 서비스 API로 들어온 요청이다. AGENTBASE 호출은 워크플로우 테스트와 보안 평가다.","AGENTBASE 호출은 서비스 사용자 사용량에 넣지 않는다.","배포 전에는 호출이 없어 빈 상태다."],"엣지":["배포가 멈췄거나 응답하지 않은 서비스 호출은 에러로 센다.","삭제된 서비스 사용자의 요청은 차단으로 세어 에러율에 넣지 않는다."],"미정":["호출을 모으는 주기(모델 배포 모니터링과 같은 1분 단위로 맞출지)."]},{"묶음":"모니터링","fn":"FN-WFL-042","이름":"노드별 처리 조회","동작":"노드마다 처리 횟수, 걸린 시간, 실패 수를 보여 주어 어느 노드가 느리거나 자주 실패하는지 확인한다.","규칙":["마스킹, 가드레일 차단과 검토 노드 한도 초과로 끝난 요청도 그 노드의 처리로 센다."],"엣지":[],"미정":[]},{"묶음":"모니터링","fn":"FN-WFL-043","이름":"노드 자원 모니터링 연결","동작":"노드가 쓰는 모델 배포, RAG, 도구의 모니터링으로 바로 이어 보게 한다. 연결 대상의 상태와 지표는 각 작업의 모니터링이 정본이다.","규칙":["삭제된 연결 대상은 이동하지 않고 「삭제됨」으로 보인다."],"엣지":[],"미정":[]},{"묶음":"모니터링","fn":"FN-WFL-044","이름":"호출 이력 조회","동작":"호출 한 건마다 출처, 결과, 응답 시간을 보여 주고, 열면 그 호출의 노드별 실행 흐름을 보여 준다.","규칙":["응답 캐시로 돌려준 호출은 결과가 「캐시 응답」이다.","보안 평가 호출은 결과가 공격 실패 또는 공격 성공이다.","출처(서비스 호출, AGENTBASE 호출)로 거른다."],"엣지":["호출 이력은 워크플로우 다운로드 패키지에 넣지 않는다."],"미정":[]},{"묶음":"모니터링","fn":"FN-WFL-045","이름":"만족도 조회","동작":"서비스가 보낸 좋아요, 싫어요를 실행 식별자로 원래 요청에 붙여 만족도를 보여 준다. 만족도는 좋아요의 비율이고, 싫어요 사유를 모아 본다.","규칙":["없는 실행 식별자로 보낸 평가는 만족도에 넣지 않는다.","권한으로 걸러 봐도 만족도는 거르지 않는다."],"엣지":[],"미정":[]},{"묶음":"작업 이력","fn":"FN-WFL-046","이름":"작업 이력 조회","동작":"배포 회차별로 사람이 한 일을 한 줄씩 보여 준다. 배포 시작과 중지, 롤백, 설계 변경, 테스트, 보안 평가, 서비스 API 오픈, 다운로드를 변경 전후, 반영 상태, 승인자, 실행 일시, 실행자와 함께 남긴다. 연결 대상의 새 버전처럼 시스템이 바꾼 일은 실행자가 「-」인 시스템 줄로 남긴다. 프롬프트 변경 줄에서 그 값으로 되돌리면 지금 회차에 바로 반영하고 새 줄을 남긴다(D-03).","규칙":["회차 표기는 n회차이고 0회차는 생성이다.","배포 중의 설계 변경은 프롬프트 변경만 생긴다.","목록은 최근 회차만 보인다(처음 10회차, 관리자가 3~50회차 사이에서 바꿈). 더 오래된 회차는 리포트에서 본다.","이력 표시 기간은 보이는 기간일 뿐이고 기록은 지우지 않는다.","화면 이동, 조회, 저장하지 않은 편집, 편집 점유, 확대와 이동은 남기지 않는다.","오케스트레이터를 거쳐 한 일은 줄에 「오케스트레이터」 경유를 표시한다(D-52)."],"엣지":["실행의 완료와 실패는 줄이 아니라 회차 정보의 상태와 종료 일시로 보인다.","프롬프트 되돌리기도 배포중이 아니면 할 수 없고, 다른 구성원이 편집 중이면 막는다."],"미정":[]},{"묶음":"작업 이력","fn":"FN-WFL-047","이름":"배포 롤백","동작":"구성원이 작업 이력 회차 상세에서 [이 회차로 롤백]을 누르면 그 회차의 정의(노드, 연결선, 프롬프트, 모델·RAG·도구 연결, 변수, 규칙 조건)로 새 회차를 배포한다. 배포중이면 지금 회차를 먼저 중지한다. 마지막 배포 뒤 저장한 편집은 사라진다.","규칙":["권한이 필요 없다.","돌아가는 프롬프트는 그 회차가 끝난 시점의 마지막 프롬프트다(D-05).","지금 회차의 줄에는 롤백 버튼을 두지 않는다.","다른 구성원 편집 중, 설치중·배포 중지 중, 서비스 API에 오픈된 회차가 배포중, 오픈 요청 대기, 다른 워크플로우 호출 중, 보안 평가 중이면 막는다.","그 회차의 모델 배포가 삭제되었거나 배포중이 아니면 확인 창에서 막는다.","작업 이력에 롤백 한 줄과 바뀐 항목마다 설정 변경 줄을 남긴다."],"엣지":["그 회차의 RAG나 도구가 삭제되었으면 빼고 롤백하고, 그 노드는 호출하지 못한다고 확인 창에 보인다.","그 회차가 쓴 검색 DB 버전이나 커밋이 지워졌으면 현재 버전을 부른다고 보인다.","새 회차 배포가 실패하면 이전 회차로 자동으로 돌아가지 않고 실패로 남으며 실행자에게 알린다.","롤백으로 새 회차가 되면 서비스 API 오픈을 새로 해야 한다."],"미정":[]},{"묶음":"정보","fn":"FN-WFL-048","이름":"워크플로우 정보 조회","동작":"워크플로우의 이름, 설명, 상태, 생성자와 일시, 노드 구성 요약, 지금 배포 회차와 배포 일시, 응답 캐시 사용 여부, 서비스 API 오픈 상태를 보여 준다.","규칙":["뷰어도 조회한다."],"엣지":[],"미정":[]},{"묶음":"정보","fn":"FN-WFL-049","이름":"워크플로우 수정, 복제, 삭제","동작":"편집자가 이름, 설명, 응답 캐시 사용 여부를 고치면 바로 저장한다. [복제]하면 노드, 연결, 프롬프트, 모델·RAG·도구 연결을 복사해 생성됨 상태의 새 워크플로우를 만든다. [삭제]하면 워크플로우와 그 산출물을 지운다.","규칙":["이름과 설명은 배포 중에도 고치고 권한이 필요 없다.","응답 캐시는 서비스 API 오픈의 응답 캐시가 사용일 때만 적용한다.","복제 이름의 처음 값은 「{원본}_복제」이고 겹치면 _복제2, _복제3이다. 복제한 구성원이 생성자다.","복제본은 배포 회차 기록, 프롬프트 변경 기록, 서비스 API 오픈 설정과 요청, 테스트·보안 평가 결과를 가져오지 않는다.","설치중, 배포중, 배포 중지 중, 보안 평가 중, 서비스 API에 오픈됨, 다른 워크플로우가 부르는 중, 이 워크플로우를 대상으로 한 승인 대기 요청이 있음이면 삭제를 막는다. 삭제는 [배포 중지] 뒤에 한다.","다른 구성원이 편집 중이면 수정과 삭제를 막는다."],"엣지":["삭제한 워크플로우를 부르던 배포 전 워크플로우는 참조를 지우지 않고 「삭제됨」으로 남기며 배포를 막는다.","오케스트레이터는 삭제를 대신하지 않고 삭제할 자리를 안내한다."],"미정":[]},{"묶음":"정보","fn":"FN-WFL-050","이름":"워크플로우 다운로드","동작":"구성원이 배포 회차 하나를 골라 그 회차를 다른 환경에서 다시 구성할 수 있는 압축 패키지로 받는다. 패키지에는 그 회차의 정의, 연결 자원(모델, RAG, 도구), 실행 구성, 모델 체크포인트, 이 워크플로우의 보안 평가셋 전부를 넣는다.","규칙":["고르는 값은 배포 회차 하나뿐이다. 처음 값은 가장 최근 회차이고, 회차 상세에서 열면 그 회차다.","모델 체크포인트는 그 회차에 배포된 커밋이고, 배포중인 회차는 현재 커밋이다.","보안 평가셋은 회차와 관계없이 전부 넣는다.","비밀값, 계정과 권한, 호출 이력과 모니터링, 테스트 대화, 컨테이너 이미지 파일, 노드 풀과 GPU 할당은 넣지 않는다.","다운로드 권한이 있으면 바로 받고, 없으면 [다음]으로 요청한다. 승인은 요청한 회차에 묶이고 1회 다운로드 또는 7일 경과 가운데 먼저 오는 때 끝난다.","다운로드는 감사 이력과 작업 이력에 한 건씩 남긴다."],"엣지":["배포 회차가 없으면 [다운로드]는 비활성이고 배포한 뒤 받으라고 안내한다.","같은 워크플로우에 다른 회차로 보낸 요청이 승인을 기다리면 새 요청을 막는다. 승인 뒤 회차를 바꾸면 다시 요청이다.","커밋이나 검색 DB가 지워졌으면 넣지 못한 파일을 패키지 안내 파일에 적고 다운로드는 막지 않는다.","보안 평가셋이 없으면 evaluations 폴더를 만들지 않는다.","관리자가 승인을 검토하는 순간 대상 회차와 요청자 권한을 다시 확인해 실행할 수 없으면 [승인]을 비활성으로 두고 이유를 보인다(D-26)."],"미정":[]}]},{"모듈":"오케스트레이터","코드":"ORC","개요":"사용자가 글로 요청한 작업을 AGENTBASE가 대신 실행한다. 요청을 해석해 설계를 제안하고, 사용자가 확인하면 입력자의 권한으로 작업을 차례로 실행하며, 실행하는 동안 AGENTBASE는 보기 전용이다.","상태":["대기(입력 가능) → [전송] → 해석 중(생각 과정 표시) → 확인 대기(설계 제시)","확인 대기 → [Yes] → 실행중(보기 전용)","확인 대기 → [No] → 수정 내용 입력 → 확인 대기(고친 설계)","실행중 → 모든 작업 끝 → 완료 → 대기","실행중 → 작업 일부 실패 → 실패 → 대기","실행중 → [중지] → 중지(끝난 작업 유지, 시작한 배포 취소) → 대기","실행중 → 새로고침 → 중지 → 대기"],"공통":["오케스트레이터 연결은 GPUBASE에서 AGENTBASE를 만들 때 정하고 AGENTBASE 화면에서는 바꾸지 않는다. 연결되지 않으면 대화 패널과 여는 버튼을 두지 않고, 홈에도 입력창이 없다. 다른 기능은 그대로 쓴다.","오케스트레이터는 대화하는 구성원(입력자)의 권한으로 움직인다. 관리자는 모든 권한이 있다.","권한은 실행 계획을 보일 때와 확인(Yes) 뒤 실행하는 순간에 두 번 보고, 둘이 다르면 실행하는 순간을 따른다.","권한이 필요 없는 일(워크플로우 생성·수정·배포, 모델 배포 생성, RAG 생성과 문서 연결, 도구 등록, 데이터 파이프라인 생성과 모듈 삽입)은 끝까지 실행한다.","컴퓨팅 자원 사용 권한이 필요한 일(모델 배포의 배포, RAG 배포와 검색 DB 생성)은 권한이 있으면 실행하고, 없으면 배포 요청을 보내고 멈춘다. 요청 메모에는 오케스트레이터에 요청한 내용이 담기고, 입력자가 메모를 더 적을 수 있다(D-50).","삭제, 다운로드, 서비스 API 오픈, 리더보드 등록은 대신하지 않고, 하는 자리와 입력자 권한에 따른 결과(바로 실행 또는 요청)를 답한다.","고칠 수 있는 기존 작업은 워크플로우 수정과 데이터 파이프라인 모듈 삽입뿐이다(D-51). 새로 만들 수 있는 것은 워크플로우, RAG, 데이터 파이프라인, 모델 배포, 도구다.","다른 구성원이 편집 중인 작업은 수정, 노드 추가, 배포, 모듈 삽입하지 않고 「{이름}님이 편집 중이라 수정할 수 없습니다. 편집이 끝난 뒤 다시 요청합니다.」로 답한다. 조회와 실패 원인 답변 같은 읽기는 편집 점유를 보지 않는다.","오케스트레이터가 새로 만든 작업은 입력자가 생성자이자 편집자다.","오케스트레이션이 실행되는 동안 AGENTBASE 전체가 보기 전용이다. 조회와 화면 이동만 허용하고, 다른 구성원의 화면도 보기 전용이다.","오케스트레이터를 거쳐 한 일은 각 작업의 작업 이력 줄에 실행자는 입력자로, 「오케스트레이터」 경유를 함께 표시한다(D-52).","작업이 끝나면 요청자 본인에게만 작업 종료 알림을 보낸다. 그 화면에 있으면 토스트만 띄운다."],"기능":[{"묶음":"요청 입력","fn":"FN-ORC-001","이름":"오케스트레이터 요청","동작":"사용자가 어느 화면에서든 오케스트레이터 대화를 열어 요청을 보내고, 닫아 대화를 끝낸다. 대화를 닫아도 진행 중인 실행은 계속되고, 끝나면 작업 알림으로 알린다.","규칙":["오케스트레이터가 연결되지 않으면 패널과 여는 버튼을 두지 않는다. 홈의 「대화로 만들기」는 비활성이고 연결은 GPUBASE에서 관리하니 관리자에게 요청하라고 안내한다.","실행 중에는 새 요청을 보낼 수 없다."],"엣지":["열어 둔 채 연결이 끊기면 패널을 걷는다. 지난 세션의 기록은 그대로 본다."],"미정":[]},{"묶음":"요청 입력","fn":"FN-ORC-002","이름":"세션 초기화","동작":"사용자가 세션을 초기화하면 지금 대화를 대화 기록의 지난 세션으로 넘기고 빈 세션을 연다. 이미 만든 작업과 보낸 요청에는 영향이 없다.","규칙":["실행 중에는 초기화할 수 없다."],"엣지":[],"미정":[]},{"묶음":"요청 입력","fn":"FN-ORC-003","이름":"오케스트레이터 대화 기록","동작":"세션별 대화 기록을 보여 주고 내려받게 한다. 지난 세션은 읽기 전용이다.","규칙":["지난 세션을 보는 동안에는 요청을 보낼 수 없고 현재 세션으로 돌아가라고 안내한다.","다운로드는 다운로드 권한을 거친다. 권한이 없으면 다운로드 요청을 보내고, 승인되면 요청자가 1회 받는다. 승인은 1회 다운로드 또는 7일 경과 가운데 먼저 오는 때 끝난다.","다운로드는 감사 이력에 한 건으로 남긴다."],"엣지":[],"미정":[]},{"묶음":"요청 입력","fn":"FN-ORC-004","이름":"요청 대상 표시","동작":"사용자가 지금 보고 있는 작업(예: 열린 워크플로우, 데이터 파이프라인 설계)을 요청 대상으로 함께 보낸다. 오케스트레이터는 그 대상을 수정이나 제안의 기준으로 쓴다.","규칙":["요청 대상이 다른 구성원의 편집 중인 작업이면 수정하지 않고 편집 점유 문장으로 답한다.","요청 대상이 배포중인 워크플로우이면 계획 단계에서 막는다."],"엣지":[],"미정":[]},{"묶음":"요청 입력","fn":"FN-ORC-005","이름":"홈 대화 이어 보기","동작":"홈에서 시작한 세션을 유지해, 다른 메뉴로 옮겨도 같은 대화를 이어서 진행한다.","규칙":["세션은 구성원마다 따로다."],"엣지":["새로고침해도 대화는 남는다."],"미정":[]},{"묶음":"요청 해석","fn":"FN-ORC-006~007","이름":"생각 과정 표시, 업무 설계 선택","동작":"요청 문장을 해석하는 생각 과정을 답 앞에 보이고, 의도를 생성, 수정, 배포, 배포 중지, 안내(대신하지 않는 일)로 나눈 뒤 맞는 업무 설계를 고른다.","규칙":["대신하지 않는 일(삭제, 다운로드, 서비스 API 오픈, 리더보드 등록)은 설계를 만들지 않고 하는 자리와 입력자 권한에 따른 결과를 답한다.","배포 중지는 입력자가 화면에서 바로 할 수 있는 경우에만 대신 실행한다."],"엣지":[],"미정":["권한이 없는 구성원의 배포 중지를 요청으로 둘지, 비활성으로 둘지(C-27). 사용자 답은 배포 중지 요청이 없어진 것으로 본다."]},{"묶음":"요청 해석","fn":"FN-ORC-008~009","이름":"설계 확인, 설계 수정 요청","동작":"고른 설계를 단계 목록으로 보이고 진행 여부(Yes, No)를 묻는다. 단계마다 필요한 권한과 입력자의 권한 유무를 함께 적는다. No를 고르면 바꿀 내용을 받아 설계에 반영하고 다시 확인받는다. Yes 뒤에만 실행한다.","규칙":["권한이 없으면 마지막 단계가 「배포 요청」으로 바뀌고 확인 질문도 「~을 생성하고 배포 요청을 보낼까요?」가 된다.","모델 배포 설계는 생성 → 배포(또는 배포 요청), RAG 설계는 생성 → 문서 연결 → 배포와 검색 DB 생성(또는 배포 요청), 워크플로우 설계는 생성 또는 수정 → 노드 구성·연결·검증 → 배포 여부 확인 뒤 배포다."],"엣지":["계획을 보인 뒤 권한이 사라지면 그 단계는 실행하는 순간 요청으로 바뀐다."],"미정":[]},{"묶음":"워크플로우 작업","fn":"FN-ORC-010","이름":"작업 목록 실행","동작":"확인한 설계의 작업을 차례로 실행하고 작업마다 진행 상태를 보인다. 각 작업의 결과는 끝나는 순간 목록, 상세, 작업 이력에 반영한다.","규칙":["실행하는 순간 권한과 편집 점유를 다시 확인한다.","작업 일부가 실패하면 그 자리에서 실패로 끝내고 입력창을 [전송]으로 돌린다. 이미 끝난 작업은 되돌리지 않고 사용자가 다시 요청한다(D-49)."],"엣지":[],"미정":[]},{"묶음":"워크플로우 작업","fn":"FN-ORC-011","이름":"노드 구성","동작":"설계에 따라 새 워크플로우에 노드를 추가하고 모델, 프롬프트, RAG·도구 연결을 설정해 잇는다. 구성은 워크플로우 캔버스에 자동 저장한다.","규칙":["구성하는 동안(마지막 조작 뒤 2분까지)은 배포 전 검증 경고를 띄우지 않고 구성 중이라고 보인다.","같은 이름의 워크플로우가 있으면 생성에 실패한 뒤 목록을 보고 새 이름으로 다시 만든다."],"엣지":[],"미정":[]},{"묶음":"워크플로우 작업","fn":"FN-ORC-012","이름":"검증 결과 요약","동작":"구성한 워크플로우를 배포 전 검증과 같은 규칙으로 검증하고, 검증 결과와 노드 구성 요약을 답한다.","규칙":["걸린 항목은 노드, 사유, 조치를 함께 답한다.","외부 호출 앞에 마스킹이나 가드레일이 없으면 경고로 답하고 배포는 막지 않는다."],"엣지":[],"미정":[]},{"묶음":"워크플로우 작업","fn":"FN-ORC-013","이름":"열린 워크플로우 수정","동작":"열려 있는 워크플로우를 수정 대상으로 지정해 노드를 추가하거나 설정을 바꾼다. 편집 점유를 먼저, 배포 상태를 다음으로 확인한다.","규칙":["다른 구성원이 편집 중이면 계획을 보일 때와 실행하는 순간 모두 막고 편집 점유 문장으로 답한다.","배포중(설치중, 배포 중지 중 포함)이면 계획 단계에서 막고 「배포 중인 워크플로우에서는 프롬프트만 수정 가능합니다. 배포를 중지한 뒤 수정합니다.」로 답한다.","배포 실패는 수정한다."],"엣지":[],"미정":[]},{"묶음":"워크플로우 작업","fn":"FN-ORC-014","이름":"배포 확인","동작":"대상 워크플로우를 검증하고, 사용자가 배포를 확인하면 배포한다. 워크플로우 배포는 실행 자원을 잡지 않아 권한과 관계없이 배포한다.","규칙":["실행하는 순간 다른 구성원이 편집 중이면 배포하지 않고 「{워크플로우}은(는) {이름}님이 편집 중이라 배포할 수 없습니다. 편집이 끝난 뒤 다시 요청합니다.」로 답한다.","검증에서 막히면 배포하지 않고 걸린 항목을 답한다."],"엣지":["중지하면 시작한 배포는 취소한다."],"미정":[]},{"묶음":"자원 생성 작업","fn":"FN-ORC-015","이름":"RAG 생성","동작":"요청 주제에 맞는 데이터 관리 문서로 RAG를 만들고 문서를 연결한다. 컴퓨팅 자원 사용 권한이 있으면 실행 자원으로 배포하고 검색 DB를 만들고, 없으면 배포 요청을 보내고 멈춘다.","규칙":["권한이 없을 때 RAG는 생성됨 상태로 남고 「컴퓨팅 자원 사용 권한이 없어 배포 요청을 보냈습니다. 관리자가 승인하면 요청한 실행 자원으로 배포하고 검색 DB를 생성합니다.」로 답한다.","관리자가 승인하면 요청한 실행 자원으로 바로 배포하고 검색 DB를 만든다."],"엣지":["다른 구성원이 편집 중인 문서는 연결에서 빼고 「제외한 문서」에 편집자를 적는다."],"미정":[]},{"묶음":"자원 생성 작업","fn":"FN-ORC-016","이름":"데이터 파이프라인 생성","동작":"요청에 맞는 원본 데이터로 데이터 파이프라인 구성을 제시하고, 확인하면 생성한다. 배포와 실행은 하지 않는다.","규칙":["원본 데이터 후보에서 파이프라인 수집 폴더와 잠긴 폴더는 뺀다.","생성에는 권한이 필요 없다."],"엣지":[],"미정":[]},{"묶음":"자원 생성 작업","fn":"FN-ORC-017","이름":"모델 배포 생성","동작":"요청한 모델과 자원 구성(노드 풀, GPU, CPU, RAM)을 제시하고, 확인하면 모델 배포를 만든다. 컴퓨팅 자원 사용 권한이 있으면 바로 배포하고, 없으면 배포 요청을 보내고 멈춘다.","규칙":["노드 풀의 잔여 GPU가 부족하면 대기 상태로 만든다.","권한이 없으면 상태는 대기, 사유는 승인 대기이고 「{이름} 모델 배포를 생성했습니다. 컴퓨팅 자원 사용 권한이 없어 배포 요청을 보냈습니다. 관리자가 승인하면 요청한 자원으로 배포합니다. 승인 결과는 알림으로 전달합니다.」로 답한다.","관리자가 승인하면 요청한 자원으로 바로 배포하고, 거절하면 요청 전 상태(생성됨)로 남는다."],"엣지":[],"미정":[]},{"묶음":"자원 생성 작업","fn":"FN-ORC-018","이름":"도구 등록","동작":"요청한 MCP 서버로 도구 등록 구성을 제시하고, 확인하면 도구를 등록한다. 배포는 하지 않는다.","규칙":["동작 목록은 도구 상세에서 연결을 확인한 뒤 보인다.","등록에는 권한이 필요 없다."],"엣지":[],"미정":[]},{"묶음":"자원 생성 작업","fn":"FN-ORC-019","이름":"생성 결과 안내","동작":"생성 작업이 끝나면 만든 항목의 링크를 결과와 함께 준다. 권한이 없어 요청을 보낸 경우에는 요청한 화면으로 이동할지 묻는다.","규칙":["대상은 워크플로우, RAG, 데이터 파이프라인, 모델 배포, 도구다.","대화 영역이 닫혀 있으면 「요청한 오케스트레이션 작업이 종료되었습니다.」로 작업 알림을 보낸다."],"엣지":[],"미정":[]},{"묶음":"데이터 파이프라인 작업","fn":"FN-ORC-020","이름":"데이터 파이프라인 노드 제안","동작":"데이터 파이프라인 설계에서 고른 노드 뒤에 이을 노드를 제안하고, 사용자가 [적용]하면 설계에 삽입한다. 삽입한 노드는 설정이 필요하면 설정 필요 상태로 들어간다.","규칙":["다른 구성원이 편집 중이면 제안할 때와 [적용] 순간 모두 막고 편집 점유 문장으로 답한다.","삽입만 하고 배포와 실행은 하지 않는다."],"엣지":[],"미정":[]},{"묶음":"실행 관리","fn":"FN-ORC-021~022","이름":"실행 상태 표시, 실행 관리","동작":"오케스트레이션이 실행되는 동안 단계별 진행 상태를 보이고 AGENTBASE 전체를 보기 전용으로 둔다. 작업 결과는 끝나는 순간 목록, 상세, 작업 이력에 반영한다.","규칙":["실행 중 허용 조작은 조회와 화면 이동뿐이다.","보기 전용은 다른 구성원의 화면에도 적용한다.","작업 이력 줄에는 「오케스트레이터」 경유를 표시한다."],"엣지":["실행 중에 이미 시작된 학습, 배포, 업로드 같은 다른 작업은 계속된다."],"미정":[]},{"묶음":"실행 관리","fn":"FN-ORC-023","이름":"요청 중지","동작":"사용자가 실행 중인 오케스트레이션을 중지하면 끝난 작업은 남기고 시작한 배포는 취소한 뒤, 끝난 작업과 취소한 작업을 답한다. 보기 전용을 푼다.","규칙":["이미 끝난 작업은 되돌리지 않는다.","보낸 배포 요청은 중지로 취소되지 않고 요청 관리에서 취소한다."],"엣지":[],"미정":[]},{"묶음":"실행 관리","fn":"FN-ORC-024","이름":"새로고침 뒤 상태 정리","동작":"실행 중에 화면을 새로고침하면 대화는 남기고 진행 중이던 작업은 중지로 표시하며, 보기 전용과 실행 중 표시를 푼다.","규칙":["새로고침으로 멈춘 작업은 실패가 아니라 중지다.","끝난 작업은 남는다."],"엣지":[],"미정":[]}]},{"모듈":"서비스 API 오픈","코드":"SVC","개요":"외부 서비스 하나를 연결하고 실행 자원을 잡아 서비스 API를 오픈해, 배포된 워크플로우 가운데 오픈한 것을 서비스 사용자가 부르게 한다. 서비스 사용 현황, 자원 사용 현황, 서비스 사용자, 개인 RAG·개인 도구를 모아 서비스 운영을 모니터링한다.","상태":["연결 전 → [서비스 연결](승인) → 오픈 준비(0회차 생김)","오픈 준비 → [서비스 API 오픈](승인) → 오픈됨(새 회차 열림, 실행 자원 점유)","오픈됨 → [오픈 중지](승인) → 오픈 중지(회차 닫힘, 실행 자원 반환)","오픈 중지 → [서비스 API 오픈](승인) → 오픈됨(새 회차, 켜 둔 워크플로우 함께 오픈)","워크플로우: 오픈 안 함 → [오픈](대표 모델 선택, 승인) → 오픈","워크플로우: 오픈 → [오픈 해제](승인) → 오픈 안 함(배포 회차 유지)","API Key: 사용 중 → [폐기] → 폐기 / 사용 중 → (만료 일시 경과) → 만료"],"공통":["하나의 AGENTBASE는 하나의 서비스에 API를 제공한다. 서비스 하나에 API가 둘이다: 서비스 쪽(서비스 URL, 연결 키)과 사용자·권한 쪽(사용자·권한 API URL, 연결 키).","서비스 API 오픈의 상태는 연결 전, 오픈 준비, 오픈됨, 오픈 중지 넷이다.","서비스 연결, 오픈, 오픈 중지, 서비스 설정 변경, 워크플로우 오픈과 해제, 그룹 변경, API Key 발급과 폐기는 서비스 API 오픈 권한이 필요하고, 없으면 같은 창에서 [다음]으로 요청을 보내 승인 순간 적용한다.","서비스 하나에 승인 대기 요청은 1건이다. 다른 구성원의 요청이 승인을 기다리면 서비스 설정 창의 선택지를 모두 비활성으로 둔다.","관리자가 [승인]을 누르는 순간 대상 상태와 요청자 권한을 다시 확인하고, 실행할 수 없으면 [승인]을 막고 이유를 보인다.","실행 자원(노드 풀, CPU, RAM, 스토리지)은 오픈한 순간 잡아 오픈 중지까지 점유한다. 호출이 없어도 점유한다. 서비스 노드 풀은 CPU 전용이라 GPU가 없다.","실행 자원은 호출 인증, 워크플로우 연결, 대화 저장을 맡는다. 답을 만드는 일은 각 워크플로우와 모델 배포의 자원이 한다. 개인 RAG와 개인 도구는 서비스 설정에서 따로 정한 자원을 쓴다.","회차는 오픈한 순간 열리고 오픈 중지로 닫힌다. 서비스를 처음 연결하면 0회차(오픈 준비)가 생기고, 오픈 전 서비스 설정 저장도 0회차에 남는다.","워크플로우 오픈의 단위는 배포 회차다. 오픈한 워크플로우는 서비스 API가 오픈된 동안 배포 중지와 롤백이 막혀 회차가 바뀌지 않는다.","서비스 사용 현황, 호출 이력, API Key 내역은 지우지 않는다. 화면에는 관리 설정의 이력 표시 기간 안의 것만 보이고, 리포트와 감사 이력 내보내기에는 모두 들어간다.","서비스 연결이 운영 중 끊기면 마지막으로 동기화한 사용자와 권한으로 호출을 계속 판정한다.","모니터링은 측정값만 보인다. 권고 문장은 두지 않는다. 원인 분석은 워크플로우 모니터링으로 넘긴다.","모니터링 수치는 요청이 끝나는 즉시 기록되고 화면이 다음에 새로 그려질 때 들어간다. 처리 중인 요청은 세지 않고, 요청은 받은 시각의 칸에 들어간다.","시험 호출은 서비스 사용 현황, 크레딧, 서비스 사용자 사용량 어디에도 세지 않는다."],"기능":[{"묶음":"서비스 API 오픈 상태 관리","fn":"FN-SVC-001","이름":"서비스 API 오픈 상태 표시","동작":"오픈 설정 탭 왼쪽 상세 정보에 오픈 상태, 서비스 URL, 사용자·권한 API URL, 오픈한 워크플로우 수, 노드 풀, 실행 자원, API 기본 주소, 승인 대기 요청을 보인다. 오픈한 워크플로우 수에 마우스를 올리면 이름 목록을 보인다.","규칙":["상세 정보에는 주소 두 칸만 두고, 연결 키 만료일은 주소에 마우스를 올리면 보인다.","연결 전에는 「워크플로우를 오픈할 서비스가 연결되지 않았습니다.」와 [서비스 연결](권한 없으면 [연결 요청], 내 요청이 대기 중이면 [연결 요청 취소])을 둔다.","연결 전에도 머리, 탭, 워크플로우 목록은 보이고 오픈 스위치만 비활성이다."],"엣지":["자원 빈 값은 「실행 자원 -」 한 칸으로 보인다."],"미정":[]},{"묶음":"서비스 API 오픈 상태 관리","fn":"FN-SVC-024","이름":"서비스 연결","동작":"서비스 쪽은 서비스 URL과 연결 키, 사용자·권한 쪽은 사용자·권한 API URL과 연결 키를 넣고 저장하면, 저장하는 순간 연결을 확인하고 확인이 끝나야 저장한다. 서비스 쪽을 처음 연결하면 0회차(오픈 준비)가 생기고, 사용자·권한 쪽을 연결하면 바로 동기화를 시작한다. 연결 뒤 변경은 서비스 설정 창의 서비스 연결 탭에서 한다.","규칙":["서비스 쪽은 서비스 API 오픈 권한, 사용자·권한 쪽은 권한 설정 변경 권한이 필요하다. 없으면 저장 대신 연결 요청을 보내고, 승인되면 서비스 ID를 확인한 뒤 저장한다.","나중에 연결하는 쪽의 서비스 ID가 먼저 연결된 쪽과 다르면 저장을 막고 칸 아래에 이유를 적는다.","연결 키는 첫 연결에서 필수다. 등록된 키는 「********」로 가려 보이고 새 키를 넣고 저장할 때만 바뀐다.","주소에 접속할 수 없으면 「주소에 접속할 수 없습니다.」, 키가 틀리거나 만료되었으면 「연결 키가 맞지 않거나 만료되었습니다.」를 칸 아래에 보이고 저장하지 않는다.","확인하는 동안 버튼은 「확인 중」이 되고 칸이 잠긴다.","연결 규격은 연결 창 제목 옆 [연결 규격 보기]로 본다.","저장하면 작업 이력에 설정 변경 한 줄을 남긴다."],"엣지":["두 쪽을 한 창에서 함께 바꾸면 서비스 쪽 응답의 서비스 ID를 기준으로 사용자·권한 쪽을 검사한다.","다른 구성원의 연결 요청이 기다리면 연결 창을 잠근다."],"미정":["운영 중 서비스 연동이 실패할 때 계속 쓰는 기능의 범위를 정책에 적을지 정하지 않았다. 구현은 마지막 동기화 값으로 계속 운영한다(D-25)."]},{"묶음":"서비스 API 오픈 상태 관리","fn":"FN-SVC-002","이름":"서비스 API 오픈","동작":"[서비스 API 오픈]하면 서비스 설정 창과 같은 탭(서비스 연결, 실행 자원, 개인 RAG, 개인 도구, API Key, 응답 캐시)으로 오픈 창을 연다. 노드 풀 잔여 자원, CPU·RAM 입력, 노드 1대 규격 이내를 확인한 뒤 오픈하면 실행 자원을 잡고 새 회차를 열며, 켜 둔 워크플로우가 같은 순간 서비스의 그룹·모델 선택지에 보인다.","규칙":["서비스 연결과 배포된 워크플로우가 하나 이상 있어야 활성이다. 툴팁은 「서비스를 연결해야 오픈할 수 있습니다.」, 「배포된 워크플로우가 있어야 서비스 API를 오픈할 수 있습니다.」 차례다.","권한(서비스 API 오픈)이 없으면 오픈 요청을 보내고 승인되면 오픈한다.","잔여 노드가 없는 노드 풀은 고를 수 없다.","연결했으면 오픈 전에도 서비스 설정을 저장할 수 있고 저장한 값으로 오픈한다."],"엣지":["오픈한 워크플로우가 하나도 없어도 오픈할 수 있고, 그동안 부를 수 있는 워크플로우가 없다.","슈퍼 계정은 다른 구성원의 대기 요청이 있어도 막지 않는다."],"미정":[]},{"묶음":"서비스 API 오픈 상태 관리","fn":"FN-SVC-003","이름":"서비스 API 오픈 중지","동작":"[오픈 중지]하면 새 호출을 바로 막고 실행 자원을 돌려주며 그 회차를 닫는다. 워크플로우별 오픈 설정은 지우지 않아 목록의 오픈 스위치는 켜 둔 값을 보이되 비활성이고, 다시 오픈하면 켜 둔 워크플로우가 함께 오픈된다.","규칙":["권한(서비스 API 오픈)이 없으면 중지 요청을 보내고 승인되면 중지한다.","중지 요청이 승인을 기다리는 동안 워크플로우를 새로 오픈할 수 없고 해제는 할 수 있다.","오픈 중지 상태의 스위치 툴팁은 「서비스 API 오픈이 중지되어 호출되지 않습니다. 서비스 API를 다시 오픈하면 이 워크플로우도 함께 오픈됩니다.」다.","작업 이력에 「실행 | 서비스 API | 오픈 중지」로 남고 그 회차가 끝난다."],"엣지":["오픈 중지 상태에서 오픈해 둔 워크플로우의 배포를 중지하면 그 워크플로우의 오픈도 해제되어 다시 오픈할 때 함께 열리지 않는다. 작업 이력에 「오픈 해제(배포 중지)」를 남긴다.","오픈 중지 상태에서는 오픈해 둔 워크플로우의 롤백을 막는다."],"미정":["중지할 때 처리 중인 요청에 끝까지 응답할지, 기다리는 시간의 상한을 둘지 정하지 않았다. 구현은 다음 노드 경계에서 멈추고 30초 안에 연결이 끊긴다(D-24, C-01)."]},{"묶음":"서비스 설정","fn":"FN-SVC-004","이름":"서비스 설정 변경","동작":"[서비스 설정]은 오픈 창과 같은 탭이며, 오픈된 동안에도 중지하지 않고 모든 탭을 바꿔 바닥 [저장] 한 번으로 함께 적용한다. 실행 자원이나 노드 풀을 바꾸면 새 자원으로 다시 띄우고, 개인 RAG의 임베딩 모델을 바꾸면 개인 RAG 검색 DB에 반영한다.","규칙":["권한(서비스 API 오픈)이 없으면 같은 창에서 [다음]으로 변경 요청을 보낸다.","개인 RAG 설정은 임베딩 모델, 청킹, 리랭커 모델, 리랭크 결과 수(top_n), 오토 스케일링이다.","개인 도구 설정은 오토 스케일링(기준, 기준값, 레플리카 범위, 레플리카당 CPU와 RAM)이다.","바꾼 칸마다 작업 이력에 설정 변경 한 줄을 남긴다.","잔여 노드가 없는 노드 풀은 고를 수 없다."],"엣지":["다시 띄우는 동안 처리 중인 요청은 오픈 중지 때와 같은 원칙을 따른다."],"미정":["오픈 중에 실행 자원을 바꾸는 것을 허용하고 무중단으로 적용할지, 오픈 중에는 잠글지 정하지 않았다. 4340 화면은 허용, 구현은 잠근다(C-02)."]},{"묶음":"서비스 설정","fn":"FN-SVC-005","이름":"API Key 관리","동작":"서비스 설정 창의 API Key 탭에서 키를 발급하고 폐기한다. 발급과 폐기는 초안에 담겼다가 바닥 [저장](권한이 없으면 요청)에서 다른 탭의 변경과 함께 적용된다. 발급한 키는 즉시 쓸 수 있고, 폐기와 만료는 그 순간 막힌다.","규칙":["서비스 API 오픈 권한이 필요하다.","키 값은 발급 직후 한 번만 보이고, 이후에는 끝 네 글자만 보인다. 키 값은 저장하지 않는다.","발급 때 만료 일시를 고른다. 만료는 최대 365일 또는 무기한이다.","키는 여러 개를 함께 발급할 수 있어, 새 키를 먼저 쓰게 한 뒤 옛 키를 폐기하면 끊김 없이 바꾼다.","발급, 폐기, 만료 내역은 지우지 않는다. 한 줄은 키 이름, 끝 네 글자, 발급자, 발급 일시, 만료 일시, 폐기한 사람과 일시, 상태(사용 중, 폐기, 만료)다.","만료 일시가 지나면 작업 이력에 「만료」 시스템 줄을 남긴다.","API 가이드 탭은 키 목록과 시험 호출만 둔다."],"엣지":["사용 중인 키를 모두 폐기하면 서비스의 호출은 모두 인증 실패가 된다.","같은 이름으로 다시 발급해도 이전 키 내역은 따로 남는다.","서비스 연결을 끊거나 오픈을 중지해도 내역은 남는다.","다른 구성원이 편집 중이면 발급·폐기를 할 수 없다."],"미정":["옛 키에 유예 기간을 주는 교체 기능을 둘지, 키 개수를 하나로 제한할지 정하지 않았다(D-22)."]},{"묶음":"서비스 설정","fn":"FN-SVC-006","이름":"응답 캐시 설정","동작":"응답 캐시는 서비스 설정과 워크플로우 정보 양쪽에 있고, 둘 다 사용일 때만 같거나 비슷한 질문에 저장한 응답을 모델 실행 없이 돌려준다. 저장한 응답으로 답한 요청은 요청 수에는 넣고 모델 사용량과 크레딧은 0으로 세며, 호출 이력에 「저장된 응답」으로 남는다.","규칙":["처음 값은 둘 다 사용 안 함이다.","서비스 쪽 설정은 서비스 API 오픈 권한을 거치고, 워크플로우 쪽은 워크플로우 정보 수정이라 권한이 필요 없다.","개인 RAG를 쓴 응답과 민감 정보가 든 응답은 저장하지 않는다.","근거 문서가 바뀌거나 유효기간이 지나면 저장한 응답을 지운다."],"엣지":["서비스 쪽을 끄면 워크플로우 쪽 값과 상관없이 쓰지 않는다."],"미정":[]},{"묶음":"워크플로우 오픈","fn":"FN-SVC-007","이름":"워크플로우 목록 조회","동작":"오픈 설정 탭 오른쪽에 배포된 워크플로우를 그룹별로 보이고, 줄마다 대표 모델, 배포 회차, 최근 보안 평가 결과, 오픈 상태를 보인다.","규칙":["대표 모델 칸에 마우스를 올리면 워크플로우가 쓰는 모델을 타입별로 보이고 대표 모델에 「(대표 모델)」을 붙인다.","오픈한 워크플로우가 없는 그룹은 서비스에 보이지 않는다."],"엣지":["배포된 워크플로우만 목록에 오른다. 오픈해 둔 워크플로우의 배포가 중지되면 그 오픈도 해제된다."],"미정":[]},{"묶음":"워크플로우 오픈","fn":"FN-SVC-008","이름":"워크플로우 오픈 설정","동작":"워크플로우 줄의 오픈 스위치를 켜면 오픈 창(권한 없으면 오픈 요청 창)에서 대표 모델을 고르고, 오픈한 순간(요청이면 승인 순간)부터 그 워크플로우를 부를 수 있다. 끄면 그 뒤 들어온 요청에는 「오픈되지 않았습니다」 응답이 가고 지금 배포 회차는 유지된다.","규칙":["오픈 스위치는 오픈 준비와 오픈됨에서만 켜고 끈다. 연결 전과 오픈 중지에서는 비활성이다.","막히는 이유는 다음 차례로 먼저 걸린 하나를 툴팁으로 보인다: 서비스 API 오픈 중지, 서비스 연결 전, 그룹 없음, 모델 없음, 고를 수 있는 대표 모델 없음, 다른 구성원의 오픈 중지 요청 대기.","보안 평가는 오픈의 필수 조건이 아니다. 통과 기준을 두지 않고, 평가 결과가 없어도 오픈할 수 있다.","대표 모델 선택지는 워크플로우가 쓰는 모든 모델(LLM, VLM, Image Generation, Embedding, Reranker, TTS, STT)을 노드에서 많이 쓴 차례로 두고 「노드 n개」를 적는다.","같은 그룹에서 오픈했거나 오픈 승인 대기인 워크플로우의 대표 모델은 고를 수 없다(「{워크플로우}에서 사용 중」). 해제 대기인 워크플로우도 오픈한 것으로 센다.","대표 모델 처음 값은 지난번 대표 모델이고, 쓸 수 없으면 고를 수 있는 첫 모델이다. 오픈한 동안 바꿀 수 없다.","관리자와 일반 구성원에게 같은 이유를 보인다."],"엣지":["요청은 승인할 때 고른 모델이 대표 모델이 된다. 그 사이 같은 그룹의 다른 워크플로우가 같은 모델로 오픈되면 [승인]을 막는다.","회차가 바뀌는 길은 오픈 해제 뒤 배포 중지, 또는 오픈 중지 상태에서 배포 중지뿐이다. 새 회차는 오픈 전 상태로 시작해 다시 오픈한다.","프롬프트만 바꾼 경우는 회차가 바뀌지 않아 계속 불린다."],"미정":[]},{"묶음":"워크플로우 오픈","fn":"FN-SVC-009","이름":"워크플로우 그룹 관리","동작":"같은 일을 하고 대표 모델만 다른 워크플로우를 그룹으로 묶는다. 서비스 사용자는 그룹을 고른 뒤 모델을 고르고, 그 모델의 워크플로우가 실행된다. 워크플로우 이름은 서비스에 보이지 않는다.","규칙":["권한(서비스 API 오픈)이 없으면 그룹 설정, 이름 변경, 해제, 이동을 요청으로 하고, 대기 중에는 그룹 메뉴를 막는다.","오픈했거나 오픈 승인 대기인 워크플로우는 그룹을 옮길 수 없고, 그런 워크플로우가 있는 그룹은 해제할 수 없다.","새 그룹 이름이 비었거나 같은 이름이 있으면 저장을 막는다.","옮겨서 워크플로우가 하나도 남지 않은 그룹은 해제한다.","그룹 이름, 설명, 가이드 질문은 서비스 기능 한 벌이 가진다."],"엣지":["그룹 해제 요청은 확인 창 없이 승인 요청 창을 연다.","요청 전 초안은 목록에 보이지 않는다.","오픈하지 않은 워크플로우는 모델과 상관없이 같은 그룹에 넣고 옮길 수 있다."],"미정":[]},{"묶음":"서비스 사용 현황","fn":"FN-SVC-010","이름":"서비스 지표 조회","동작":"기간을 골라 서비스 전체의 요청, 사용자, 만족도, 응답 성능, 에러율, 토큰과 비용 지표를 보고, 지표마다 워크플로우별 값을 비교한다. 오픈 워크플로우 수에 마우스를 올리면 요청이 많은 차례의 이동 목록이 열리고, 줄을 고르면 그 워크플로우 모니터링을 서비스 호출, 같은 기간으로 연다.","규칙":["칸 폭은 기간에 따라 정한다: 최근 1시간 5분, 6시간까지 30분, 2일까지 1시간, 그보다 길면 하루.","진행 중인 마지막 칸은 「집계 중」으로 표시한다.","에러율은 워크플로우나 연결 자원이 실패한 요청만 센다. 권한·한도로 막힌 호출과 삭제된 사용자의 요청은 차단으로 따로 센다.","크레딧 소진으로 멈춘 요청은 요청 수에 넣고 에러율에는 넣지 않는다.","API Key가 맞지 않아 들어오지 못한 호출은 세지 않고 시스템 로그에만 남긴다.","만족도는 좋아요 비율이고, 싫어요 사유는 따로 모은다. 권한으로 걸러 봐도 만족도는 거르지 않는다.","요청 급증(직전 1시간 5분 평균의 3배 이상)과 응답 지연(p95가 직전 1시간 p95의 2배 이상)은 5분 구간이 끝날 때 판정해 생성자와 관리자에게 알린다. 30분 안의 같은 알림은 한 줄로 묶는다.","보는 일은 작업 이력에 남지 않는다."],"엣지":["좋아요·싫어요가 늦게 오면 원래 요청이 있던 칸의 만족도가 나중에 바뀐다.","직전 1시간 기록이 없으면 급증·지연을 판정하지 않는다.","서비스 API로 불리지 않는 워크플로우의 모니터링은 AGENTBASE 호출로 연다."],"미정":["화면을 열어 둔 동안 자동으로 새로 그리는 주기를 정하지 않았다(5분보다 짧게 둔다).","권한·한도로 막힌 요청을 에러율에서 빼고 차단 수로 따로 셀지 확정하지 않았다(C-09).","서비스 사용 현황과 자원 사용 현황의 칸 폭을 하나로 맞출지 정하지 않았다(C-10)."]},{"묶음":"자원 사용 현황","fn":"FN-SVC-011~013","이름":"자원 사용 현황(호출 자원, 실행 자원, 개인 자산)","동작":"서비스 요청이 부른 모델 배포, RAG, 도구별 사용 현황과, 실행 자원의 GPU·CPU·RAM·스토리지 사용률과 용도별 사용량을 보인다. 개인 RAG와 개인 도구는 판 하나가 실행 단위 하나로, 요청 수, 응답 시간 p95, CPU·RAM 사용률, 지금 레플리카 수와 오토 스케일링 설정, 레플리카 증감 기록을 보인다.","규칙":["CPU·RAM 사용률 칸 폭은 6시간까지 10분, 7일까지 1시간, 30일까지 4시간, 그보다 길면 하루다.","개인 RAG·개인 도구 하나하나와 사용자별 사용량은 이 탭에서 세지 않는다.","실행 자원 사용률이 시스템 자원 알림 기준을 넘으면 구성원 전원에게 자원 사용률 초과 알림을 보낸다.","GPU를 쓰지 않으면 CPU·RAM 줄만 보인다."],"엣지":["모델 배포가 늘어나야 하는데 자원이 모자라면 지금 레플리카로 계속 응답하고, 응답 시간이 늘면 응답 지연 알림으로 드러난다."],"미정":[]},{"묶음":"서비스 사용자 조회","fn":"FN-SVC-014~015","이름":"서비스 사용자 목록과 상세","동작":"서비스가 보낸 서비스 사용자의 권한, 사용량, 이번 달 크레딧, 크레딧 한도 상태, 이번 달 추가 지급 크레딧을 보인다. 상세에서는 사용 현황, 개인 RAG, 개인 도구와, 한도에 닿은 사용자의 도달 일시와 추가 지급 이력을 보인다. 사용량은 요청이 끝나는 순간 더해지고 한도와 추가 지급은 동기화할 때 바뀐다.","규칙":["한도 상태는 월 크레딧 한도에 이번 달 추가 지급을 더한 값 대비 이번 달 사용률로 정한다: 80% 미만 정상, 80% 이상 한도 임박, 100% 이상 한도 도달.","월 한도와 추가 지급은 서비스에서 동기화한 보기 전용 값이다. 추가 지급 승인자는 서비스 관리자(AGENTBASE 구성원 아님)다.","매달 1일 0시에 이번 달 사용량과 추가 지급을 0부터 다시 센다.","AGENTBASE는 서비스 사용자에게 한도 알림을 보내지 않고, 알림 종류도 더하지 않는다.","사용자 이름과 계정은 가려 보인다."],"엣지":["서비스가 추가 지급을 알려 오면 그 사용자만 바로 반영한다.","동기화가 실패하면 직전에 받은 한도로 판정한다.","서비스에서 삭제된 사용자는 「삭제됨」으로 남고 지난 사용량과 크레딧 기록은 그대로 둔다. 그 사용자의 개인 RAG와 개인 도구는 정리 대상이 되어 지워진다.","동기화 전의 새 사용자는 사용 현황에는 바로 세지만 목록에는 다음 동기화 뒤에 보인다."],"미정":["서비스가 보내는 사용자 상태 inactive를 삭제로 볼지 일시 정지로 볼지 정하지 않았다(C-08)."]},{"묶음":"개인 RAG 현황","fn":"FN-SVC-016~018","이름":"개인 RAG 목록, 검색 추이, 상세","동작":"서비스 사용자가 만든 개인 RAG의 목록과 검색 추이, 에러를 보이고, 상세에서 정보, 호출 이력, 문서 활용을 보인다. 조회만 하고 AGENTBASE 구성원은 개인 RAG를 만들거나 고치지 않는다.","규칙":["개인 RAG는 서비스 설정의 개인 RAG 설정(임베딩 모델, 청킹, 리랭커)과 자원을 쓴다.","개인 RAG를 쓴 응답은 응답 캐시에 저장하지 않는다."],"엣지":["임베딩 모델을 바꾸면 개인 RAG 검색 DB에 반영된다.","작성자가 서비스에서 삭제되면 그 사용자의 개인 RAG는 지워진다."],"미정":[]},{"묶음":"개인 도구 현황","fn":"FN-SVC-019~021","이름":"개인 도구 목록, 호출 추이, 상세","동작":"서비스 사용자가 등록한 개인 도구의 목록과 호출 추이, 에러를 보이고, 상세에서 정보와 호출 이력을 보인다. 조회만 한다.","규칙":["개인 도구는 서비스 설정의 개인 도구 자원(오토 스케일링)을 쓴다."],"엣지":["작성자가 서비스에서 삭제되면 그 사용자의 개인 도구는 지워진다."],"미정":[]},{"묶음":"API 가이드","fn":"FN-SVC-022","이름":"API 가이드와 호출 판정","동작":"외부 서비스가 서비스 API로 워크플로우를 부르는 방법, 키 목록, 시험 호출, 호출 현황을 보인다. 호출 하나는 API Key 확인, 오픈된 워크플로우 확인, 사용자 권한으로 워크플로우 사용 판정, 실행 차례로 확인하고, 실행 중에는 RAG·도구를 부를 때마다 권한과 한도를 확인하고 크레딧을 센다. 응답에는 실행 식별자가 함께 가고 요청이 끝나면 사용 장부에 한 줄 남는다.","규칙":["API Key가 없거나 맞지 않으면 인증 실패로 끝낸다.","오픈하지 않은 워크플로우면 「{워크플로우} 에이전트가 오픈되지 않았습니다.」로 끝낸다.","서비스 사용자의 권한이 그 워크플로우를 허용하지 않으면 「그 권한으로는 이 에이전트를 사용할 수 없습니다」로 끝낸다.","배포가 멈췄거나 응답하지 않으면 「{워크플로우} 에이전트가 응답하지 않습니다.」로 끝내고 에러로 센다.","워크플로우 안의 RAG·도구 하나만 막히면 요청 전체를 거부하지 않고 그것만 빼고 실행한다. 개인 인증이 안 된 도구도 빼고, 응답에 인증 필요 안내를 넣는다.","사용자 검토 노드에 닿으면 검토 대기 상태와 선택지를 응답하고, 재개 호출로 고른 분기를 받아 이어 간다.","대화 식별자가 없으면 새 대화로 처리한다.","시험 호출은 서비스 API를 오픈한 뒤에만 된다.","호출 현황과 서비스 사용 현황은 같은 사용 장부를 세므로 같은 기간이면 요청 수가 같다."],"엣지":["좋아요·싫어요는 실행 식별자로 원래 요청을 찾아 만족도에 반영한다. 없는 실행 식별자면 「실행이 없습니다」를 돌려주고 반영하지 않는다.","삭제된 사용자의 요청은 실행하지 않고 사용할 수 없다는 응답을 돌려주며 차단으로 센다.","요청에 권한 체계에 없는 속성 값이 오면 거부하지 않고 「전체」의 값만으로 처리하고 동기화를 시작한다.","크레딧을 요청 도중 다 쓰면 그때까지 만든 답과 「크레딧을 모두 사용해 응답을 멈췄습니다.」를 돌려주고, 요청은 「크레딧 소진으로 중단」으로 남는다."],"미정":["서비스 API 오픈이 중지된 상태의 응답 코드, 한도 초과, 크레딧 소진, 검토 대기 응답이 오류 코드 목록에 없다. 코드를 정해 목록에 넣는다.","도구 호출 한도를 넘었을 때 그 호출만 막고 요청을 이어 갈지 확정하지 않았다. 구현은 그 호출만 막는다(D-16).","권한을 요청에 실려 온 값으로 판정할지, 마지막 동기화 값으로만 판정할지 정하지 않았다(C-03).","크레딧 한도를 넘은 요청을 AGENTBASE가 도중에도 멈출지, 서비스가 요청 전에만 막을지 정하지 않았다(C-04)."]},{"묶음":"작업 이력","fn":"FN-SVC-023","이름":"작업 이력 조회","동작":"서비스 API 오픈 회차별로 상태, 오픈 기간, 실행자, 중지한 구성원, 승인자, 오픈한 워크플로우 수, 그룹, 노드 풀, 실행 자원을 보이고, 회차 상세에서 오픈과 오픈 중지, 설정과 자원 변경, 워크플로우 오픈 변경, API Key 변경, 다운로드를 변경 전후, 반영 상태, 승인자와 함께 보인다.","규칙":["0회차는 오픈 준비(처음 연결한 일시와 구성원)다. 연결 전에는 회차가 없다.","회차 목록의 CPU, RAM은 실행 자원, 개인 RAG, 개인 도구의 합이다.","권한 없이 요청한 일은 따로 줄을 만들지 않고 그 일의 줄에 승인 대기, 반영됨과 승인자, 반려(사유)로 남는다.","API Key 발급은 변경 후에 키 끝 네 글자와 만료 일시, 폐기는 사용 중에서 폐기로 남는다.","서비스 사용 현황과 개인 RAG·개인 도구 목록을 보는 일은 남기지 않는다."],"엣지":["오픈한 워크플로우가 새 배포 회차로 바뀌면서 오픈이 이어지는 경우는 없다. 오픈 중지 상태의 배포 중지는 「오픈 해제(배포 중지)」로 남는다."],"미정":[]}]},{"모듈":"권한 설정","코드":"PRM","개요":"연결한 서비스에서 권한 체계(권한 유형과 항목)와 서비스 사용자를 동기화해 「전체」 아래 계층으로 두고, 작업(RAG, 도구, 워크플로우)마다 서비스 사용자가 쓸 수 있는 권한과 사용자별 한도를 정한다. 권한 체계는 서비스가 만들고 고치며 AGENTBASE는 보기만 한다.","상태":["연결 전 → [API 연결](승인) → 연결됨, 동기화 시작","연결됨 → [동기화] 또는 자동 시작 → 동기화 중 → 연결됨(반영) 또는 동기화 실패(직전 값 유지)"],"공통":["대상은 서비스가 보낸 서비스 사용자다. AGENTBASE 구성원의 권한은 관리 설정의 구성원 권한이 정한다.","트리 맨 위의 권한(모든 서비스 사용자가 받는 권한)은 화면, 알림, 작업 이력, 문서에서 모두 「전체」로 부른다.","연결된 사용자·권한 API가 없으면 연결 외의 권한 설정을 막는다. 첫 화면은 「연결된 서비스가 없습니다.」와 [API 연결](권한 없으면 [연결 요청])이다.","권한 값 변경, 연결 변경, [동기화]는 권한 설정 변경 권한이 필요하다. 권한 값 변경과 연결은 권한이 없으면 요청 뒤 승인으로 하고, [동기화]는 요청 없이 비활성이다.","권한 설정 전체에 대기 요청은 1건이다. 대기 중에는 요청자의 권한 값 칸을 잠그고 [변경 요청 취소]를 둔다.","편집 점유는 권한 설정 전체에 1명이다. 권한 없는 구성원도 변경안을 쓰는 동안 점유하고, 요청을 보낸 뒤에는 점유하지 않는다. 3분 동안 조작이 없으면 점유를 풀고 바꾼 값을 지운다.","권한 값은 저장한 순간(요청이면 승인한 순간) 다음에 들어온 요청부터 적용된다. 처리 중인 요청은 시작할 때의 권한으로 끝까지 처리한다.","관리자가 [승인]을 누르는 순간 대상 칸이 동기화로 없어졌으면 그 칸은 반영하지 않고, 실행할 칸이 없으면 [승인]을 막는다.","관리자로 지정된 구성원의 기존 대기 요청은 자동 취소하지 않고 본인이 직접 승인하거나 거절한다.","회차가 없고 일 하나가 작업 이력 한 줄이다.","사용자 이름과 계정은 가려 보인다.","모델 토큰 한도는 없다. 서비스 사용자의 크레딧 한도와 지급은 서비스가 정한다."],"기능":[{"묶음":"서비스 연동","fn":"FN-PRM-001","이름":"사용자·권한 API 연결","동작":"사용자·권한 API URL과 연결 키를 넣고 저장하면 저장하는 순간 연결을 확인하고, 확인이 끝나면 저장하고 바로 동기화를 시작한다. 연결은 서비스 API 오픈의 서비스 연결과 같은 서비스여야 한다.","규칙":["권한 설정 변경 권한이 필요하다. 없으면 [연결 요청](연결 뒤에는 [변경 요청])을 보내고, 승인되는 순간 서비스 ID를 확인해 저장하고 동기화한다.","사용자·권한 API URL은 서비스 URL과 다른 주소이고, 서비스 ID가 같아야 한다. 먼저 연결된 쪽과 서비스 ID가 다르면 저장을 막고 칸 아래에 이유를 적는다.","연결 키는 첫 연결에서 필수다. 등록된 키는 가려 보이고 새 키를 넣을 때만 바뀐다.","주소 접속 불가, 키 불일치·만료면 칸 아래에 이유를 보이고 저장하지 않는다.","동기화 중에는 연결을 바꿀 수 없다.","[연결 규격 보기]로 API 규격을 본다.","저장하면 작업 이력에 「사용자·권한 API 연결 변경」 한 줄을 남긴다."],"엣지":["연결 뒤 끊기면 마지막으로 받은 권한과 사용자로 계속 운영하고, 그동안 권한 값 저장은 된다.","다른 구성원의 연결 요청이 기다리면 연결 창을 잠근다."],"미정":[]},{"묶음":"서비스 연동","fn":"FN-PRM-002","이름":"권한 체계 동기화","동작":"[동기화]하면 서비스의 권한 유형과 항목, 서비스 사용자(계정, 이름, 속성, 크레딧 한도와 추가 지급)를 연결 확인, 권한 체계, 사용자 차례로 끝까지 받은 뒤 한 번에 바꾼다. 진행하는 동안 누가 들어와도 본문을 덮고 「동기화 중입니다.」와 「{이름}님이 {일시}에 시작했습니다.」를 보이며 권한 값 변경과 연결 변경을 막는다. 끝나면 「동기화를 마쳤습니다.」를 보이고 작업 이력에 동기화 한 줄을 남긴다.","규칙":["권한 설정 변경 권한이 없으면 [동기화]는 비활성이다(「권한 설정 변경 권한이 있어야 동기화할 수 있습니다.」). 요청은 없다.","동기화는 [동기화], 사용자·권한 API의 첫 저장과 변경 승인, 서비스가 변경을 알려 올 때, 요청에 모르는 권한 단계가 들어올 때 시작한다. 자동으로 시작한 동기화는 5분에 한 번까지이고 실행자는 「시스템」이다.","서비스에서 없어진 권한은 그 권한에 지정한 값도 함께 지우고, 동기화 줄에 지운 지정 값 수를 적는다.","새로 생긴 권한은 값을 지정하지 않은 권한으로 트리에 흐리게 더해 상위 값을 받는다.","서비스 사용자의 요청은 동기화 중에도 멈추지 않고 직전 값으로 판정한다.","사용자 한 명의 추가나 삭제만 알려 온 경우에는 그 사용자만 바로 반영한다."],"엣지":["일부만 받고 끊기거나 연결 키가 만료·거절되면 하나도 반영하지 않고 직전 값을 그대로 쓴다. 「동기화하지 못했습니다.」와 이유를 보이고 작업 이력 반영 상태는 실패다.","동기화 중에 또 알려 온 변경은 지금 동기화가 끝나고 5분 뒤 한 번 더 가져온다.","동기화로 지운 권한 값이 담긴 승인 대기 요청은 남은 칸만 승인 때 적용한다.","서비스에서 삭제된 사용자는 「삭제됨」으로 남고 요청이 막힌다."],"미정":["다른 구성원이 저장하지 않은 권한 값 변경이 있는 동안 [동기화]를 막을지, 진행하고 없어진 권한의 변경만 버릴지 정하지 않았다(N-10).","자동 동기화(서비스 변경 알림, 회원 단위 갱신)를 정식 규격과 정책에 넣을지 정하지 않았다. 구현에는 있다(D-20, C-07)."]},{"묶음":"권한 체계","fn":"FN-PRM-003","이름":"권한 체계 조회","동작":"서비스에서 가져온 권한 체계를 「전체」 아래로 권한 유형 차례대로 모든 항목을 펼쳐 보인다. 권한마다 소속 사용자 수를 적고, 값을 지정하지 않은 권한은 흐리게 보인다.","규칙":["권한 체계는 보기 전용이다. 권한 유형과 항목의 생성, 수정, 삭제와 단계 변경은 서비스에서 한다.","권한 유형 이름은 서비스가 보내는 사용자 속성 이름이고, 항목 이름은 그 속성의 값이다.","서비스에서 바꾼 권한 체계는 다음 동기화부터 반영한다.","트리 줄을 누르면 펼치고 고른다. 저장하지 않은 값이 있는 권한은 표시가 붙는다."],"엣지":["권한 트리를 보는 일은 작업 이력에 남지 않는다."],"미정":[]},{"묶음":"권한 체계","fn":"FN-PRM-004","이름":"적용 권한 조회","동작":"권한마다 매핑된 사용자와, 사용자마다 받는 권한과 쓸 수 있는 RAG, 도구, 워크플로우를 보인다. 사용자는 서비스가 보낸 속성이 경로의 모든 항목 이름과 같은 가장 깊은 권한에 매핑되고, 지정하지 않은 값은 경로를 따라 상위 권한에서 받는다.","규칙":["맞는 권한이 둘 이상이면 허용은 합치고 한도는 큰 값을 쓴다.","서비스가 승인한 적용 중인 추가 권한은 그 사용자의 권한에 더한다.","맞는 권한이 없는 사용자는 「전체」의 값만 받는다.","속성 값이 권한 체계에 없으면 「전체」의 값만 적용하고 관리자에게 매핑 확인 알림을 하루 한 번 보낸다. 같은 값을 가진 사용자가 여럿이면 값마다 한 줄이다. 이 알림은 수신 설정으로 끌 수 없다.","사용자 이름과 계정은 가려 보인다."],"엣지":["요청에 권한 체계에 없는 값이 오면 요청은 거부하지 않고 「전체」의 값으로 처리하며, 권한 항목별 보기에서는 「전체」에 들어간다."],"미정":[]},{"묶음":"작업별 권한","fn":"FN-PRM-005","이름":"작업별 권한 조회","동작":"작업(RAG, 도구, 워크플로우)마다 허용한 권한과 쓸 수 있는 사용자 수, 한도를 보이고, 그 작업을 쓰는 워크플로우를 보인다. 보기 기준으로 권한별, 작업별을 바꾼다.","규칙":["RAG·도구의 전체 상한은 사용자별 한도 칸 아래에 「전체 n회」로 참고 표시한다."],"엣지":["삭제된 작업은 목록에서 빠지고 지정 값도 함께 사라진다."],"미정":[]},{"묶음":"작업별 권한","fn":"FN-PRM-006","이름":"접근 권한 지정","동작":"작업마다 서비스 사용자가 쓸 수 있는 권한을 허용 또는 차단으로 정한다. 도구는 동작마다 정한다. 지정하지 않은 권한은 상위 권한의 값을 받고, 상위 권한이 허용한 범위 안에서 일부 권한을 차단한다. 권한이 있으면 [저장]으로 즉시 적용하고, 없으면 [변경 요청]으로 바꾼 칸만 실어 승인을 요청한다.","규칙":["대상은 모듈마다 만든 작업 전부다.","맞는 권한이 둘 이상이면 허용을 합친다.","저장하면 다른 관리자에게 권한 변경 알림을 보내고 바뀐 칸마다 작업 이력 한 줄을 남긴다.","승인되면 요청에 실은 칸만 적용하고 그 사이 다른 사람이 바꾼 칸은 되돌리지 않는다.","저장하지 않고 다른 탭·메뉴로 가면 나가기 창을 띄우고, 브라우저 이동이면 변경을 버리고 「저장하지 않은 변경 n건은 반영하지 않았습니다.」를 알린다."],"엣지":["워크플로우 안의 RAG·도구 하나에 권한이 없으면 요청을 거부하지 않고 그것만 빼고 실행한다."],"미정":["어디에도 값을 지정하지 않은 새 워크플로우·RAG·도구의 처음 값을 차단으로 할지 허용으로 할지 정하지 않았다. 정책은 차단, 구현은 생성 때 「전체 허용」을 저장한다(D-14, C-06)."]},{"묶음":"작업별 권한","fn":"FN-PRM-007","이름":"사용자별 한도 지정","동작":"허용한 권한마다 RAG는 일일 요청 한도, 도구는 시간당 호출 한도를 사용자별로 정하고, 권한 유형의 항목 기준으로 여러 권한에 한 번에 지정한다. 워크플로우는 한도가 없다. 한도를 넘은 호출은 MCP 게이트웨이가 막고 기록한다.","규칙":["RAG·도구의 전체 상한(모든 서비스 사용자 합계)이 사용자별 한도보다 먼저 적용된다. 사용자별 한도의 최댓값은 전체 상한이다.","맞는 권한이 둘 이상인 사용자는 큰 값을 받는다.","한도를 넘으면 그 호출만 거절 문장으로 돌려주고 요청은 계속 진행한다. 요청은 성공으로 남고 막힌 호출은 차단으로 센다.","편집과 요청 규칙은 접근 권한 지정과 같다."],"엣지":["한도를 세는 곳에 장애가 나면 통과시키지 않고 그 호출만 막으며 시스템 로그에 「한도 확인 불가」로 남긴다."],"미정":["한도 값 0과 빈 값의 뜻을 정하지 않았다. 정책은 0 = 제한 없음, 구현은 0 = 차단이다(C-05).","전체 상한을 정시 구간으로 셀지 이동 구간으로 셀지, 언제 초기화할지 정하지 않았다(P-36).","전체 상한을 이미 정한 사용자별 한도보다 작게 줄일 때 저장을 허용하고 표시만 할지, 막을지 정하지 않았다(N-11).","한도 확인 불가를 관리자에게 알릴지 정하지 않았다."]},{"묶음":"작업 이력","fn":"FN-PRM-008","이름":"작업 이력 조회","동작":"사용자·권한 API 연결 변경, 동기화, 권한 설정 변경을 일 하나에 한 줄로 보인다. 권한 설정 변경은 저장 한 번에 바뀐 칸마다 한 줄로 대상(권한 경로 · 자원 종류 이름), 항목, 변경 전후, 반영 상태, 실행 일시, 실행자, 승인자를 적는다.","규칙":["권한 체계의 변경은 서비스에서 하므로 동기화 줄로만 남는다.","권한 없는 구성원의 요청은 변경 줄에 승인 대기로 남고, 승인되면 승인자와 반영됨이 된다.","자동으로 시작한 동기화의 실행자는 「시스템」이다.","기록은 지우지 않고 화면에는 이력 표시 기간 안의 것만 보인다."],"엣지":["저장하지 않은 변경은 남지 않는다."],"미정":[]}]},{"모듈":"크레딧","코드":"CRD","개요":"서비스 사용자가 워크플로우를 한 번 부를 때 쓴 모델 사용량과 도구 호출을 하나의 단위로 환산하는 비율을 정한다. 시스템은 호출이 끝난 시점의 비율로 크레딧을 계산해 서비스에 전달하고, 사용자별 한도와 지급, 초과 차단은 서비스가 맡는다.","상태":[],"공통":["크레딧 비율 변경은 권한 설정 변경 권한으로 판정한다. 권한이 있으면(관리자 포함) [저장]으로 바로 적용하고, 없으면 [변경 요청]으로 바꾼 칸만 실어 승인을 요청한다.","대기 요청은 구성원마다 1건이다. 대기 중에는 요청자의 칸을 잠그고 [변경 요청 취소]를 둔다. 승인되면 요청에 실은 칸만 적용하고, 거절되거나 취소되면 잠금만 푼다.","관리자가 [승인]을 누르는 순간 대상 모델 배포나 도구가 삭제되었으면 [승인]을 막는다.","크레딧은 호출 한 건이 끝난 시점의 비율로 계산한다. 저장하거나 승인한 다음 시작한 요청부터 새 비율을 쓰고, 처리 중인 요청은 시작할 때의 비율로 끝까지 센다. 지난 호출은 다시 계산하지 않는다.","포함하는 사용량은 에이전트 노드의 LLM·VLM, RAG 검색의 임베딩·리랭커 모델, 출력 노드의 TTS 모델과 STT, Image Generation 모델 사용량, 도구 호출이다.","RAG 검색은 도구 호출로 세지 않고 그 검색에 쓴 임베딩·리랭커 모델 사용량으로 센다.","저장된 응답(응답 캐시)으로 답한 요청은 모델 사용량과 크레딧을 0으로 센다.","워크플로우 테스트의 질문도 같은 방식으로 계산해 보이지만 서비스 사용자의 사용량에는 넣지 않는다.","사용자별 크레딧 한도와 추가 지급, 한도 초과 시 차단과 서비스 사용자 알림은 서비스가 맡는다.","크레딧 관리는 회차가 없고 일 하나가 작업 이력 한 줄이다.","저장하지 않고 나가면 권한 설정과 같은 나가기 창을 띄운다."],"기능":[{"묶음":"크레딧 비율","fn":"FN-CRD-001","이름":"모델 배포 크레딧 비율 지정","동작":"배포중인 모델 배포마다 모델 유형의 단위 하나당 크레딧을 정하고, 호출 한 건의 모델 사용량을 그 비율로 환산한다.","규칙":["단위: LLM·VLM은 입력 10만 토큰과 출력 10만 토큰을 따로, 임베딩·리랭커는 입력 10만 토큰, STT는 오디오 1분, TTS는 1K 글자, Image Generation은 이미지 1장이다.","값은 정수 0~100,000이다. 0은 크레딧 없이 쓴다는 뜻이다.","처음 값: LLM·VLM 입력 100, 출력 300, 임베딩·리랭커 100, STT 1, TTS 1, Image Generation 3.","목록에는 배포중인 모델 배포만 보인다.","권한 설정 변경 권한이 없으면 [변경 요청]으로 한다."],"엣지":["모델 배포를 중지하거나 지워도 정한 비율은 남아, 다시 배포하면 그 값을 쓴다.","실측 사용량이 없고 토큰만 남은 기록은 유형별 어림(STT 출력 150토큰 = 1분, TTS 입력 1토큰 = 2자, 이미지 출력 1,000토큰 = 1장)으로 단위 수를 정한다."],"미정":["크레딧 비율에 편집 점유(편집자 1명)를 둘지, 지금처럼 나중 저장을 남길지 정하지 않았다(N-12)."]},{"묶음":"크레딧 비율","fn":"FN-CRD-002","이름":"도구 크레딧 비율 지정","동작":"배포한 도구마다 1회 호출의 크레딧을 정하고, 도구의 동작마다 따로 정할 수 있다. 동작에 따로 정하지 않으면 그 도구의 값을, 도구 값도 없으면 등록 유형의 처음 값을 쓴다.","규칙":["값은 정수 0~1,000이다.","권한 설정 변경 권한이 있으면 [저장]으로 바로 적용하고, 없으면 [변경 요청]으로 한다.","바뀐 칸마다 작업 이력에 「크레딧 변경」 한 줄을 남긴다."],"엣지":["두 구성원이 같은 칸을 요청하면 나중에 승인한 값이 남는다.","관리자가 바꾸는 사이 다른 구성원의 요청이 기다리면, 승인 때 요청에 실은 칸만 적용하고 관리자가 바꾼 다른 칸은 그대로 둔다."],"미정":[]},{"묶음":"작업 이력","fn":"FN-CRD-003","이름":"작업 이력 조회","동작":"크레딧 비율의 저장 한 번 또는 승인 한 번에 바뀐 칸마다 한 줄로 구분, 항목, 변경 전후, 승인 관리자, 실행 일시, 실행자를 보인다.","규칙":["구분은 「크레딧 변경」이다.","바로 저장하면 실행자는 저장한 사람이고 승인 관리자는 「-」다.","요청이 승인되면 실행자는 요청한 구성원이고 승인 관리자는 승인한 관리자다.","기록은 지우지 않고 화면에는 이력 표시 기간 안의 것만 보인다."],"엣지":["저장하지 않은 변경은 이력에 남지 않는다."],"미정":[]}]},{"모듈":"시스템 자원 관리","코드":"JOB","개요":"AGENTBASE 에 할당된 GPU, CPU, RAM, 스토리지의 사용량을 작업 단위로 집계하고, 자원을 쓰거나 기다리는 작업과 그 사유를 보이며, 할당량 변경을 GPUBASE 에 요청한다.","상태":["대기(자원 부족) → 노드 풀에 자원이 반환됨 → 설치중 또는 실행중(자원 점유 시작)","대기(예약) → 예약 일시 도달, 자원 충분 → 실행 / 자원 부족 → 대기(자원 부족)","대기(피크외 시간) → GPUBASE 가 배정한 일시 도달 → 실행","대기(승인 대기) → 관리자 승인 → 요청한 실행 시점의 대기 또는 실행","대기 → [배포 중지]·[실행 취소]·[예약 취소] → 중지(돌려줄 자원 없음)","자원 한도 변경 요청: 승인 대기 → GPUBASE 승인 → 할당량 적용 / GPUBASE 거절 / 요청자 취소"],"공통":["컴퓨팅 자원 사용량은 자원을 점유한 작업이 요청한 양의 합이고, 스토리지 사용량은 작업이 저장한 산출물과 올린 파일 용량의 합이다.","상태 「대기」는 자원 점유가 0 이다. 대기 사유는 자원 부족, 예약, 피크외 시간, 승인 대기 넷이다.","대기에는 만료가 없다. 사유가 모두 풀리면 자동 실행하고, 취소는 사람이 한다.","남은 GPU 가 요청보다 적으면 대기에 들어간다. 요청이 노드 풀의 GPU 총량보다 크면 대기에 들어가지 않고 처음부터 막는다(「이 풀의 GPU는 모두 n EA입니다.」).","자원 대기 중이거나 예약된 학습의 설정은 고칠 수 없다. [실행 취소] 뒤 고친다.","대기 취소 확인 창을 연 사이 자원이 잡혀 설치가 시작되었어도 확인하면 설치를 취소하고 중지로 처리한다. 권한은 필요 없다.","오버쿼터 회수로 내려간 구성 요소는 대기로 돌아가고 자원이 반환되면 자동으로 다시 배포된다. 상위 워크플로우는 배포중을 유지한다.","오토 스케일링 확장에 자원이 모자라면 기존 레플리카로 계속 서비스하고 확장은 대기했다가 자원이 반환되면 자동으로 늘린다.","실행 일정을 기다리는 데이터 파이프라인은 자원을 이미 점유하므로 자원 대기 작업 수와 대기 필터에서 뺀다.","조회는 모든 구성원이 한다."],"기능":[{"묶음":"자원 사용 현황","fn":"FN-JOB-001","이름":"자원 사용량 조회","동작":"구성원이 시스템 자원 관리를 열면 → GPU, CPU, RAM, 스토리지마다 할당량, 사용량, 잔여량, 사용률을 보이고 → 사용률이 시스템 자원 알림 사용률(스토리지는 스토리지 알림 사용률)에 닿은 자원을 경고로 표시한다.","규칙":["알림 기준은 관리 설정 운영 설정의 값이다(시스템 자원 처음 값 90%, 스토리지 처음 값 80%).","스토리지 95% 는 고정 차단 기준이다. 닿으면 새 파운데이션 모델, 커밋, 검색 DB, 모델 배포 생성을 막고 진행 중인 업로드는 실패한다.","대시보드 자원 위젯과 같은 값이다."],"엣지":["사람이 정리해 95% 아래로 내려가면 생성 차단이 풀린다."],"미정":["(P-37) 스토리지 95% 이상에서 학습 실행과 데이터 파이프라인 전체 실행의 시작도 막을지(권장: 막음)","(P-38) GPUBASE 가 스토리지 할당량을 사용량보다 작게 줄일 때의 처리(권장: 지우지 않고 100% 초과로 보아 95% 차단 적용, 관리자에게 조치 알림)","(N-18) 실패 상태인 작업이 자원을 잡은 것으로 셀지(권장: 실패는 늘 자원 반환)"]},{"묶음":"자원 사용 현황","fn":"FN-JOB-002","이름":"자원 상세 조회","동작":"구성원이 자원 하나를 고르면 → 그 자원의 노드 풀별 현황, 그 자원을 쓰는 작업(많이 쓰는 차례), 사용 이력을 보인다.","규칙":["GPU 상세는 노드 풀마다 할당, 점유, 잔여, 대기 작업 수를 보인다.","작업 자원은 GPU 를 쓰면 GPU, CPU, RAM 을 모두, 쓰지 않으면 CPU 와 RAM 만 적는다.","모델 배포가 점유하는 GPU 는 레플리카 수 × 레플리카 1개의 GPU 다."],"엣지":[],"미정":["사용 이력의 집계 단위와 보이는 기간"]},{"묶음":"자원 사용 현황","fn":"FN-JOB-003","이름":"자원 대기 작업 조회","동작":"구성원이 자원 대기 작업을 열면 → 자원을 기다리는 작업과 필요한 자원을 보이고 → 줄을 고르면 대기 사유 창에서 실행 시점, 대기 사유, 실행 예정 일시, 종료 시각, 대기 시간을 본다.","규칙":["자원 대기 작업과 노드 풀별 대기 작업 수는 승인 대기를 빼고 센다(승인 전에는 자원을 요청하지 않음). 승인되면 그때부터 센다.","실행 예정 일시는 즉시 실행이면 「GPU 반환 시」, 피크외 시간 배정 전이면 「배정 전」이다.","종료 시각은 지정 시각으로 정했을 때만 적는다.","대기 차례(n번째)와 예상 대기 시간은 적지 않는다."],"엣지":["예약 일시가 지났는데 GPU 가 모자라면 사유가 자원 부족으로 바뀌고 실행 예정 일시는 「GPU 반환 시(예약 일시 …)」다.","GPU 는 있는데 CPU 나 RAM 이 모자라도 사유는 「자원 부족」이고 문장이 모자란 자원을 적는다.","홈 자원 대기 작업 위젯과 같은 대상이다."],"미정":["(P-01) 같은 노드 풀의 대기 작업에 자원을 배정하는 차례(권장: 대기 순서대로, 앞 작업이 못 들어가면 들어가는 뒤 작업 먼저)","(P-02) 회수 복귀와 확장 대기를 새 대기보다 먼저 배정할지(권장: 회수 복귀 > 확장 > 신규)","(P-03) 대기 사유가 바뀔 때 작업 이력과 알림을 남길지(권장: 이력만)","(P-04) 자원 부족 대기 진입과 장기 대기 알림(권장: 진입 때 한 번, 기준 시간 초과 때 한 번 더)","(P-05) 예약 종료 시각까지 시작하지 못한 대기의 처리(권장: 종료 시각에 대기를 끝내고 중지)","(P-07) 피크외 시간 배정 일시의 자원 부족 처리(권장: 자원 대기로 전환)","(P-09) 자원 대기·예약 취소를 누가 할 수 있는지(권장: 실행자와 관리자만)","대기 중 노드 풀 할당이 줄어 요청이 풀 총량보다 커질 때의 처리(제안: 대기를 끝내고 실패, 사유 「노드 풀 총량 초과」)"]},{"묶음":"작업 목록","fn":"FN-JOB-004, FN-JOB-005","이름":"작업 목록 조회와 작업 상태 사유 조회","동작":"구성원이 작업 목록을 열면 → 자원을 쓰거나 기다리는 작업을 상태, 작업 유형, 노드 풀, 자원 사용량과 함께 보인다. 상태와 작업 유형으로 거르고 작업 이름, 생성자, 노드 풀로 찾는다. 대기나 실패 작업은 줄마다 대기 사유나 실패 사유를 연다.","규칙":["홈 실행중 작업·문제 발생 위젯에서 들어오면 같은 상태로 걸러진 목록이 열린다.","실패 사유는 시작 실패, 응답 없음, 실행 실패, 스토리지 부족처럼 원인을 적는다."],"엣지":[],"미정":["(N-18) 실패한 채 자원을 잡은 작업을 목록 자원 칸에 셀지"]},{"묶음":"자원 한도 변경 요청","fn":"FN-JOB-006","이름":"자원 한도 변경 요청","동작":"AI 개발자가 [자원 한도 변경 요청]으로 자원별 요청 할당량과 메모를 보내면 → GPUBASE 가 승인하는 순간 할당량이 바뀌고 → 요청자에게 결과 알림이 간다. 승인 대기 중인 요청은 요청자 본인이 [자원 한도 변경 요청 취소]로 취소한다.","규칙":["관리자에게 버튼은 있되 비활성(「관리자는 GPUBASE에서 할당량을 변경합니다.」)이다.","AGENTBASE 관리자는 이 요청을 검토하지 않고, 검토할 요청과 구성원별 승인 대기 수에 넣지 않는다.","요청 할당량은 지금 사용 중인 양보다 적을 수 없다(「{자원} {하한} 이상으로 입력해야 합니다. 요청 할당량은 사용 중인 자원보다 적을 수 없습니다.」).","바꾼 자원이 없으면 [요청]을 막는다.","승인 알림은 「GPUBASE에서 자원 한도 변경을 승인했습니다. 요청한 할당량이 적용되었습니다.」다.","요청, 취소, 승인, 거절은 감사 이력에 남고 처리자는 GPUBASE 다.","AGENTBASE 권한과 무관해 권한이 생기거나 관리자로 지정되어도 자동 취소하지 않는다."],"엣지":["요청을 보낸 뒤 관리자로 지정되면 남은 요청은 GPUBASE 처리 결과만 기다린다."],"미정":["다른 구성원의 요청이 대기할 때 내 요청을 막을지. 세부 정책 둘이 다르다(워크로드에 1건으로 막음 / 구성원마다 1건으로 허용)","GPUBASE 쪽 요청 수신·승인 기능의 제공 시점(D-65 로 GPUBASE 에 요청하기로 함)"]}]},{"모듈":"리포트","코드":"RPT","개요":"고른 대상과 수집 기간의 사용 이력을 보고서 파일로 만든다. 화면 조회는 이력 표시 기간 안의 최근 현황만 보이고, 그보다 오래된 이력은 리포트로 확인한다.","상태":["대기 → 생성 시작 → 실행중 → 종료(다운로드 가능)","실행중 → 생성 실패 → 실패(사유 표시, 다운로드 불가)"],"공통":["리포트 생성은 권한과 자원 점유가 없고 동시 생성 수를 제한하지 않는다.","내용은 생성 시점의 데이터로 고정되어 언제 내려받아도 같다.","리포트는 이력 표시 기간과 상관없이 모든 기록을 쓴다. 대상 작업이 지워져도 적재분은 남는다.","리포트 목록은 모든 구성원이 함께 본다."],"기능":[{"묶음":"리포트 생성","fn":"FN-RPT-001","이름":"리포트 생성","동작":"구성원이 이름, 설명, 대상, 수집 기간을 넣고 [생성]하면 → 리포트가 대기로 목록에 들어가고 → 다른 화면으로 가도 생성은 계속된다.","규칙":["종류와 파일 형식은 생성할 때 고르지 않는다.","수집 기간은 최근 7일, 30일, 90일, 사용자 지정이다(처음 값 최근 30일).","대상의 「감사 이력」은 관리자만 고른다.","이름은 100자 이하, 「/」 금지, 리포트 전체에서 중복을 막는다."],"엣지":["수집 기간 안에 기록이 없으면 머리만 담긴 파일을 만든다."],"미정":[]},{"묶음":"리포트 조회","fn":"FN-RPT-002","이름":"리포트 목록 조회","동작":"구성원이 리포트 목록을 열면 → 모든 구성원의 리포트를 상태로 거르고 리포트 이름이나 생성자로 찾는다.","규칙":["상태는 대기, 실행중, 종료, 실패다."],"엣지":[],"미정":["(N-20) 감사 이력을 담은 리포트를 AI 개발자에게 보일지와 받게 할지(권장: 목록에는 보이되 다운로드 비활성 + 「감사 이력을 담은 리포트는 관리자만 다운로드할 수 있습니다.」)"]},{"묶음":"리포트 조회","fn":"FN-RPT-003","이름":"리포트 다운로드","동작":"구성원이 종료한 리포트의 다운로드에서 CSV 나 PDF 를 고르면 → 그 형식의 파일을 받는다. 같은 리포트를 두 형식으로 각각 받을 수 있다.","규칙":["종료 상태 리포트만 받는다.","다운로드 권한을 거친다. 권한이 없으면 [다운로드 요청] → 관리자 승인 뒤 7일 안에 1회 받는다.","다운로드는 감사 이력에 「다운로드」로 남는다."],"엣지":["승인을 기다리는 동안 그 리포트의 다운로드는 요청자에게 비활성이다."],"미정":[]},{"묶음":"리포트 조회","fn":"FN-RPT-004","이름":"리포트 생성 진행 조회","동작":"목록이 리포트의 생성 상태를 보이고 → 생성이 끝나면 생성자에게 작업 종료 알림이 간다. 실패하면 상태 「실패」에 실패 사유를 함께 보인다.","규칙":["생성자가 리포트 화면에 있으면 알림 대신 「{이름} 리포트 생성이 완료되었습니다.」만 보인다.","실패한 리포트의 다운로드는 비활성 + 「생성에 실패한 리포트입니다.」다. 다시 만들어야 한다."],"엣지":[],"미정":["(N-19) 생성 중지 기능을 둘지(권장: [중지]를 두고 중지하면 파일을 만들지 않으며 그 뒤 삭제 가능)"]},{"묶음":"리포트 조회","fn":"FN-RPT-005","이름":"리포트 삭제","동작":"구성원이 리포트를 삭제하면 → 확인 뒤 목록과 파일이 지워진다.","규칙":["대기·실행중인 리포트는 삭제할 수 없다(「생성 중인 리포트는 삭제할 수 없습니다.」).","삭제한 리포트는 복구하지 않는다."],"엣지":[],"미정":["다른 구성원이 만든 리포트를 지울 수 있는지(지금은 막는 규칙이 없다)"]}]},{"모듈":"알림","코드":"NTF","개요":"승인 요청과 결과, 검수 요청, 작업 시작·종료, 회차 시작, 운영 사건, 자원 사용률, 연결 자원 변경, 권한 변경을 알림으로 전하고, 관리자 승인이 필요한 일을 요청하고 검토하는 자리다.","상태":["알림: 안 읽음 → 선택하거나 [확인함] → 확인함","검토할 요청 알림: 대기 중 → 승인·거절·요청 취소 → 목록에서 빠짐([모두 확인]으로는 빠지지 않음)"],"공통":["알림은 시스템 알림만이다. 공지, 메일, 메신저로 보내지 않는다.","받는 사람: 승인 요청은 관리자 전원, 승인 결과는 요청자, 검수 요청은 검수자, 회차 시작은 모든 구성원, 자원 사용률 초과와 저장 용량은 구성원 전원, 권한 변경과 매핑 확인은 관리자다.","자동 복구, 중단, 응답 지연, 요청 급증, 연결 자원 변경, 데이터 새 회차, 데이터셋 새 버전은 모든 구성원에게 보내고 각자 수신 설정에서 끈다.","작업 시작과 작업 종료는 실행자와 관리자에게 보낸다. 오케스트레이션 종료는 요청자 본인에게만 보낸다.","작업이 끝날 때 실행자가 그 작업 화면에 있으면 화면 안내만 보이고 알림은 보내지 않는다.","같은 대상, 같은 종류의 알림이 30분 안에 다시 나면 한 줄로 묶고 「같은 알림 n건, 처음 {일시}」를 적는다.","자원 사용률 알림은 기준을 넘는 순간 한 번 온다. 기준 이상인 동안은 조치가 필요한 알림에 남고 내려가면 빠진다.","응답 지연은 5분 구간 응답 시간 p95 가 이전 1시간 p95 의 기준 배수(처음 값 2배) 이상, 요청 급증은 5분 구간 요청 수가 이전 1시간 5분 평균의 기준 배수(처음 값 3배) 이상일 때다.","관리자의 승인 요청 알림은 따로 저장하지 않고 대기 중인 요청에서 그때그때 만든다.","알림 목록은 최근 7일을 개수로 자르지 않고 모두 보인다.","구분으로 갈리는 알림 요소는 넷이다: 검토할 요청 구획과 승인 요청 알림(관리자), 승인을 기다리는 내 요청 구획(AI 개발자), 관리자 알림 탭(관리자), 수신 설정의 관리자 묶음(관리자). 권한 유형은 알림 구분에 쓰지 않는다."],"기능":[{"묶음":"알림 패널","fn":"FN-NTF-001","이름":"알림 조회","동작":"구성원이 알림 패널을 열면 → 검토할 요청(관리자), 조치가 필요한 알림, 승인을 기다리는 내 요청(AI 개발자), 시각 묶음(오늘, 어제, 최근 7일) 차례로 알림을 보인다. 알림 종류와 작업 유형으로 거르고, 알림을 고르면 그 작업으로 간다.","규칙":["관리자는 탭 셋(전체, 내 알림, 구성원 알림)을 쓰고 처음 값은 전체다. AI 개발자에게는 탭이 없다.","내 알림은 내가 한 일, 나에게 온 승인 요청, 받는 사람이 정해지지 않은 시스템 알림이다. 구성원 알림은 다른 구성원이 실행한 작업과 그 대상의 사건이고 그 구성원 이름을 적는다.","조치가 필요한 알림은 중단, 지금도 기준 이상인 자원, 저장 용량, 모델 배포가 쓰던 커밋의 삭제, 배포 중인 워크플로우가 연결한 도구의 호출 불가다.","승인을 기다리는 내 요청은 안 읽은 수에 넣지 않는다.","알림 종류 필터에서 알림이 없는 종류는 비활성이다. 작업 유형 필터는 알림을 보내는 메뉴를 모두 둔다."],"엣지":[],"미정":["(C-24) 7일이 지난 알림의 보관과 「이전」 구획 여부(권장: 7일만 두고 이전 구획 걷음)","알림이 가리키던 작업이 삭제되었을 때의 처리(제안: 알림은 남기고 [상세 보기]·[영향 범위] 비활성 + 「삭제된 작업입니다.」)"]},{"묶음":"알림 패널","fn":"FN-NTF-002","이름":"알림 상태 변경","동작":"구성원이 알림 한 건을 확인함으로 바꾸거나 [모두 확인]을 고르면 → 그 알림이 안 읽은 수에서 빠진다.","규칙":["[모두 확인]은 검토할 요청을 뺀 알림만 바꾼다. 검토할 요청은 [검토]로 판단해야 빠진다.","확인 상태는 구성원마다 따로다."],"엣지":[],"미정":[]},{"묶음":"알림 패널","fn":"FN-NTF-003","이름":"알림 수신 설정","동작":"구성원이 [수신 설정]에서 알림 종류를 활성화·비활성화하면 → 즉시 저장되고 → 끈 종류는 알림 목록과 알림 수에서 빠진다.","규칙":["끌 수 없는 알림은 승인 요청(관리자), 검수 요청(검수자), 회차 시작(모든 구성원), 매핑 확인(관리자) 넷이다.","끌 수 있는 묶음은 내 작업(승인 결과, 작업 시작, 작업 종료), 자원과 연결(자동 복구와 중단, 응답 지연과 요청 급증, 시스템 자원 사용률과 저장 용량, 연결 자원 변경과 데이터 새 회차·데이터셋 새 버전), 관리자(구성원 작업, 권한 변경, 관리자에게만) 셋이다.","관리 설정 운영 설정에는 수신 설정을 두지 않는다."],"엣지":["저장 용량 알림을 꺼도 95% 생성 차단은 그대로이고, 막힌 버튼이 이유를 알린다.","끈 동안 생긴 알림은 다시 켜면 보관 기간 안의 것이 나타난다(지우지 않고 거르기만 함).","관리자가 AI 개발자로 바뀌면 관리자 묶음은 사라지고 그 값은 다시 관리자가 될 때 쓰인다."],"미정":[]},{"묶음":"알림 패널","fn":"FN-NTF-004","이름":"영향 범위 조회","동작":"구성원이 알림의 [영향 범위]를 고르면 → 알림 대상 자원을 쓰는 작업을 연결 사슬을 따라 보인다.","규칙":["연결 사슬은 서비스 API 오픈 → 워크플로우 → 모델 배포·RAG·도구다. 간접 대상인 서비스 API 오픈과 그 대상을 부르는 워크플로우까지 넣는다."],"엣지":[],"미정":[]},{"묶음":"관리자 승인","fn":"FN-NTF-005","이름":"승인 요청","동작":"권한이 없는 구성원이 [{동작} 요청]을 고르면 → 값이 있는 일은 설정 창 → [다음], 값이 없는 일은 요청 창이 바로 열리고 → 메모와 함께 [요청]하면 승인 대기가 되고 관리자 전원에게 승인 요청 알림이 간다.","규칙":["요청 종류와 권한: 학습 실행·학습 중지·배포·오토 스케일링 적용·오토 스케일링 설정 변경(컴퓨팅 자원 사용), 리더보드 등록·등록 해제(리더보드 등록), 다운로드(다운로드), 권한 값 변경·사용자·권한 API 연결·크레딧 비율 변경(권한 설정 변경), 서비스 연결·오픈·변경·오픈 중지·워크플로우 오픈·오픈 해제·그룹 설정·이름 변경·해제·이동(서비스 API 오픈).","대기 단위는 공통 규칙의 단위를 따른다(작업, 모델 배포, 권한 설정 전체, 크레딧 관리 전체, 서비스, 구성원).","요청 뒤 안내는 「{요청}을 요청했습니다. / 승인 결과는 알림으로 전달합니다.」다.","대기 중에는 그 작업의 삭제를 막는다(「{요청자}님의 {일} 요청이 승인을 기다리고 있습니다. 요청이 취소되거나 처리된 뒤에 삭제할 수 있습니다.」).","오토 스케일링은 자원을 늘리는 조작만 요청이다. 최소·최대 레플리카를 줄이거나 기준만 바꾸면 바로 저장하고, 비활성화는 요청 없이 바로 하며 지금 레플리카 수를 유지한다.","폴더·여러 파일 다운로드 승인은 요청 때의 파일 목록과 각 파일의 회차에 고정한다."],"엣지":["다운로드 요청은 구성원마다 따로라 같은 파일에 다른 구성원 요청이 대기해도 막지 않는다.","서비스 API 연결 요청이 대기 중이어도 사용자·권한 API 연결 요청은 보낼 수 있다.","리더보드 등록 요청과 배포 요청은 단위가 달라 같은 모델 배포에 함께 대기할 수 있다.","내 오토 스케일링 요청이 대기 중이면 스위치와 설정 아이콘이 모두 요청 취소 창을 연다."],"미정":["(C-27) 배포 중지에 컴퓨팅 자원 사용 권한이 필요한지(배포 중지 요청은 없앰으로 정리됨, 권한 무관 실행인지 권한자만인지)","학습 중지를 요청 대상으로 계속 둘지(배포 중지 요청을 걷은 것과 맞출지)"]},{"묶음":"관리자 승인","fn":"FN-NTF-006","이름":"요청 검토","동작":"관리자가 검토 진입점에서 [검토]를 고르면 → 「{요청} 검토」 창에서 요청 내용, 요청자, 메모를 보고 → [승인]하면 시스템이 요청한 값 그대로 바로 실행하고, [거절]하면 대상은 요청 전 상태로 돌아간다. 요청자에게 결과 알림이 간다.","규칙":["검토 진입점은 알림 패널 검토할 요청의 [검토], 홈 승인 대기 위젯(누르면 알림 패널), 관리 설정 구성원 권한의 승인 대기 수와 줄의 [검토], 요청 대상 상세의 [요청 검토] 넷이다. 모두 같은 검토 창을 연다.","요청 대상 상세에서는 대상의 원래 버튼을 본래 글자로 비활성으로 남기고 [요청 검토]를 더한다.","검토 창은 승인 순간 대상 상태와 요청자 권한을 다시 확인하고, 실행할 수 없으면 [승인]을 비활성 + 이유로 둔다.","거절은 검토 메모의 거절 사유가 있어야 한다(「거절하려면 검토 메모에 거절 사유가 있어야 합니다.」).","다운로드는 승인 뒤 요청자가 받고, 자원 한도 변경은 AGENTBASE 관리자가 검토하지 않는다."],"엣지":["관리자 둘이 같은 요청을 동시에 열면 먼저 처리한 판단만 유효하고, 나중 창은 [승인][거절] 비활성 + 「{처리자}님이 이미 승인한 요청입니다.」/「…거절한 요청입니다.」다.","검토 중에 요청이 취소되거나 권한 생김으로 자동 취소되면 [승인][거절] 비활성 + 「요청자가 취소한 요청입니다.」다.","관리자가 AI 개발자로 바뀌는 순간 열어 둔 검토 창의 [승인][거절]은 비활성이 된다.","요청을 보낸 구성원이 관리자로 지정되면 그 요청은 남고, 본인이 직접 검토한다.","구성원 권한 승인 대기 창의 [이동]은 대상 화면으로 가서 그 요청의 검토 창을 연다."],"미정":["(N-15) 승인 전에 대상 상태가 바뀌어 요청한 일을 실행할 수 없게 된 경우(권장: 시스템이 요청을 자동 취소하고 사유를 남김)","(P-10) 예약이 담긴 요청을 승인하는 순간 예약 일시가 지났을 때(권장: 승인을 막고 이유 표시)"]},{"묶음":"관리자 승인","fn":"FN-NTF-007","이름":"요청 취소","동작":"요청자가 [{일} 요청 취소]를 고르면 → 확인 창(「관리자에게 보낸 {대상}의 {요청} 요청을 취소합니다. 요청을 취소하시겠습니까?」) 뒤 요청이 취소되고 → 관리자 알림 목록에서 바로 빠지며 대상은 요청 전 상태로 돌아간다.","규칙":["요청 취소는 요청자 본인만 한다.","취소 알림은 누구에게도 보내지 않는다.","감사 이력에 결과 「요청 취소」, 처리자는 요청자 본인으로 남는다."],"엣지":["단위 안의 요청이 취소되면 그 순간 다른 구성원의 막힌 버튼이 풀린다."],"미정":[]}]},{"모듈":"관리 설정","코드":"SET","개요":"AGENTBASE 관리자가 운영 기준값, 구성원의 구분과 권한, 승인 요청·다운로드·권한 변경의 감사 이력, 시스템 정보를 관리한다. 관리자만 접근한다.","상태":["구분: AI 개발자 → 관리자가 구분 칸에서 관리자 지정 → 관리자(즉시 적용, 감사 이력 「적용」)","구분: 관리자(AGENTBASE 에서 지정) → 다른 관리자 또는 본인이 AI 개발자로 변경 → AI 개발자(마지막 관리자는 불가)","구분: GPUBASE 그룹 관리자 이상 → 관리자로 고정(바꿀 수 없음)"],"공통":["관리 설정 메뉴는 관리자에게만 보인다. AI 개발자가 주소로 들어오면 막힘 안내를 보인다.","관리 설정의 변경은 승인 요청을 거치지 않는다(관리자만 바꾸므로).","권한 유형 값과 구분 변경은 저장 없이 즉시 적용하고, 운영 설정은 [저장]으로 한 번에 적용한다.","감사 이력 대상은 승인 요청, 다운로드(권한으로 바로 받은 것 포함), 권한 설정 저장, 구성원 권한 변경이다.","감사 이력 결과는 승인 대기, 실행, 실행 전, 거절, 요청 취소, 만료, 적용 일곱이다.","이력 표시 기간은 화면에 보이는 기간일 뿐이고 기록은 지우지 않는다."],"기능":[{"묶음":"운영 설정","fn":"FN-SET-001","이름":"이력 표시 설정","동작":"관리자가 표시 회차 수와 이력 표시 기간을 바꾸고 [저장]하면 → 모든 구성원 화면에 바로 적용된다. 작업 이력은 그 회차 수만큼, 이력 화면은 그 기간 안의 기록만 보인다.","규칙":["표시 회차 수는 3~50회차(처음 값 10)다.","이력 표시 기간은 30일, 90일, 180일, 1년, 3년(처음 값 180일)이다.","작업 이력, 감사 이력, 시스템 로그, 서비스 사용 이력, API Key 발급 내역은 기간이 지나도 지우지 않는다.","리포트와 감사 이력 내보내기, 회차 롤백, 회차 선택 다운로드는 기간과 상관없이 모든 기록과 회차를 쓴다."],"엣지":["기간을 줄여도 지우지 않으므로 확인 창이나 유예가 없다. 다시 늘리면 지난 기록이 바로 다시 보인다.","표시 기간 밖의 회차는 회차 선택 목록의 「이전 회차 보기」로 연다.","작업이나 파일을 지우면 그 이력은 화면에서 빠지지만 감사 이력의 삭제 기록과 리포트 적재분은 남는다."],"미정":[]},{"묶음":"운영 설정","fn":"FN-SET-002","이름":"알림 기준 설정","동작":"관리자가 알림 기준값을 바꾸고 [저장]하면 → 다음 판정부터 그 기준으로 알림을 보낸다.","규칙":["시스템 자원 알림 사용률 50~99%(처음 값 90), 스토리지 알림 사용률 50~94%(처음 값 80), 응답 지연 알림 기준 1.5~10배(처음 값 2), 요청 급증 알림 기준 1.5~10배(처음 값 3)다.","스토리지 95% 는 고정 차단 기준이다. 닿으면 새 생성을 막는다. 알림 사용률은 95% 이상으로 정할 수 없다.","토큰 알림 기준, 업로드 상한, 권한 상한 칸은 두지 않는다.","바꾼 항목이 없으면 [저장]은 비활성 + 「변경한 항목이 없습니다.」이고, 바꾼 동안 「변경한 항목 n개」와 [취소]를 둔다."],"엣지":["저장하지 않고 다른 탭이나 메뉴로 나가면 바꾼 값은 버린다."],"미정":["(N-14) 두 관리자가 운영 설정을 동시에 고칠 때의 처리(권장: 화면 전체 1개 편집 점유)","장기 자원 대기 알림의 기준 시간 항목을 둘지와 처음 값(P-04)"]},{"묶음":"운영 설정","fn":"FN-SET-003","이름":"운영 설정 변경 이력 조회","동작":"관리자가 변경 이력을 열면 → 저장마다 항목별 한 줄(일시, 변경자, 항목, 변경 전, 변경 후)을 보이고 → 한 건을 고르면 같은 저장에서 함께 바뀐 항목을 본다.","규칙":["관리자만 접근한다."],"엣지":[],"미정":[]},{"묶음":"구성원 권한","fn":"FN-SET-004","이름":"구성원 권한 조회","동작":"관리자가 구성원 권한을 열면 → 구성원마다 구분, 권한 유형 여섯의 값, 승인 대기 수를 보인다. 구분으로 거르고 사용자나 메일로 찾는다.","규칙":["관리자가 맨 위, 그다음 AI 개발자 차례다.","라벨링 검수 열은 라벨링 검수 기능을 쓰는 동안 보인다. 감춰도 저장된 값은 남는다."],"엣지":[],"미정":[]},{"묶음":"구성원 권한","fn":"FN-SET-005","이름":"관리자 지정","동작":"관리자가 구성원의 구분을 관리자나 AI 개발자로 바꾸면 → 저장 없이 즉시 적용되고 → 감사 이력에 「구성원 권한 변경」 결과 「적용」으로 남는다. 알림은 보내지 않는다.","규칙":["GPUBASE 그룹 관리자 이상은 관리자로 고정되어 구분 메뉴가 없다.","관리자가 한 명뿐이면 AI 개발자 선택지는 비활성 + 「관리자가 한 명뿐이라 AI 개발자로 변경할 수 없습니다. 다른 구성원을 관리자로 변경한 뒤 변경합니다.」다. 그룹 관리자 이상도 관리자 수에 넣는다.","관리자로 지정하면 권한 여섯이 모두 있고 스위치는 켜진 채 잠긴다(「관리자는 모든 권한이 있습니다.」).","관리자로 지정된 구성원의 대기 요청은 남고 본인이 직접 검토한다."],"엣지":["관리자가 자기 자신을 AI 개발자로 내릴 수 있다(마지막 관리자가 아니면). 내리는 즉시 관리 설정 메뉴가 사라진다.","워크로드 생성자가 만들 때 고른 관리자도 다른 관리자가 AI 개발자로 내릴 수 있다."],"미정":["(N-16) 관리자를 AI 개발자로 내린 직후 권한 값(권장: 모두 꺼진 값으로 두고 다시 줌)"]},{"묶음":"구성원 권한","fn":"FN-SET-006","이름":"권한 변경","동작":"관리자가 AI 개발자의 권한 스위치를 바꾸면 → 즉시 적용되고 그 구성원 화면의 버튼이 [{동작}]과 [{동작} 요청] 사이에서 바로 바뀐다. 감사 이력에 변경 전후 값이 남는다.","규칙":["권한 유형은 서비스 API 오픈, 다운로드, 컴퓨팅 자원 사용, 리더보드 등록, 권한 설정 변경, 라벨링 검수 여섯이다.","권한 설정 변경은 사용자·권한 API 연결과 변경, 동기화, RAG·도구·워크플로우의 권한 값 편집, 크레딧 비율 변경을 포함한다.","권한 체계와 토큰 한도는 서비스가 정해 AGENTBASE 권한에 들지 않는다.","권한을 주면 그 권한으로 보낸 대기 요청은 자동 취소되고 감사 이력에 「요청 취소」로 남는다."],"엣지":["권한을 회수해도 대기 요청과 아직 쓰지 않은 승인은 유효하다."],"미정":[]},{"묶음":"구성원 권한","fn":"FN-SET-007","이름":"승인 대기 요청 검토","동작":"관리자가 구성원의 승인 대기 수를 고르면 → 그 구성원의 대기 요청 창이 열리고 → 줄마다 [검토]로 검토 창을 열거나 [이동]으로 대상 화면에 가서 그 요청의 검토 창을 연다.","규칙":["승인 대기 수에서 GPUBASE 가 처리하는 자원 한도 변경 요청은 뺀다.","관리 설정 메뉴는 AI 개발자에게 보이지 않는다."],"엣지":[],"미정":["(N-17) 관리자 줄의 승인 대기 열이 무엇을 셀지(권장: 「-」, 검수 대기는 알림이 맡음)"]},{"묶음":"감사 이력","fn":"FN-SET-008, FN-SET-009","이름":"감사 이력 조회와 상세 조회","동작":"관리자가 감사 이력을 열면 → 승인 요청, 다운로드, 권한 설정 저장, 구성원 권한 변경 기록을 사용자, 요청 일시, 처리 일시, 실행 일시, 결과와 함께 보인다. 한 건을 고르면 단계별 처리자, 일시, 메모를 본다.","규칙":["승인 후 실행하는 일(학습 실행, 배포, 오토 스케일링, 리더보드 등록·해제, 권한 값 변경, 서비스 쪽 요청)은 승인 시각이 곧 실행 시각이다.","다운로드 승인이 7일 경과나 파일 회차 변경으로 끝나면 「만료」이고 상세에 끝난 이유를 적는다.","관리자가 직접 받은 다운로드는 승인자가 그 관리자다.","자원 한도 변경의 처리자는 GPUBASE 다.","감사 이력 내보내기는 이력 표시 기간과 상관없이 모든 기록을 쓴다."],"엣지":["요청자가 그룹을 떠나거나 대상이 지워져도 기록은 남는다."],"미정":[]},{"묶음":"시스템","fn":"FN-SET-010, FN-SET-011","이름":"업데이트 조회와 구성요소 버전 조회","동작":"관리자가 시스템 탭을 열면 → 설치된 버전, 최신 버전, 업데이트 채널 상태, 설치 일시, 최근 점검과 릴리스 목록(버전, 설치 여부, 릴리스 일시)을 보이고, 구성요소마다 버전, 빌드, 상태, 인스턴스, 빌드 일시를 보인다.","규칙":["값은 설치본이 준다. 화면에서 업데이트를 실행하지 않는다."],"엣지":[],"미정":["폐쇄망에서 업데이트 채널이 연결되지 않을 때 최신 버전 칸의 표시","구성요소 상태가 정상이 아닐 때 알림을 보낼지"]},{"묶음":"시스템","fn":"FN-SET-012, FN-SET-013","이름":"라이선스 조회와 오픈소스 라이선스 조회","동작":"관리자가 라이선스를 보면 → 유효 여부와 남은 날, 에디션, 발급 대상, 라이선스 키(앞뒤 마디만), 발급일, 만료일, 구성원과 서비스 API 의 지금 사용량 대비 한도를 보인다. 오픈소스 라이선스는 이름, 버전, 라이선스, 출처를 찾아 본다.","규칙":["라이선스 키는 앞뒤 마디만 보이고 가운데는 가린다."],"엣지":[],"미정":["라이선스 만료나 구성원·서비스 API 한도 초과 때 막는 조작과 알림"]}]},{"모듈":"공통","코드":"COM","개요":"GPUBASE 계정으로 AGENTBASE 에 들어오는 진입, 모듈 이동, 상단바, 모든 모듈이 함께 쓰는 조회와 다운로드, 승인 요청과 관리자 검토의 공통 규칙을 정의한다.","상태":["승인 요청: 승인 대기 → [승인] → 승인(시스템이 요청한 값 그대로 실행)","승인 요청: 승인 대기 → [거절](거절 사유 필수) → 거절(대상은 요청 전 상태)","승인 요청: 승인 대기 → [요청 취소](요청자 본인) → 요청 취소","승인 요청: 승인 대기 → 관리자가 요청자에게 그 권한을 줌 → 요청 취소(자동)","다운로드 승인: 승인 → 요청자가 1회 받음 → 실행","다운로드 승인: 승인 → 7일 경과 또는 파일 회차 변경 → 만료(다시 요청)"],"공통":["구성원 구분은 관리자와 AI 개발자 둘이다. 관리자는 권한 유형 여섯을 모두 가진다.","권한 유형은 서비스 API 오픈, 다운로드, 컴퓨팅 자원 사용, 리더보드 등록, 권한 설정 변경, 라벨링 검수 여섯이다. 라벨링 검수만 요청이 없고(권한이 없으면 불가), 나머지 다섯은 권한이 없으면 요청이다.","권한 판정 단위는 그 조작의 권한 유형 하나다. 권한이 있으면 버튼이 [{동작}], 없으면 [{동작} 요청]이다.","권한 변경은 관리자가 스위치를 바꾸는 순간 적용되고, 그 구성원의 버튼과 열린 설정 창의 마지막 버튼도 즉시 바뀐다.","값을 정하는 일(학습 실행, 배포, 오토 스케일링 적용, 최소·최대 레플리카를 늘리는 오토 스케일링 설정 변경, 리더보드 등록, 서비스 API 오픈·설정 변경, 권한 값 변경, 크레딧 비율 변경)은 설정 창을 거친다. 설정 창의 마지막 버튼은 권한이 있으면 [{동작}], 없으면 [다음] → 「{동작} 요청」 창이다.","값이 없는 일(학습 중지, 리더보드 등록 해제, 다운로드, 오픈 중지, 워크플로우 오픈·오픈 해제)은 요청 창이 바로 열린다. 요청 창 뒤에 확인 창은 없다.","요청 창은 메모(선택, 500자)를 받는다. 검토 창은 검토 메모(500자, 거절 때 필수)를 받는다.","요청 이름은 실제 일 이름이다(권한 이름이 아니다). 창 제목, 알림, 검토 창, 버튼, 감사 이력이 같은 이름을 쓴다.","배포 중지 요청은 없다. 배포 중지와 자원을 점유하기 전 취소([배포 중지], [실행 취소], [예약 취소])는 요청을 거치지 않는다.","승인 대기 요청은 단위마다 1건이다. 컴퓨팅 자원 사용 요청은 작업 1개에 1건(일이 달라도 함께 셈), 리더보드 등록·해제는 모델 배포 1개에 1건, 권한 값 변경은 권한 설정 전체에 1건, 크레딧 비율 변경은 크레딧 관리 전체에 1건, 서비스 쪽 요청은 서비스 1개에 1건, 서비스 연결은 서비스 API 연결과 사용자·권한 API 연결을 따로 1건씩, 다운로드는 구성원마다 1건이다.","단위 안에 다른 구성원의 요청이 대기하면 같은 일의 버튼은 관리자를 포함해 비활성이고 이유는 「{요청자}님의 {일} 요청이 관리자의 승인을 기다리고 있습니다.」다.","요청이 대기하는 동안 요청한 설정 값은 요청자, 다른 구성원, 관리자 모두 바꿀 수 없고 그 대상은 삭제할 수 없다.","요청자에게는 같은 자리 버튼이 [{일} 요청 취소]이고, 같은 대상의 다른 컴퓨팅 자원 버튼은 비활성이다.","승인하면 시스템이 요청한 값 그대로 바로 실행한다. 그 순간 자원이 모자라면 대기(자원 부족)로 들어가 자원이 반환되면 자동 실행한다. 다운로드는 승인 뒤 요청자가 직접 받고, 자원 한도 변경은 GPUBASE 가 승인해야 적용된다.","거절하면 대상은 요청 전 상태로 돌아가고, 새로 만들려던 모델 배포는 만들지 않은 것으로 처리한다. 작업 이력에는 반영 상태 「반려({사유})」를 남긴다.","검토 창은 승인 순간 대상 상태와 요청자 권한을 다시 확인하고, 실행할 수 없으면 [승인]을 비활성으로 두고 이유를 보인다.","관리자가 구성원에게 권한을 주면 그 권한으로 보낸 대기 요청은 모두 자동 취소된다(사유 「권한이 생겨 요청 없이 실행할 수 있습니다.」, 처리자는 권한을 바꾼 관리자). 관리자에게 취소 알림은 보내지 않는다.","구성원을 관리자로 지정해도 그 구성원의 대기 요청은 남고, 본인이 직접 승인하거나 거절한다.","권한을 회수해도 대기 요청은 그대로 두고, 승인되었으나 아직 쓰지 않은 승인은 끝날 조건까지 유효하다.","요청자가 취소하면 관리자 알림 목록과 알림 수에서 바로 빠진다. 취소 결과 알림은 누구에게도 보내지 않는다.","승인 대기로 멈춰 있던 학습과 모델 배포는 요청 취소나 거절 뒤 요청 전 상태로 돌아간다.","승인 요청의 상태는 승인 대기, 승인, 거절, 요청 취소 넷이다. 감사 이력의 결과는 승인 대기, 실행, 실행 전, 거절, 요청 취소, 만료, 적용 일곱이다.","다운로드는 AGENTBASE 에서 파일로 내려받는 모든 일(데이터 관리 파일·데이터셋, RAG 문서, 커밋, 학습 지표, 시스템 로그와 에러 로그, 리포트, 보안 평가 문장, 에이전트 패키지)에 적용한다. 빈 양식, 예시 파일, Service Manual 은 제외한다.","다운로드는 누가 했든 감사 이력에 「다운로드」 한 건으로 남고, 대상 작업이 있으면 작업 이력에도 남는다.","관리 설정 메뉴는 관리자에게만 보인다. 이것이 「숨기지 말고 비활성」 규칙의 유일한 예외이고, 메뉴 안의 다른 조작은 비활성 + 이유로 둔다.","이력 표시 기간은 화면에 보이는 기간일 뿐이고 작업 이력, 감사 이력, 시스템 로그, 서비스 사용 이력, API Key 발급 내역은 지우지 않는다.","편집 점유가 막는 조작은 숨기지 않고 비활성 + 「{이름}님이 편집 중입니다.」다(편집 점유 모듈)."],"기능":[{"묶음":"AGENTBASE 진입","fn":"FN-COM-001, FN-COM-002","이름":"GPUBASE 계정 사용과 AGENTBASE 접속","동작":"사용자가 GPUBASE 워크로드에서 AGENTBASE 를 열면 → 시스템이 GPUBASE 계정과 역할을 읽어 구분(관리자, AI 개발자)을 정하고 → 홈으로 들어간다. AGENTBASE 에 따로 가입하거나 로그인하지 않는다.","규칙":["들어올 수 있는 계정은 그 워크로드가 속한 그룹의 구성원 가운데 워크로드 생성자와 공개 설정 대상이다.","워크로드 전체 공개는 쓰지 않는다. 로그인이 없으면 구분을 정할 수 없기 때문이다.","GPUBASE 그룹 관리자 이상은 AGENTBASE 관리자로 고정된다. 그룹 범위 조건은 따로 두지 않는다.","워크로드 생성자는 만들 때 자신을 관리자로 둘지 AI 개발자로 둘지 정한다. 다른 관리자가 AI 개발자로 내릴 수 있다.","그 밖의 구성원은 AI 개발자로 들어오고, 관리자가 관리 설정에서 관리자로 지정할 수 있다.","AGENTBASE 에서 실행한 학습과 배포에는 실행한 구성원의 GPUBASE 역할 제한이 걸린다."],"엣지":["GPUBASE 역할은 다음 진입 때 다시 읽는다. 그룹 관리자 이상이 되면 관리자로 고정되고, 그 아래로 내려가면 AGENTBASE 에서 지정한 구분(없으면 AI 개발자)으로 돌아간다."],"미정":["GPUBASE 역할 제한이 학습·배포 도중 바뀔 때 이미 시작한 작업은 시작할 때의 제한으로 끝까지 가는지(제안: 다음 실행부터 적용)","구성원이 GPUBASE 그룹에서 빠질 때 그 사람의 대기 요청, 편집 점유, 자원 대기 처리(제안: 요청 자동 취소, 점유·대기 해제, 실행 중인 작업은 유지)"]},{"묶음":"AGENTBASE 진입","fn":"FN-COM-003","이름":"AGENTBASE 진입 확인","동작":"AGENTBASE 에 들어올 때마다 시스템이 작업에 필요한 자원(노드 풀 할당, 스토리지)과 연결(오케스트레이터 등)의 준비 상태를 확인하고 → 준비되지 않은 항목과 이유를 안내한다.","규칙":["준비되지 않아도 진입은 막지 않는다."],"엣지":[],"미정":["준비되지 않은 항목이 있을 때의 화면 동작(제안: 조회는 허용하고 그 자원이나 연결이 필요한 실행 버튼만 비활성 + 이유, 준비되면 다음 갱신 때 풀림)","확인하는 항목의 목록과 각 항목이 막는 조작의 대응"]},{"묶음":"AGENTBASE 진입","fn":"FN-COM-004","이름":"운영 자원 유지","동작":"GPUBASE 에서 워크로드를 종료해도 → 실행 중인 모델 배포, 워크플로우, 서비스 API 는 내리지 않고 → 서비스 호출이 끊기지 않는다. 화면 없이 시스템이 처리한다.","규칙":["워크로드 종료는 사용자 화면의 접속만 끝낸다. 점유한 자원은 그대로 유지한다."],"엣지":[],"미정":["워크로드 종료 중에 진행 중이던 학습, 전체 실행, 검색 DB 업데이트 같은 실행형 작업의 처리"]},{"묶음":"화면 이동","fn":"FN-COM-005, FN-COM-006, FN-COM-007","이름":"모듈 진입, 계층 경로, 상위 계층 복귀","동작":"사용자가 메뉴의 모듈을 고르면 그 모듈 목록으로 들어간다. 상단바는 지금 위치를 메뉴 > 상세 > 탭 세 마디 경로로 보이고, 마디를 고르면 그 계층으로 간다. 상세 화면에서 상위 계층 복귀를 고르면 목록으로 돌아간다.","규칙":["관리 설정 메뉴는 관리자에게만 보인다. AI 개발자에게는 메뉴 줄이 없다.","AI 개발자가 주소로 관리 설정에 직접 들어오면 본문 대신 「{메뉴 이름}은 관리자만 사용할 수 있습니다.」와 「내 승인 요청과 알림 수신 설정은 [알림]을 선택해 확인합니다.」를 보인다.","같은 작업 안 탭 이동은 편집 점유의 이탈이 아니다."],"엣지":["관리자가 관리 설정을 보는 중에 AI 개발자로 바뀌면 메뉴 줄이 사라지고 열린 화면은 막힘 안내로 바뀐다. 저장하지 않은 운영 설정 변경은 반영하지 않는다.","AI 개발자가 관리자로 지정되면 새로 고침 없이 관리 설정 메뉴가 나타난다.","편집 중인 수정 창이 있는 채로 다른 모듈로 이동하면 편집 점유가 풀리고 저장하지 않은 입력은 버린다(캔버스는 자동 저장으로 남는다)."],"미정":["(N-13) 메뉴 정본 이름(RAG/지식베이스, 워크플로우/에이전트, 도구/도구·MCP, 관리 설정/시스템 설정). 결정 전까지 기능정의서 이름을 쓴다(D-61 보류)","관리자 전용 메뉴만 있던 묶음에서 AI 개발자에게 빈 묶음 이름을 남길지"]},{"묶음":"상단바","fn":"FN-COM-008, FN-COM-009","이름":"워크로드 이름 표시와 내 계정 조회","동작":"상단바는 지금 접속한 워크로드 이름을 보인다. 사용자가 내 계정을 열면 이름, 메일, 구분을 확인하고 AGENTBASE 에서 나간다.","규칙":["AGENTBASE 에서 나가면 편집 점유를 모두 놓는다. 실행 중인 작업과 업로드는 멈추지 않는다."],"엣지":[],"미정":["나가기 때 진행 중인 업로드의 처리(브라우저가 올리는 파일이 끊기는 경우)"]},{"묶음":"상단바","fn":"FN-COM-010","이름":"상태 갱신 주기 설정","동작":"사용자가 갱신 주기를 고르면 → 시스템이 그 주기마다 작업 상태와 지표를 다시 모으고 마지막 수집 시각을 갱신한다. 수동이면 [즉시 수집]을 누를 때만 모은다.","규칙":["주기는 15초(처음 값), 30초, 1분, 수동이다.","고른 주기는 이 브라우저에 남고 모든 화면에 같게 적용된다.","요청 수와 응답 시간은 5분 구간으로 모으고, 진행 중인 구간의 값은 그 구간이 끝나야 확정된다.","작업 종료 알림은 갱신 주기와 상관없이 온다."],"엣지":["수동이면 실행이 끝나도 [즉시 수집] 전까지 화면은 마지막으로 모은 상태로 남는다."],"미정":[]},{"묶음":"상단바","fn":"FN-COM-011","이름":"데이터 업로드 현황","동작":"사용자가 파일 업로드를 시작하면 → 다른 화면으로 이동해도 업로드는 계속되고 → 상단바 업로드 현황에서 파일별 진행과 완료·중지·실패 수를 본다. 파일 줄의 [중지] 또는 [전체 중지]로 업로드를 멈춘다.","규칙":["중지는 「업로드를 중지하시겠습니까?」 확인 창을 거친다. 중지한 파일은 「중지됨」이고 완료한 파일은 남는다.","진행 표시는 완료 건수, 업로드 중 건수, 진행률, 남은 시간이다(남은 시간은 업로드에만 쓴다)."],"엣지":["네트워크가 끊기거나 스토리지 사용률이 95% 에 닿으면 진행 중이던 파일은 실패로 끝나고 저장하지 않는다. 어느 화면에 있든 업로드 실패 안내가 열린다.","커밋 파일 업로드를 중지하면 커밋을 더하지 않고 베이스 모델만 남는다."],"미정":[]},{"묶음":"상단바","fn":"FN-COM-012","이름":"접속자 표시","동작":"상단바는 같은 워크로드에 접속한 구성원 수를 보이고, 목록을 열면 구성원마다 지금 위치, 편집 중인 작업, 관리자 여부를 보인다.","규칙":["목록 차례는 나, 편집 중인 사람, 내가 보는 화면과 같은 자리에 있는 사람, 나머지다.","편집 중인 사람은 「편집 중」과 편집 위치를 함께 보인다.","홈 접속 현황 위젯과 같은 값이다."],"엣지":["접속 종료 판정이 늦으면 그 사람은 3분 무조작으로 편집 점유를 놓을 때까지 편집 중으로 보인다."],"미정":[]},{"묶음":"사용 안내","fn":"FN-COM-013","이름":"Service Manual 다운로드","동작":"사용자가 메뉴의 Service Manual 을 고르면 사용 안내서 PDF 를 바로 내려받는다.","규칙":["다운로드 권한을 거치지 않고 감사 이력에도 남기지 않는다(제품 안내 파일이다)."],"엣지":[],"미정":[]},{"묶음":"사용 안내","fn":"FN-COM-014","이름":"튜토리얼과 Quick guide","동작":"튜토리얼을 시작하면 → 시연용 목업 화면으로 옮겨 화면별 설명을 차례로 보고 → 끝나면 목업에 남은 것을 비우고 시작한 화면으로 돌아온다. Quick guide 는 실제 화면에서 안내 대상을 직접 선택하고 값을 넣어 끝까지 실행해 본다.","규칙":["튜토리얼은 실제 데이터와 무관하고 아무것도 만들어지지 않는다. 시작 전에 지금 역할과 설정을 목업에 베낀다.","Quick guide 의 조작은 클릭(대상 선택), 입력(값을 넣고 [다음]), 대기(조건이 되면 자동으로 다음) 셋이다. 대상을 찾지 못하면 [건너뛰기]다.","Quick guide 로 만든 항목은 마치거나 중간에 끝낼 때 묻지 않고 삭제한다.","Quick guide 진행은 그 브라우저 탭에만 남아 새로 고침해도 이어진다.","튜토리얼을 시작하면 진행 중인 Quick guide 는 끝난다."],"엣지":["Quick guide 도중 탭을 닫으면 만든 항목이 남을 수 있다."],"미정":["Quick guide 가 실제로 자원을 점유하는 실행(배포, 학습)을 할 때 권한과 자원 부족 처리, 탭을 닫아 남은 실습 항목의 정리"]},{"묶음":"공통 조회","fn":"FN-COM-015","이름":"기간 선택","동작":"사용자가 기간을 고르면 → 그 화면의 지표와 목록을 그 기간으로 다시 집계한다.","규칙":["기간은 최근 7일, 30일, 90일, 사용자 지정이다.","기간 선택은 화면 표시만 바꾸고 저장된 기록은 바꾸지 않는다.","이력 표시 기간 밖의 기록은 화면 조회에서 빠지고 리포트로 확인한다."],"엣지":[],"미정":[]},{"묶음":"공통 조회","fn":"FN-COM-016","이름":"시스템 로그 조회","동작":"사용자가 [시스템 로그]를 열면 → 기간을 고르고, 회차가 있는 작업은 실행 회차나 배포 회차를 고른 뒤 → 그 범위의 로그를 본다. [다운로드]로 파일로 받는다.","규칙":["기록이 없으면 [시스템 로그]는 비활성 + 이유다(예: 「아직 배포하지 않아 시스템 로그가 없습니다.」).","회차 선택지는 그 기간에 기록이 있는 회차뿐이다. 없으면 「기간 안에 실행 회차가 없습니다」다.","실행 중에 생기는 기록은 상단바 갱신 주기에 맞춰 이어 붙고, 끝까지 내리면 다음 30건을 읽는다.","다운로드는 다운로드 권한을 거친다. 권한이 있으면 「다운로드」 확인 창(대상, 용량) → [다운로드], 없으면 [다운로드 요청] → 승인 뒤 1회 받는다."],"엣지":["모델 배포와 RAG 는 생성 기록 줄이 늘 있어 비활성이 되지 않는다."],"미정":[]},{"묶음":"공통 조회","fn":"FN-COM-017","이름":"에러 조회","동작":"사용자가 에러 로그를 열면 → 에러와 경고를 수준으로 나눠 요청 내용과 함께 보이고 → 원인을 파악한다.","규칙":["요청 형식 오류, 서버 오류, 실행 실패는 에러다. 권한 거부와 호출 한도 초과는 경고다."],"엣지":[],"미정":["(C-09) 권한·한도로 막힌 요청을 에러율에 넣을지(권장: 에러율에서 빼고 「차단」 수로 따로 셈)"]},{"묶음":"공통 조회","fn":"FN-COM-018, FN-COM-019","이름":"지표 크게 보기와 표시 지표 선택","동작":"사용자가 지표를 크게 보기로 열면 추이와 시점별 세부 값을 확대해 본다. 모니터링과 학습 화면에서 표시할 지표를 고르면 그 지표만 그린다.","규칙":["표시 지표 선택은 화면 표시만 바꾸고 수집하는 지표는 바꾸지 않는다."],"엣지":[],"미정":["표시 지표 선택을 구성원마다 남길지, 화면을 다시 열면 처음 값으로 돌아갈지"]},{"묶음":"공통 조회","fn":"FN-COM-020","이름":"용량 상세","동작":"사용자가 용량 상세를 열면 → 그 작업이 쓰는 저장 용량을 원본 데이터, 데이터셋, 체크포인트, 모델, 검색 DB, 로그 같은 구성으로 나눠 본다.","규칙":["작업의 저장 용량은 스토리지 사용량에 들어간다(시스템 자원 관리와 같은 셈)."],"엣지":[],"미정":[]}]},{"모듈":"편집 점유","코드":"LCK","개요":"같은 대상을 여러 구성원이 동시에 고쳐 덮어쓰지 않도록 대상마다 편집자를 한 명만 둔다. 먼저 변경을 시작한 구성원이 편집자가 되고 나머지는 뷰어다.","상태":["뷰어 → 아무도 편집하지 않을 때 변경 조작 시작 → 편집자","뷰어 → 다른 구성원이 먼저 편집자가 됨 → 다른 사람 편집 중(변경 조작 비활성)","편집자 → [편집 완료] / 작업 화면 이탈 / 수정 창 닫음(데이터 관리) / 접속 종료 / 조작 없음 3분 → 뷰어","다른 사람 편집 중 → 그 구성원의 점유 해제 → 뷰어"],"공통":["점유 단위: 파운데이션 모델, 모델 배포, RAG, 도구는 작업 1개, 워크플로우·데이터 파이프라인은 작업 1개, 서비스 API 오픈은 서비스 1개, 권한 설정은 전체 1개, 데이터 관리는 데이터 1개(파일, 폴더)다.","3분과 30초는 고정 값이다. 관리 설정 항목이 없다.","편집 시작과 종료는 작업 이력에 남기지 않는다.","인계 요청과 강제 인계는 없다. 점유자가 자리를 비우면 3분 무조작이 풀어 준다.","오케스트레이션 실행 중에는 편집자 여부와 상관없이 모든 화면이 보기 전용이다."],"기능":[{"묶음":"편집 중 상태","fn":"FN-LCK-001","이름":"편집 점유","동작":"구성원이 아무도 편집하지 않는 대상에서 변경을 시작하면 → 시스템이 그 구성원을 편집자로 정하고 → 다른 구성원 화면에 편집자 이름을 보인다. 편집자가 [편집 완료], 이탈, 접속 종료, 3분 무조작 가운데 하나에 이르면 점유를 놓는다.","규칙":["파운데이션 모델, 모델 배포, RAG, 도구, 서비스 API 오픈은 변경 조작을 시작하는 순간 편집자가 된다.","워크플로우와 데이터 파이프라인 설정 탭은 [편집]으로 편집 모드에 들어가는 순간 편집자가 되고 [편집 완료]로 끝난다.","새로 만든 작업은 만든 사람이 점유한 채로 들어간다. 데이터 파이프라인과 워크플로우는 편집 모드로 열린다.","권한 설정은 권한 값 변경을 시작하는 순간 편집자가 된다(권한이 없는 구성원 포함).","권한 설정 변경 요청을 보내면 점유를 놓는다. 대기 중에는 요청한 값을 아무도 바꿀 수 없다.","데이터 관리는 데이터 한 개의 상세 열기, 수정, 이동, 삭제 동안 점유한다.","2분 30초에 「30초 뒤 뷰어로 전환합니다.」, 3분에 「3분 동안 조작이 없어 뷰어로 전환했습니다.」와 대상별 둘째 줄을 보인다.","조작은 마우스 이동·누름·휠·스크롤, 키보드, 터치다. 자동 새로 고침, 진행률, 알림 도착은 조작이 아니다."],"엣지":["데이터 파이프라인의 정보 탭 수정과 설정 탭 편집 모드는 같은 점유 하나다.","데이터 파이프라인 편집 모드가 3분 무조작으로 끝나면 [편집 완료]와 같이 처리한다. 설계를 고쳤으면 [편집 완료]가 지우는 실행 결과도 지워진다.","3분이 지나면 열린 수정 창을 닫고 저장하지 않은 입력은 버린다(임시 보관 없음). 캔버스는 자동 저장이라 남는다.","같은 구성원이 같은 작업을 브라우저 탭 둘로 열면 점유는 하나이고, 무조작 판정은 탭마다 따로라 조작이 없는 탭이 먼저 점유를 놓을 수 있다.","브라우저가 비정상 종료되면 접속 종료로 보고 점유를 놓는다. 판정이 늦으면 3분 무조작으로 놓인다.","점유 중에 편집자의 권한이 회수되어도 점유는 유지된다. 권한이 필요한 조작만 요청으로 바뀐다.","점유 중에도 이미 시작한 학습, 배포, 업로드, 검색 DB 업데이트는 계속된다."],"미정":["(N-14, N-12) 크레딧 비율과 운영 설정처럼 점유가 없는 공유 설정을 동시에 고칠 때의 처리(권장: 권한 설정과 같이 화면 전체 1개 점유)"]},{"묶음":"편집 중 상태","fn":"FN-LCK-002","이름":"뷰어 변경 차단","동작":"편집자가 아닌 구성원이 변경 조작을 하려 하면 → 시스템이 막고 「{이름}님이 편집 중입니다.」를 보인다. 조회는 그대로 허용한다.","규칙":["뷰어에게 막는 조작은 수정, 삭제, 실행, 중지, 저장, 업로드, 연결 변경, 데이터 파이프라인 표본 실행, RAG 테스트 질문, 워크플로우 테스트, 보안 평가 [실행], 자원 점유 전 취소([배포 중지], [실행 취소], [예약 취소])다.","막힌 조작은 숨기지 않고 비활성 + 「{이름}님이 편집 중입니다.」이며, 상세 제목 아래에도 같은 문장을 다른 안내보다 먼저 보인다.","막힌 조작을 누르면 「{이름}님이 편집 중입니다. / 편집이 끝난 뒤에 수정할 수 있습니다.」를 보인다.","조회, 메뉴 이동, 필터, 검색, 기간, 정렬, 조회 창, 복사는 뷰어도 한다."],"엣지":["데이터 관리에서 점유 중인 파일은 이름 변경, 편집, 이동, 삭제, 복사, 다운로드, 업로드 덮어쓰기와 체크 선택까지 막는다.","중복 파일 확인 창에서 기존 파일을 다른 구성원이 편집 중이면 [덮어쓰기]만 비활성이고 [새 이름으로 저장], [건너뛰기]는 고를 수 있다.","편집자가 점유를 놓으면 그 순간 뷰어의 막힌 조작이 풀린다."],"미정":[]}]}]')}]);